window.__D("text/torat-chaim/c031",{"p":[[2300550581,"דוקא כברכה גשמיות כו'. אך ודאי יש טעם [וכוונה] למה כינו חכמי התלמוד לבחי' אוא\"ס ב\"ה בשם זה הקב\"ה דוקא להיותו כולל ב' הפכים הללו דקדוש וברוך יחד, ומבחי' קדוש נמשך בחי' ברוך וזהו פי' הפשוט דקודב\"ה דהיינו אע\"פ שהוא קדוש ומובדל לגמרי מ\"מ נמשך להיות בבחי' ברוך כו'. וביאור הדבר הנה ידוע בפי' אוא\"ס שכולל ב' דברים<sup data-n=\"3641\">353</sup> א' בבחי' העלי' למעלה בעילוי אחר עילוי שזהו מה שהוא קדוש ומובדל בכמה מיני הבדלות זו למעלה מזו והכל בחי' רוממות העצמו' ממש שאין לו שיעור למעלה מעלה שזהו פי' אור א\"ס [אין סוף] וקץ למעלה מעלה כו', וכל מה שנמשך מאורו להיות מקור למקור לכל השתלשלו' דקו\"ח הי' אחר הצמצו[מי]ם רבים שהא[י]ר רק ע\"י בחי' אותיות משמו הגדול שהוא בחי' מל' דא\"ס שקודם הצמצום דקו\"ח כידוע, וכל מה שנשתלשל מאור המצומצם הזה (שהוא בחי' הרושם הנשאר בטה\"ע אחר שנסתלק אור הראשון כו') בקו\"ח עד ע\"ס דאצי' ובי\"ע הכל כלא ממש חשיב נגד אור העצמות כו', ונק' קדוש הוי' <span data-k=\"pg\">תסג</span> ּ שלמעלה משם הוי' דאצי' כו', וגם למעלה מעלה בקדושה אחר קדושה באין שיעור למעלה כנ\"ל. ואמנם [כי] כל יכול הוא ע\"כ גם בבחי' ההעלאה ברוממות העצמו' ממש משם יכול הוא להיות בבחי' הירידה וההמשכה מן ההעלם דסדכ\"ס כו', ובא בגילוי אור דוקא גם אחר ריבוי הצמצומים והעלמות הנ\"ל, וכמאמר במקום גדולתו ממש אתה מוצא ענוותנותו כו', והוא ענין בחי' אור החסד שבא\"ס שנק' אין סוף להתפשטותו למטה שזהו הכלל דכל הגבוה<sup data-n=\"3642\">354</sup> גבוה [יותר] יותר יוכל לירד ולהתמשך למטה מטה דוקא. והוא ענין ובחי' הברכה שנמשך ומתברך ממקורו העצמי דהיינו דוקא מן העלם דעצמות הרוממות לבא בגילוי כמעיין הנובע מן ההעלם כו' כמאמר דאיהו ברוך<sup data-n=\"3643\">355</sup>, וכמו והמלך שלמה ברוך<sup data-n=\"3644\">356</sup> לשון נפעל שנתברך ממקורו שנמשך משם כל ברכה בתוס' מרובה דוקא.\n<b>והענין</b> הוא כידוע דעצמות אוא\"ס ממש הוא למעלה גם מבחי' קדוש וברוך שהוא בחי' העלי' והירידה דאו\"ח ואו\"י בחי' חו\"ג דעצמות א\"ס הנ\"ל שאינו רק בחי' העלם וגילוי ולא בחי' מהו\"ע ית' ממש שהוא למעלה מבחי' העלם וגילוי למעלה מבחי' מעלה ומטה דחו\"ג שנק' עו\"ר ועו\"ת<sup data-n=\"3645\">357</sup> כמו המגביהי לשבת המשפילי<sup data-n=\"3646\">358</sup> כו' כי קמי' ממש בחי' מעלה ומטה שבעצמות אור א\"ס שוין, ואין זה שייך רק לגבי בחי' השתלשלו' דקו\"ח<sup data-n=\"3647\">359</sup> כמשי\"ת<sup data-n=\"3648\">360</sup> (כמ\"ש בע\"ח). ואמנם אדרבה היא הנותנת",[["3641","353","<b>בפי' אוא\"ס שכולל ב' דברים</b>: ראה גם לקמן פ' תצוה שכג, א. וש\"נ."],["3642","354","<b>שזהו הכלל דכל הגבוה</b>: ראה לעיל פ' שמות כא, ב הערה 863."],["3643","355","<b>דאיהו ברוך</b>: זהר תרומה קסב, א. (רע\"מ) ואתחנן רסד, ב."],["3644","356","<b>והמלך שלמה ברוך</b>: מל\"א ב, מה. ראה גם לעיל פ' בשלח קס, ג. וש\"נ."],["3645","357","<b>עו\"ר ועו\"ת</b>: עומק רום ועומק תחת."],["3646","358","<b>המגביהי לשבת המשפילי</b>: תהלים קיג, ה. ו."],["3647","359","<b>מעלה ומטה. . דקו\"ח</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א, ענף ב. שעה\"י קכ, ב הערה 9."],["3648","360","<b>כמשי\"ת</b>: אה: בלבד. ב: כל חד(!)."]]],[2300550592,"דמטעם זה כל יכול הוא להגביל ולהמשיך מאור עצמותו כמו שהוא למעלה במקורו<sup data-n=\"3649\">361</sup> ממש גם למטה ממש כמו<sup data-n=\"3650\">362</sup> שצמצם שכינתו בין ב' בדי הארון בהיכל ק\"ק הגם דשה\"ש כו', הרי לא<sup data-n=\"3651\">363</sup> נתפס מהו\"ע ית' במקום זה דוקא. אך אין זה רק במקום שבחי' פנימי' מהו\"ע ית' יוכל להתפשט<sup data-n=\"3652\">364</sup> שם לפי שזהו מקומו העצמי כמו היכל המלך המיוחד אליו לדור ישכון<sup data-n=\"3653\">365</sup> פנימי' אור כבודו [בו] דוקא, והיינו בהיכל ק\"ק דוקא לפי<sup data-n=\"3654\">366</sup> שהי' שם הארון והלוחות וע\"כ הי' שם גילוי שכינה והתגלות אור פנימי' עצמותו ממש. וכמו\"כ הוא ית' נתפס ממש בד\"א של הלכה עכשיו משחרב בהמ\"ק כו', דהנה בחי' ההמשכה מקדוש לברוך כו' שזהו מאור העצמות ממש שנק' הקב\"ה בכלל זה אינו נתפס ומלובש רק בחכ' דתורה דוקא כידוע דג' קשרים הן אורייתא מתקשראה בקוב\"ה וישראל מתקשר[א]ן באורייתא. והנה מה שאורייתא מתקשרא' בקוב\"ה זהו בבחי' התקשרות עצמ[י'] ממש דהיינו שכל בחי'<sup data-n=\"3655\">367</sup> פנימי' ועצמו' דא\"ס ב\"ה מלובש בהן ונתפס בהן שהרי נק' שמותיו העצמים ממש כנ\"ל, ומטעם זה נק' הלכה בשם מקום ד\"א דוקא. כי באמת הרי אמר בזהר דגם דאיהו תפיס בכ\"ע ולמתב\"כ<sup data-n=\"3656\">368</sup> כו', וכן ארז\"ל הוא מקומו ש\"ע<sup data-n=\"3657\">369</sup> ואין העולם מקומו, ועכ\"פ אין כל ההשתל' נק' מקומו שיהי' נתפס בהן ממש שהרי א' דלית מ[ד]ת\"ב כו'. ע\"כ ממילא מובן דמה שאמר דאיהו תפיס בכ\"ע, וכן מה שארז\"ל שנק' מקומו ש\"ע אין זה התפיסא אמיתי' במקומו כלל, כי גם השמים ושמי השמים כו'), אבל בהיכל ק\"ק וכן בד\"א של הלכה הוא נתפס ממש כנ\"ל, כי זהו בחי' מקומו העצמי ממש. כמו מקומו של אדם הוא ד\"א<sup data-n=\"3658\">370</sup> דוקא כידוע בענין טלטול ד\"א דשבת<sup data-n=\"3659\">371</sup> שעז\"א אל יצא <span data-k=\"pg\">928</span> ּ איש ממקומו<sup data-n=\"3660\">372</sup> (כי על שטח ד' אמות שסביבו מתפשט או\"מ דיחידה<sup data-n=\"3661\">373</sup> שבאדם), וא\"כ במקום זה דד\"א נתפס האדם כולו מראשו לרגלו בלי יוכל להיות במקום אחר זולתו. כך הוא בחי' ד\"א של הלכה שאוא\"ס כמו שהוא ממש נתפס בד\"א הללו כידוע דאורייתא היכלא עילאה דקוב\"ה וע\"כ במקום שלומדים ד\"ת נק' ד\"א של הלכה (כי אין הילוך פחות מד\"א<sup data-n=\"3662\">374</sup> והלכה [ד\"א] שלו המיוחד[י'] לו, וכמו הליכות עולם לו<sup data-n=\"3663\">375</sup> הליכות אלי<sup data-n=\"3664\">376</sup> כו'. וע\"כ נק' ד' אמות של הלכה דוקא שהוא בחי' מקומו העצמי שא\"א להיות נתפס בשום מקור<sup data-n=\"3665\">377</sup> אחר זולתו מטעם שההלכות הן בחי' פנימי' ועצמ[י'] רצונו וחכמתו משום דאורייתא מתקשרת בקוב\"ה (וכמו הנה מקום אתי<sup data-n=\"3666\">378</sup>, וכן ברוך המקום<sup data-n=\"3667\">379</sup>, וכמו שא' ברוך כבוד ה' ממקומו<sup data-n=\"3668\">380</sup> היינו בחי' מקומו העצמי",[["3649","361","<b>במקורו</b>: אב: במקומו."],["3650","362","<b>כמו</b>: שם: גם. ה: כבפנים."],["3651","363","<b>לא</b>: שם: ליתא."],["3652","364","<b>להתפשט</b>: שם: להתפס. ה: כבפנים."],["3653","365","<b>לדור ישכון</b>: א: לדור שם ישכון. ה: לסור וישכון."],["3654","366","<b>לפי</b>: ה: ניתוסף: כבודו."],["3655","367","<b>בחי'</b>: שם: ליתא. ה: כבפנים."],["3656","368","<b>דאיהו תפיס בכ\"ע ולמתב\"כ </b>[אב: למדת\"ב]: ראה זהר (רע\"מ) פינחס רכה, א."],["3657","369","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."],["3658","370","<b>מקומו של אדם הוא ד\"א</b>: ראה אנציק' תלמודית בערכו וש\"נ."],["3659","371","<b>טלטול ד\"א דשבת</b>: ראה שו\"ע אדה\"ז הל' שבת סשמ\"ט, ס\"א."],["3660","372","<b>אל יצא איש ממקומו</b>: בשלח טז, כט."],["3661","373","<b>ד' אמות. . או\"מ דיחידה</b>: ראה גם לעיל פ' בשלח קעט, ד. וש\"נ."],["3662","374","<b>אין הילוך פחות מד\"א</b>: ראה גם שו\"ע אדה\"ז שבהערה 371. הל' השכמת הבקר מהדו\"ב ס\"א, ס\"ז. ס\"ב ס\"ה. מהדו\"ק ס\"א, ס\"ז. ס\"ב, ס\"ז."],["3663","375","<b>הליכות עולם לו</b>: חבקוק ג, ו."],["3664","376","<b>הליכות אלי</b>: תהלים סח, כה."],["3665","377","<b>מקור</b>: אב: מקום."],["3666","378","<b>הנה מקום אתי</b>: תשא לג, כא."],["3667","379","<b>ברוך המקום</b>: מדות ספ\"ה. הגש\"פ (פסקא זו)."],["3668","380","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב."]]],[2300550603,"הנ\"ל, כמו בהיכל ק\"ק ויותר למעלה הימנו כי בהיכל ק\"ק הי' שורה בבחי' או\"פ<sup data-n=\"3669\">381</sup> דחכ', ובד\"א של הלכה הרי הוא נתפס בבחי' מקיף למעלה ממנו כו').\n<b>וזהו</b> שבזמן בהמ\"ק הי[ו] ישראל נקראים אחים מטעם הכרובים שהיו פורשים כנפים ופניהם איש אל אחיו דוקא וכנ\"ל, כך גם בזמן הגלות יוכל להיות בחי' יחוד קודב\"ה ושכינתי' הן כנס\"י בבחי' פב\"פ דוקא להיות נק' אחים וריעים ממש, והוא ע\"י שמתקשרי' באורייתא, והתקשרות זו ג\"כ בבחי' פנימית ועצמ[י'] בנש\"י בס\"ר אותיות התורה<sup data-n=\"3670\">382</sup> כידוע שהן נתפסים [ג\"כ] בד\"א של הלכה כמו דקודב\"ה נתפס<sup data-n=\"3671\">383</sup> בד' אמות הללו. וע\"כ הרי נק' אחים וריעים להקב\"ה ע\"י שנתפסים בהתקשרות שכלם ודעתם בהעמקה גדולה באותיות התורה (שנק' היכלא עילאה), והקב\"ה שוכן ונתפס ג\"כ בחכ' זו שבתו', ה\"ז נק' אחים וריעים כמו שבת אחים וריעים יחד בהיכל אחד וללמוד דבר א' שמתקשרי' שניהם ונתפסים במקום א' ובדבר א' שהוא בתורה דוקא שהוא בחי'<sup data-n=\"3672\">384</sup> הממוצע דאורייתא מתקשרא' בקודב\"ה וישראל מתקשרי' באורייתא (רק שהתקשרות דקודב\"ה באורייתא מלמעלה למטה והתקשרות דישראל באורייתא מלמטה למעלה [ו]יחדיו יהיו תמים שנתפסים בהיכל א', והן ד' אמות של הלכה שנק' מקומו העצמי). וכמו גם בכל מי שלומד וקורא ושונה דבר ה' זו הלכה שמתקשרת ונתפסת [ב]ד' אמות של הלכה זו וגם הקב\"ה יושב ושונה כנגדו אותו דבר הלכה ממש כמ\"ש ה' צלך<sup data-n=\"3673\">385</sup> כו', א\"כ זהו בחי' יחוד האמיתי פב\"פ כאחים וריעים כמו שהי' יחוד פב\"פ אמיתי בזמן מתן תורה ממש כנ\"ל וד\"ל.\n<b>ומעתה</b> יתורץ ג\"כ ענין הנ\"ל במ\"ש למען אחיי כו' למען בית ה' כו', דהל\"ל תחלה למען בית כו', ועוד למה חלק לשלום וטוב לשנים כו'. אך הענין הוא מובן ע\"פ כל הנ\"ל [ד]במצות ת\"ת דבחי' החכמה דתו' בחי' ממוצע שמתקשרי' ונתפסים בה קודב\"ה וישראל יחד כו'<sup data-n=\"3674\">386</sup>, הרי זהו בבחי' יחוד דאו\"א דאצי' שנק' תרדל\"מ כו' דאוא\"ס מתגלה בחכ' בבחי' או\"י ושורש נש\"י בבינה שמקבל מחכמה כו'. וזהו שהקדים למען אחיי דוקא שזהו כמו בזמן הגלות בד' אמות של הלכה במקום היכל ק\"ק (בהיכל ק\"ק דבריאה שמתייחדים שם זו\"נ דאצי' כידוע בענין סמיכת גאולה לתפלה<sup data-n=\"3675\">387</sup> ) <span data-k=\"pg\">תסד</span> ּ והוא מ\"ש אדברה נא",[["3669","381","<b>או\"פ</b>: ה: אור פשוט."],["3670","382","<b>והתקשרות. . בנש\"י בס\"ר אותיות התורה</b>: ראה גם של\"ה מס' פסחים מצה עשירה קסג, ב. קסה, ב. לעיל פ' שמות ב, ד. וש\"נ."],["3671","383","<b>נתפס</b>: אב: ליתא. ה: כבפנים."],["3672","384","<b>בתורה דוקא שהוא בחי'</b>: א: בחי'. ה: בתו' שהוא פנימי'."],["3673","385","<b>ה' צלך</b>: תהלים קכא, ה. ראה גם לעיל פ' וארא סה, ד. וש\"נ."],["3674","386","<b>כו'</b>: אב: כנ\"ל."],["3675","387","<b>בהיכל ק\"ק דבריאה. . סמיכת גאולה לתפלה</b>: ראה פע\"ח (שער הק\"ש) ש\"ח, פכ\"ט. סידור האריז\"ל במקומו. מאמרי אדה\"א דברים ח\"ג ע' א'מ. וש\"נ."]]],[2300550612,"שלום בך כמ\"ש או יחזיק במעוזי יעשה שלום לי כו' ב' שלימות כנ\"ל, יחו\"ע בפמליא של מעלה ויחו\"ת בחכ' דתושבע\"פ שנק' הלכה אותיות הכלה<sup data-n=\"3676\">388</sup> כידוע כמ\"ש ורב שלום בניך<sup data-n=\"3677\">389</sup> כו' וד\"ל. אך זהו היחוד במשפיע ומקבל בבחי' מקיף דד\"א של הלכה שנק' מקומו כו' כמו שזו\"נ עולים בהיכלות דאו\"א להתייחד<sup data-n=\"3678\">390</sup> כמו בס\"ת בהיכל<sup data-n=\"3679\">391</sup>, ואמנם בזמן בהמ\"ק ע\"י הכרובים שהיו פניהם איש אל אחיו כנ\"ל הי' בחי' יחוד פנימי יותר והוא בבחי' פנימי' דע\"י וא\"א שלמעלה מיחוד דאו\"א. וז\"ש למען בית ה' כו' אבקשה טוב לך בחי' הטוב דצ\"ע דיסוד<sup data-n=\"3680\">392</sup> דע\"י שיתגלה לע\"ל במשיח ובנין בהמ\"ק לע\"ל שיהי' נצחי', וזהו טוב לך ליום שכולו טוב<sup data-n=\"3681\">393</sup> שהוא בחי' העדן דעוה\"ב שהוא בחי' טוב העצמי שהוא טוב נצחי' כידוע, אבל זהו למען בית הוי' אלקינו דוקא כשיבנה בהמ\"ק ויהי' כרובים ופניהם כו', והוא לפי שבחי' התענוג הפשוט שבעצמות אוא\"ס ממש שנק' שעשועי המלך בעצמו<sup data-n=\"3682\">394</sup> ממש הוא למעלה גם מהעונג העליון דחכ' דתורה הקדומה שהרי אמר ואהי' אצלו אמון כו' שעשועים שירד להשתעשע בשעשועים הנ\"ל בתורה [ו]א\"כ עיקר עלי' דחכ' דתורה הוא בשעשועי' העצמי' שנק' טוב בעצם כמו בעוה\"ב שנק' עדן הפשוט כו', שהוא בחי' עונג הנעלם שבעצמות ממש (שזהו בחי' קדוש וברוך שנתצמצם בתו\"מ שלמטה). וזהו שהיו הכרובים דוקא פורשי כנפיים למעלה על הכפורת שהי' מגיע בעצמות השעשועים בעצמות דאוא\"ס שלמעלה גם מבחי' כתר דחכמה דתורה שהוא הכפורת [ש]על הארון כנ\"ל, וז\"ש סוככים בכנפיהם כו'), כענין כנפי נשרים דצדיקים לע\"ל, והוא לפי שבחי' הקטנות דמוחין דכרובים אנפי זוטרי דוקא הוא שעולה בבחי' או\"ח למעלה גם מכתר דחכמה להיות בבחי' מקיף על הכפורת כמ\"ש סוככים בכנפיהם כו' (וכמ\"ש במ\"א בענין ונערים ממשתה נגינתם כו' שעולה למעלה מחתנים בחופתם בבחי' גדלות המוחין כו'). וזהו כרוב אותיות ברוך<sup data-n=\"3683\">395</sup> שבבחי' אור שממשיך ברכה ותורה כענין רוכב על כרוב קל ושט כו' שממשיך ממקום שעולה שם. וזהו ג\"כ ע\"י בחי' צמצום העיון להיות ליבון הלכתא בדיוק גדול מצד בחי' הקטנות דוקא יעלה בזה למעלה בעצמות העונג שבעצמות שלמעלה ממקור הח\"ע כנ\"ל וכמ\"ש בעדן עין לא<sup data-n=\"3684\">396</sup> כו' יעשה למחכה לו ואמר בזהר דדי[י]ק מילין דחכמתא<sup data-n=\"3685\">397</sup> דוקא בבחי' או\"ח ומטעם הנ\"ל וד\"ל וכמ\"ש במ\"א וד\"ל.",[["3676","388","<b>הלכה אותיות הכלה</b>: ראה פע\"ח (שער הנהגת הלימוד) שי\"ז. לעיל פ' שמות ג, ב. וש\"נ."],["3677","389","<b>ורב שלום בניך</b>: ישעי' נד, יג."],["3678","390","<b>שזו\"נ עולים. . להתייחד</b>: ראה ע\"ח (שער העקודים) ש\"ו, ספ\"ח."],["3679","391","<b>בס\"ת בהיכל</b>: ראה ביאוה\"ז אחרי עו, א."],["3680","392","<b>הטוב. . דיסוד</b>: ראה זהר נח ס, א. הנסמן במאמרי אדה\"א קונטרסים ע' רכד."],["3681","393","<b>ליום שכולו טוב</b>: נוסח הרחמן (שבברכת המזון) ליו\"ט."],["3682","394","<b>שעשועי המלך בעצמו</b>: ראה עמק המלך שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ. קונטרסים ע' שמה. וש\"נ."],["3683","395","<b>כרוב אותיות ברוך</b>: ראה גם שערי אורה ס, ב ובהערה 35."],["3684","396","<b>בעדן עין לא</b>: ראה ברכות לד, א. ישעי' סד, ג."],["3685","397","<b>יעשה למחכה. . דדי[י]ק מילין דחכמתא</b>: ישעי' שם. ראה זהר ח\"ש קל, ב. לעיל פ' שמות ח, ג. וש\"נ."]]],[2300550056,"<b>פרשת תצוה </b>\nב\"ה\n<span data-k=\"pg\">930</span> ּ<b>ואתה</b> תצוה<sup data-n=\"3686\">1</sup> את בנ\"י<sup data-n=\"3687\">2</sup> ויקחו אליך שמן זית זך כתית למאור כו', הנה ארז\"ל תרי\"ג מצות נאמרו למשה בסיני<sup data-n=\"3688\">3</sup> בא חבקוק והעמידן על אחת<sup data-n=\"3689\">4</sup> שנאמר וצדיק באמונתו יחי'<sup data-n=\"3690\">5</sup>. ויש להבין איך העמיד לכל המצות על מצוה זאת דאמונה הלא האמונה האלקי' ירושה היא מאברהם<sup data-n=\"3691\">6</sup> כידוע ולא שייך למנות בכלל מצוה שהמצוה היא הציווי על המעשה ותלוי בבחירה אבל האמונה האלקית כמו טבע בנפשותינו מצד הירושה כו'. ועוד מה ראי' זו מצדיק שבאמונתו יחי' שהצדיק זהו שקיים כל המצות דוקא כו', ואם מפני שהאמונה הוא יסוד חזק לכל המצות ולכך אמר שהעמידן על אחת כמו שהכל הולך אחר המעמיד<sup data-n=\"3692\">7</sup> (וזהו שצדיק יסוד עולם) הרי א' אלה המצות אשר יעשה האדם וחי בהם<sup data-n=\"3693\">8</sup> וכו'.\n<b>אך</b> הנה יש להקדים מ\"ש ויהי ערב ויהי בקר<sup data-n=\"3694\">9</sup> יום אחד דאין יום שאינו כלול מערב ובוקר דוקא שאז נק' יום אחד וא\"א להיות יום בלא לילה מקודם וכמו שא' בחולין במשנה (סוף או\"ב)<sup data-n=\"3695\">10</sup> דבמעשה דבראשית היום הולך אחר הלילה שקדמה כמ\"ש ויהי ערב ואח\"כ ויהי בוקר אז נק' יום אחד, ולכך דרשו מזה דכברייתו ש\"ע ברישא חשוכא והדר נהורא<sup data-n=\"3696\">11</sup> כו'. ואע\"פ שמדת יום ומדת לילה מחולקים ומובדלים זה מזה כמו שהבדיל בין האור והחושך ויקרא לאור יום<sup data-n=\"3697\">12</sup> ולחושך קרא לילה (וכמו שאו' בערבית גולל אור מפני חשך וחשך מפני אור ומעביר יום ומביא לילה ומבדיל בין יום ולילה כו', דמ\"ש ויהי ערב ברישא חשוכא זהו שגולל אור הראשון מפני חושך ואח\"כ גולל חושך מפני אור דבוקר ומעביר יום כו' שגולל אור דיום מפני חשך דלילה כו' שכ\"ז נכלל בענין ההבדלה בין מדת יום למדת לילה וכידוע בס' הקבלה די\"ב שעו' הלילה הן בי\"ב צירופי' דשם אדנ\"י ויב\"ש היום בי\"ב צירופי' דשם הוי'<sup data-n=\"3698\">13</sup> כו'. אך עכ\"ז מתכללים גבורות דלילה עם בחי' חסדים דיום ובאמצעות שניהם יחד נק' יום שהרי א\"א להיות כל כ\"ד שעות יום וכל כ\"ד שעות לילה), והוא לפי שא\"א להיות בחי' התפשטות דחסד אל",[["3686","1","<b>ואתה תצוה</b>: מיוסד על מאמר ד\"ה זה משנת תקס\"ב. הנחת כ\"ק אדה\"א נדפסה במאמרי אדה\"ז תקס\"ב ח\"א ס\"ע קסג. וחסר סיום. ובשלימות ובשינויים קלים נדפסה שם בח\"ב ע' שמו. ראה גם ד\"ה נר חנוכה תשכ\"ד. ראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["3687","2","<b>ואתה תצוה את בנ\"י</b>: תצוה כז, כ."],["3688","3","<b>תרי\"ג מצות נאמרו למשה בסיני</b>: ראה מכות כג, סע\"ב. וראה גם הנסמן לעיל פ' בשלח קפט, ג."],["3689","4","<b>בא חבקוק והעמידן על אחת</b>: מכות כד, א."],["3690","5","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["3691","6","<b>האמונה האלקי' ירושה היא מאברהם</b>: ראה גם לעיל פ' בא קטז, ג. וש\"נ."],["3692","7","<b>שהכל הולך אחר המעמיד</b>: שבת טו, ב."],["3693","8","<b>אלה המצות. . בהם</b>: חיבור שני כתובים בחוקותי כז, לד. אחרי יח, ה [בדילוג]. ראה גם הנסמן לעיל פ' בשלח קעה, ד."],["3694","9","<b>ויהי ערב ויהי בקר</b>: בראשית א, ה. ראה גם זהר בראשית מו, א."],["3695","10","<b>בחולין במשנה (סוף או\"ב)</b>: פג, סע\"א."],["3696","11","<b>דכברייתו ש\"ע. . והדר נהורא</b>: ראה שבת עז, ב."],["3697","12","<b>ויקרא לאור יום</b>: בראשית א, ה [בדילוג]."],["3698","13","<b>די\"ב שעו'. . אדנ\"י. . הוי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, ב</a>) ובס' שיעורים בתניא שם ע' 547 בהערה. מכתב לר\"י פייגין נדפס ברשימות חוברת קמא. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתב. שיחת אחרון של פסח תשמ\"ז סי\"א נדפסה בהתוועדויות ח\"ג ע' 127."]]],[2300550088,"כל היום<sup data-n=\"3699\">14</sup> אם לא שקדם לו בחי' הצמצום וההסתלקות דבחי' הגבורות דלילה שזהו כברייתו ש\"ע ברישא חשוכא דוקא וא\"כ שניהם כלולי' כא' ממש וד\"ל. ושרש הענין ידוע שכל יסוד ההשתל' למעלה בבחי' הרוחניות האלקי' שמחי' כל העולמות מאין ליש הי' ע\"י התכללו' זאת דצמצום ואח\"כ התפשטות דוקא וכמ\"ש בראשית ברא אלקי\"ם<sup data-n=\"3700\">15</sup> דוקא שזהו שעלה במח' לברוא במדה\"ד<sup data-n=\"3701\">16</sup> ואח\"כ שיתף עמו שם הוי' דחסדי'<sup data-n=\"3702\">17</sup>, שאם לא בחי' הצמצום בתחלה א\"א להיות בחי' התפשטות דחסד שע\"ז אמר עולם חסד יבנה<sup data-n=\"3703\">18</sup> כו'. ולכך גם בכל הברואים העליונים ותחתונים שנבראו מכח האור האלקי אין כל בריאה ובריאה למעלה ולמטה שאין בה ענין ב' הפכים הללו דצמצום והתפשטו' כא' כמו יום ולילה, והוא מ\"ש והחיות רצוא ושוב<sup data-n=\"3704\">19</sup> שזהו אור וחיות האלקי בכלל שמחי' כל העולמות כמ\"ש ואתה מחי' את כולם<sup data-n=\"3705\">20</sup> שהוא בבחי' רו\"ש כמו הנשימה בחוטם ודפיקו דלבא שהחיות עולה ומסתלק וחוזר ויורד, ובזה האופן חוזר תמיד <span data-k=\"pg\">תסה</span> ּ ומתקיים באופן זה דוקא (כמשי\"ת). וכך הוא בכל הברואים הפרטיי' כשרפים וחיות דמרכבה שעיקר חיותם בבחי' רו\"ש בהסתלקות והתפשטות יחד כמו שבכללות דמע\"ב נבראו מדת לילה ומדת יום וערב קודם לבוקר שזהו כמו הרצוא שקודם לשוב וכלולים כא' דוקא כנ\"ל וד\"ל.\n<b>ויובן</b> זה גם ברוחניות דנשמה האלקי' שנק' נשמה ע\"ש הנשימה<sup data-n=\"3706\">21</sup> שנשמת רוח חיים באפיו (בבחי' מטי ולא מטי כמו דופק שברוח שבלב ברו\"ש) שנק' נר הוי' כמ\"ש כי נר הוי' נשמת אדם<sup data-n=\"3707\">22</sup> כאור הנר שעולה ויורד תמיד כו', שאנו רואים התפעלות הנשמה בתפלה שהיא בבחי' רו\"ש באהוי\"ר בתחלה רץ לבך בתשוקה והסתלקות ליכלל באור הוי' ואח\"כ שוב בהמשכות גילוי אלקות בנפשו כמו ע\"י תומ\"צ וצדקה וכה\"ג ונק' עלי' וירידה כא' כו'. והיינו ג\"כ ענין מדת לילה ויום שזהו חשך ואור, כמו שאנו רואים בחוש שא\"א לאדם לבוא לבחי' התפעלות אוי\"ר בהשגה בהתבוננות בק\"ש כ\"א בהקדים תחלה השפלות ומרירות שנק' כובד ראש כמו שא' דאין עומדין להתפלל<sup data-n=\"3708\">23</sup> אלא מתוך כו', דהא בהא תליא לפ\"ע",[["3699","14","<b>דחסד אל כל היום</b>: תהלים נב, ג."],["3700","15","<b>בראשית ברא אלקי\"ם</b>: בראשית א, א."],["3701","16","<b>שעלה במח' לברוא במדה\"ד</b>: ראה הנסמן לעיל פ' תרומה שה, א."],["3702","17","<b>שם הוי' דחסדי'</b>: ראה גם לעיל פ' בא פז, א. וש\"נ."],["3703","18","<b>עולם חסד יבנה</b>: תהלים פט, ג."],["3704","19","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד. ראה גם לקמן פ' ויקהל שצד, ד. מאמרי אדה\"א שמות ח\"א ע' רעט. דברים ח\"ג ע' תת. וש\"נ. קונטרסים ע' תקנה."],["3705","20","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["3706","21","<b>נשמה ע\"ש הנשימה</b>: ראה ב\"ר ספי\"ד. וראה גם לקמן פ' ויקהל שצד, א. פקודי תמה, ג. מאמרי אדה\"א דברים ח\"ג ע' תת. וש\"נ. נ\"ך ע' תקצ. וש\"נ. דרושי חתונה ח\"א ע' קלב. ח\"ב ע' תקפט."],["3707","22","<b>כי נר הוי' נשמת אדם</b>: משלי כ, כז [בהוספת תיבת: כי — ראה הנסמן לעיל פ' בשלח רכו, א]."],["3708","23","<b>דאין עומדין להתפלל</b>: ברכות ל, ב. ראה גם לעיל פ' יתרו רנא, ד. בשלח קעז, א."]]],[2300550120,"דוקא דכל מה שלבו נשבר ונדכא בשפלות וכובד ראש בהכנעת הלב ובושה גדולה מאשר נתרחק מאור פני מלך חיים<sup data-n=\"3709\">24</sup> בח\"נ וכה\"ג, כך לפ\"ע יאיר אור האלקי באור וחיות בנשמתו בהשגה האלקי' ובהתפעלו' האהבה כו' כמו האור הבא אחר החושך דוקא ויום אחר הלילה ששניהם כלולים זע\"ז והיו לאחדים כנ\"ל וכברייתו ש\"ע כו' וד\"ל (וכך הוא גם בגשמיות כמו במו\"מ הפרנסה שא\"א לאדם להרויח בעסקיו כ\"א אחר היגיעה ופיזור הנפש בצער ויסורים מהעדר ההצלחה מכמה סיבות מונעים כו' עד מיצוי הנפש עד שכמו בחשך יהלוך ויאמר נואש בנפשו ויהי' לבו נשבר ונכנע ושפל לכל כו', אזי יצליח לו ה' ויראה ברכה במעשיו שזהו בחי' אור החסד דפרנסה שאינו בא כ\"א אחר הצמצום שהוא ההסתלקות וההעדר כו' כמו הלוך ילך ובכה<sup data-n=\"3710\">25</sup> נושא משך הזרע ואח\"כ בא יבא ברינה כו', כי בזריעה זורע בדמע שמתייאש על הברכה ובקצירה ירנן כו'. וכן בהצלחת הלימוד בתורה אינו בא כ\"א ע\"י יגיעה עד שממית עצמו עלי'<sup data-n=\"3711\">26</sup> ומוצץ חלב שינק<sup data-n=\"3712\">27</sup> כו'. וכן כל עלי' בגדולה אינו אלא אחר ירידה בשפלות תחלה וכמו שאנו רואים שהאדם בכל ימי חייו הוא בבחי' עלי' וירידה תמיד שכמה שנים ועתים מצליח ושמח בחלקו וכמה עיתים יורד ונופל וחוזר ועולה שזהו כמו יום ולילה שהלילה קודם ליום הוא בחושך ולא אור שאין חסד ושפע בלילה בבנ\"א זע\"ז רק ישינים בהסתלקות המוחין ומדות כמת יחשב, ולפני השינה הוא בבחי' הקטנות מאד שהוא העצלות ועצבות והעדר הרגשת אור וחיות בנפשו במוחין ומדות שבלב אף במילי דעלמא כי עיתים דלילה הוא בבחי' הגבו', וגם החולה יכבד עליו חליו בלילה ביותר. אבל בבוקר אור יקום בבחי' גדלות שהוא גדלות המוחין והמדות בשמחה וטוב לבב והוא בחי' גילוי האור וחיות בנפשו ביותר בכל כחות שלה אף בגופו בחיצוני', שהרי גם החולה יקל חליו ויטיב לו בבקר עד חצי היום כידוע, ומסוגל לכל <span data-k=\"pg\">932</span> ּ עסק בטוב השכלת השכל והמדות ומחדו\"מ כי חסד אל כל היום בפרנס' שמתפרנסי' זע\"ז כו' שהחסד נק' אור<sup data-n=\"3713\">28</sup> המאיר היפוך החשך כו', כהפרש שבין מות לחיים כי השינה א' מס' במות<sup data-n=\"3714\">29</sup> והחסד שביום נק' חיים ואור כידוע. וזהו ההפרש בכלל בין מדת יום למדת לילה ומתחלפי', דא\"א להיות הכל בבחי' האור וחסד דיום בגדלות המוחין והמדות כ\"א שיעבור היום ויביא הלילה היפוכו ואז חוזר ומאיר אור החסד ביום האחר, וכך חוזר חלילה גם בכל הימים ושנים כמו מחליף את הזמנים כו' (וכמ\"ש בזוהר דיש עיתים וזמנים<sup data-n=\"3715\">30</sup> ושני' ידיען לטב ועיתים וזמנים ושנים ידיעין לרע כמו למה אירע בימי רע<sup data-n=\"3716\">31</sup> דדינים שלטי' בעלמא וכמו ביום רעה ימלטהו<sup data-n=\"3717\">32</sup> כו' כמו כ\"ח עיתים לטו\"ר<sup data-n=\"3718\">33</sup> כידוע).",[["3709","24","<b>מאור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["3710","25","<b>הלוך ילך ובכה</b>: תהלים קכו, א. ראה גם לעיל פ' בשלח קלג, ד. וש\"נ."],["3711","26","<b>עד שממית עצמו עלי'</b>: שבת פג, סע\"ב."],["3712","27","<b>ומוצץ חלב שינק</b>: ראה ברכות סג, ב. וראה גם לעיל פ' שמות ד, א הערה 178."],["3713","28","<b>שהחסד נק' אור</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. שעה\"י קמד, א הערה 9. לקמן פ' ויקהל שפז, א."],["3714","29","<b>השינה א' מס' במות</b>: ברכות נז, ב."],["3715","30","<b>דיש עיתים וזמנים</b>: ראה זהר מקץ רד, א. ביאוה\"ז שם לג, ג."],["3716","31","<b>למה אירע בימי רע</b>: תהלים מט, ו [ושם: אירא]."],["3717","32","<b>ביום רעה ימלטהו</b>: תהלים מא, ב."],["3718","33","<b>כ\"ח עיתים לטו\"ר</b>: קהלת ג, ב-ח. ראה גם ש\"א ע' 172."]]],[2300550152,"<b>וכך</b> הוא ממש בבחי' הרוחניות האלקי' בעבודת ה' שיש שינוי העיתים מקטנות המוחין ומדות לגדלות המוחין ומדות כמו מיום ללילה ומלילה ליום בדרך כלל אף במילי דעלמא כנ\"ל. והיינו מה שנצטוינו במצות ק\"ש ודברת בם בשבתך בביתך<sup data-n=\"3719\">34</sup> ובלכתך בדרך ובשכבך ובקומך שב' ענינים אלה הם ענין א' שהוא ענין ב' הקצוות הרחוקי' זה מזה בתכלית כמו ההבדל הרחוק בין האור והחושך ויום ולילה כנ\"ל. וכמו שאנו רואים שינוי העתים באדם עצמו שיש עיתים שהוא בעילוי בנפשו בשכל ורצון טוב ומדות שבלבו בשמחה ונק' בחי' גדלות השכל והמדות בהרחבה והתפשטו' (ואז נוח הוא לבריות ומדבר עם כל אדם באהבה ופני\"ם יפו\"ת כו', ומטיב חסדו ועניו וסבלן ומעביר על מדותיו כו'), ולפעמים הוא בהיפוך שהוא בקטנות המוחין בצמצום גדול עד שלא ישכיל בשכלו מאומה כתינוק קטן מצד כבידות ועצלות וגם רוע לב וכעס עד שלא יסבול שום אדם כו' שזהו הריחוק והבדל בין בשבתו בביתו עם אשתו וב\"ב שיושב בשלוה ומנוחה שדעתו מיושבת עליו ולבו טוב ושמח כו' לקבל במוחו ולבו חכמה דתורה כו' או השגה האלקי' ביח\"ע דק\"ש בבחי' גדלות המוחין ומדות דאוי\"ר בשמחה וטוב לבב ובהרחבת ההשגה בעומק הרצון בטוב כו', ולהיפוך מזה הוא כאשר נוסע בדרך שמטולטל ממקומו וטרוד בעסקיו ומתייגע בהילוך וטלטול קשה שאין לבו ודעתו עליו כלל כמבולבל ממש, שאז הוא בבחי' קטנות המוחין מאד בירידה ושפלות במוח ולב עד שיפול הנופל בגסות וחומריות בתאו' גופניו' באכילה ושתי' וכה\"ג כבהמה או כמת יחשב בלי הרגש חיות ואור אלקי בלבו ודעתו שלא יוכל להכיל ולקבל כלל כו'. ועכ\"ז מצווה ועומד במצות ה' בקריאה בד\"ת וק\"ש וגם בלכתך בדרך כמו בשבתך בביתך ממש בשוה, כי גם מצות ק\"ש וד\"ת שמבחי' קטנות המוחין יעלה לה' כשמכוין רק לצאת י\"ח בלבד לעשות רצון קונו שמוטל עליו לקבל עומ\"ש באמונה פשוטה בק\"ש זו אף בלא מוח ולב כלל, וכמו בק\"ש שעל המטה שהוא מנמנם עייף ויגע שגם זה יעלה לה' לרצון בוידוי שלו בלב נכנע ושפל <span data-k=\"pg\">תסו</span> ּ ויזכור על הבורא הכל במחשבה טובה בעלמא בלא השגה ולב כלל כמ\"ש דוד זכרתיך על יצועי<sup data-n=\"3720\">35</sup> במשכבו על מטתו באשמורות אהגה בך בק\"ש דשחרית בגדלות המוחין והלב באהבה ויראה בהתלהבות כו' משום דהא בהא תליא דוקא ואם אין חושך דקטנות דמדת לילה אין אור דגדלות דמדת יום כנ\"ל. וזהו שא' ובשכבך ובקומך בשכבך בק\"ש דערבית שהיא קודם השינה בבחי' קטנות בלא לב ומוח כנ\"ל ובקומך בבחי' הגדלות דמוחין ומדות שבלב בהשגה עמוקה והתפעלות ההתלהבות ושמחה כמו בק\"ש דשחרית שניהם יהיו שוים לך כו' וד\"ל (וכמ\"ש במ\"א בענין ואלה הגבורים אשר יעזרו בלא לב ולב<sup data-n=\"3721\">36</sup> לא לב ולב",[["3719","34","<b>ודברת בם בשבתך בביתך</b>: ואתחנן ו, ז."],["3720","35","<b>זכרתיך על יצועי</b>: תהלים סג, ז. ראה גם לעיל פ' משפטים רפד, ד. בשלח קצה, ב."],["3721","36","<b>ואלה הגבורים. . לב</b>: נסמן לעיל פ' משפטים רפד, ד."]]],[2300550184,"שניהם שוים כו' (משום דקטנות וגדלות הנ\"ל אינם שייך רק בל\"ב שמקבל מל\"ב חדרים שבמוח<sup data-n=\"3722\">37</sup> אבל למעלה מן החכמה שהוא בעצמות הרצון שוי' קטנות וגדלות כו').\n<b>והנה</b> בכל זה יובן שרש ענין הזה בין בשינוי העיתים מזמן לזמן מקטנות לגדלות בחיי הגוף ובחיי הנשמה בירידה ושפלות לפעמים, ולפעמים בעלי' ורוממות כנ\"ל, בין בכל יום ויום אף בקומו בבוקר יש שינויים רבים, שלפעמים יקום בגדלות וגילוי המוחין ומדות דהיינו בטוב לב ושמחה ודעתו זחה<sup data-n=\"3723\">38</sup> ומיושבת בטוב להשכיל ויהי' אופן עבודתו בתפלה וק\"ש ג\"כ בשמחה וטוב לבב בהתפעלות התלהבות בשמחה בהתבוננות בגדולת הבורא ביחו\"ע ויחו\"ת בעומק ההשגה ועומק הלב, וגם בבחי' ראי' מקרוב בעין השכל דחכ' שבמוח ולב בבחי' ביטול והזזה ממקומו לגמרי מכל וכל כו'. ולפעמים יקום בבוקר בלב נשבר ושפלות ועוצב והכנעה בלי טעם כלל ויהי' אופן של עבודתו בתפלה בקטנות המוחי' שהוא רק המרירות ולב נשבר על ריחוקו מה' אחד, ולא יוכל להעמיק דעתו ולבו ולבא להתפעלו' אהבה בחדוה ועונג כלל רק במרירות ושפלות לבד בזאת יומשך כל עיקר עבודתו בתפלה. וזהו השפלות והענוה להיות נפשו כעפר לכל באמת כמו בע\"ת ועני ואביון ממש, וכשהוא בגדלות השכל ומדות בשמחה ועונג האלקי כנ\"ל הרי זה בהתנשאות ועילוי בעצמו עד שיגבה לבו בדרכי ה' כו' כידוע וד\"ל (ונמצא שעיקר בחי' יום ולילה אור וחושך באדם ברוחניות האלקי' כמו בתפלה ותורה אור, וכן בגופו בעסקיו כל היום הוא רק ענין השמחה והרוממות (בל\"א גיהייבין) או העוצב ומרירות ושפלות וענוה כנ\"ל (גיפאלין), שזה שנק' עלי' וירידה בכלל ברוחניות וגשמיות שמשתנה בכל עת וכל זמן בפרט כמעט בכל יום וכל עת ושעה יש עלי' וירידה משמחה לעוצב ומעוצב לשמחה ומעילוי לשפלות כו'. ובכלל בזמנים ידועים כמ\"ש לכל זמן ועת לכל חפץ<sup data-n=\"3724\">39</sup> כו' עת ללדת ועת למות<sup data-n=\"3725\">40</sup> כו' וכנ\"ל שיש ימי הטוב וימי הרעה כו' ומחליף הזמנים מטוב לרע ומרע לטוב ואינו עומד באחת רק מתחלף ומשתנה כמו שאו' ובתבונה משנה עיתים<sup data-n=\"3726\">41</sup> כו' (ובזאת יתנחם האדם בנפשו על ראותו תמיד שינויים גדולים מה שלפעמים נלקה בגופו ביסורים ובממונו ובבניו ובפרנסתו יורד הוא כי בני חיי ומזוני במזלא תליא<sup data-n=\"3727\">42</sup> ) <span data-k=\"pg\">934</span> ּ ובר\"ה נפקד עליו כידוע. וזה העולם נק' עולם התמורה והשינוי שאינו עומד במדריגה א' כלל ומשתנה מעלי' לירידה ומירידה לעלי', וע\"כ אנו רואים שלא יפול הנופל ברוחניות וגשמיות לגמרי רק",[["3722","37","<b>בל\"ב שמקבל מל\"ב חדרים שבמוח</b>: ראה גם לעיל פ' בא קח, א. וש\"נ."],["3723","38","<b>זחה</b>: כ\"ה בגוכית\"ק."],["3724","39","<b>לכל זמן ועת לכל חפץ</b>: קהלת ג, א."],["3725","40","<b>עת ללדת ועת למות</b>: קהלת שם, ב."],["3726","41","<b>ובתבונה משנה עיתים</b>: ברכת ק\"ש (ערבית)."],["3727","42","<b>בני חיי ומזוני במזלא תליא</b>: ראה מוע\"ק כח, א. ביאוה\"ז פקודי נז, א. מאמרי אדה\"א שמות ח\"ב ע' תט. דברים ח\"ד ע' א'תל. וש\"נ. הסדר ראה תניא פכ\"ו ובמ\"מ הגהות והע\"ק לשם. תוד\"ה אין שבת קנו, א. תוד\"ה מוסיפין יבמות נ, א."]]],[2300550216,"לעתים וזמנים וחוזר ועולה ברוחניות וגשמיות וחוזר ויורד כו', וכן בביטושים בבנים וגופו אחר מכה רפואה. ולזאת לא יאמר אדם נואש בנפשו כו' ח\"ו בנפילתו לפרקים וזמנים רבים בין ברוחניות באור תורה ועבודה שבלב ותשו' כו', בין בגשמיות בבני חיי ומזוני או קטרוגים קשים ורעים למעלה ולמטה וכו' שבודאי לא יעמוד כן אלא אחר ירידה עלי' כנ\"ל. וגם בעת שיעלה האדם במעלו' הרוממות ברוחניות וכ\"ש בגשמיות לא ישמח ויגבה לבו ביותר ולא ידמה בנפשו שיצליח כן כל ימיו כי ודאי אחרי עלי' ירידה כו' מטעם הנ\"ל רק על ה' לבדו יבטח ויבקש על נפשו לבלתי ידח ממנו נדח<sup data-n=\"3728\">43</sup> לגמרי ח\"ו וה' הטוב בעיניו יעשה<sup data-n=\"3729\">44</sup> עמו כו' וד\"ל.\n<b>והנה</b> מבואר למעלה בשרש ענין מדת יום ולילה למעלה במקור כל החיים דעולמות עליונים ותחתונים בא מחמת שאור האלקי נמשך בבחי' רו\"ש דוקא דהיינו בבחי' הסתלקות והתפשטות דוקא. והטעם הוא לפי ששפע זאת נמשכת מבחי' הגבור' שעולה ויורד (כמו הדם הוא הנפש<sup data-n=\"3730\">45</sup> באדם שמחי' לגוף שמחמת שהוא בבחי' גבור' דאו\"ח עולה רוח החיים שבלב וחוזר ויורד שהוא הדפק שבלב), דאם הי' האור ושפע זאת בבחי' החסדים שיורד ונמשך כמים מגבוה לנמוך לא הי' בבחי' או\"ח כלל, אבל להיותו בבחי' גבורות כאש העולה לכך עולה ויורד כאור הנר שז\"ש והחיות רו\"ש בכלל. ובפרט שמפני שבפועל הנברא יש מעין דבר המשפיע, שכל נפעל דומה לפועל<sup data-n=\"3731\">46</sup> מאחר שכחו נמשך בו ע\"כ גם החיות ושרפי' וכה\"ג הן בבחי' רו\"ש תמיד מפני שכח זה האלקי בא בנבראים בבחי' רו\"ש בעצמו כו' וכמו שמדמים בדרז\"ל לנשמה שממלא הגוף<sup data-n=\"3732\">47</sup> כו' ונקרא נשמת כל חי<sup data-n=\"3733\">48</sup> בכלל (ואם האור וחיות האלקי נמשך מבחי' צירופי אותיות הדיבור העליון כמו ביו\"ד מאמרות יהי אור יהי רקיע<sup data-n=\"3734\">49</sup> ומחדש בכל יום מע\"ב למעלה ולמטה כו' גם באותיות הדבור יש בחי' עלי' וירידה בבחי' רו\"ש, כמו שנראה בחוש בהבל הדבור היוצא מן הפה שיסתלק ויתפשט כמו שהבל זה עצמו הוא ברו\"ש בלב והוא הרו\"ח שכלול מאש ומים בדיבור<sup data-n=\"3735\">50</sup> (ונק' רוח ממללא<sup data-n=\"3736\">51</sup> כו' כידוע). וכך למעלה כמו בדבר ה' שמים נעשו<sup data-n=\"3737\">52</sup> וברוח פיו כו' הרי מרוח פיו ית' נתהוו מאין ליש שמחמת זה הרי זה בבחי' רו\"ש גם בנבראים שבהן א' והחיות רו\"ש כנ\"ל וד\"ל (והוא מ\"ש בזהר ע\"פ מצמיח חציר לבהמה<sup data-n=\"3738\">53</sup> שהוא שם ב\"ן<sup data-n=\"3739\">54</sup> דמל' דשתית לון בגמיעא חדא שזהו מה שהמלאכים הנבראים מרוח פיו כו' חוזרים ונכללים ברוח פיו דמל' בביטול המציאות וזהו ושתית לון כו').",[["3728","43","<b>לבלתי ידח ממנו נדח</b>: שמו\"ב יד, יד."],["3729","44","<b>וה' הטוב בעיניו יעשה</b>: ע\"פ שמו\"א ג, יח."],["3730","45","<b>הדם הוא הנפש</b>: פ' ראה יב, כג."],["3731","46","<b>שכל נפעל דומה לפועל</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קפד."],["3732","47","<b>לנשמה שממלא הגוף</b>: ראה ברכות י, א. ויק\"ר פ\"ד, ח."],["3733","48","<b>נשמת כל חי</b>: שחרית לשבת. ראה גם לעיל פ' בשלח קסה, ג."],["3734","49","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["3735","50","<b>הרו\"ח שכלול מאש ומים בדיבור</b>: ראה זהר (רע\"מ) בא מג, ב. תצוה קפד, ב. לעיל פ' בא קו, ד. וש\"נ. שמות יט, ג. וש\"נ."],["3736","51","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["3737","52","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3738","53","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד. ראה זהר בראשית יח ב. לעיל פ' בא צג, א. וש\"נ."],["3739","54","<b>לבהמה שהוא שם ב\"ן</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא ספמ\"ו</a>. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."]]],[2300550248,"<b>וז\"ש</b> בזהר ע\"פ אלקים אל דמי לך<sup data-n=\"3740\">55</sup> דאלקים זה היינו בחי' המל'<sup data-n=\"3741\">56</sup> שמחי' כל העולמות מאין ליש שנק' נהורא תתאה שהוא חכמה שבדיבור העליון להיות מקור לנבראים בע\"ג דקארי תדיר לנהורא עילאה דאצי' <span data-k=\"pg\">תסז</span> ּ ולא שכיך לעלמין וכמ\"ש למען יזמרך כבוד<sup data-n=\"3742\">57</sup> שהוא כבוד התחתון דבחי' מל' בבי\"ע שנק' ראש לשועלים<sup data-n=\"3743\">58</sup> כו' שיזמר ויעלה בהעלא' מ\"ן לגבי אורות העליונים דאצי' שלמעלה מהיות מקור וראש לבי\"ע כו', שזהו כמו בחי' הסתלקות החיות ברוח החיים שבלב שנק' רצוא ואח\"כ בחי' שוב כו'. כך כח וחיות האלקי המצומצם בעולמות עולה בבחי' רצוא באצי' ונעשית בחי' נקודה תח\"י<sup data-n=\"3744\">59</sup> כמ\"ש בזהר ע\"פ שחורה אני כו' דאזעירת גרמה<sup data-n=\"3745\">60</sup> מגו דחיקו דרחימו כו' ונעשית נקודה א' כחיריק תחת האות לגבי בחי' צדיק עליון בחי' יסוד שהוא בחי' סובב כ\"ע דאצי' בכלל כידוע שזהו שנק' נהורא עילאה ואח\"כ נמשך מחדש מלמעלה מאצי' להיות בבחי' שוב למטה שזהו בהתפשטו' דמל' בחסד ומדות ומח' ודבור בקומה שלימה בבריאה ויצי' כו' (וכמ\"ש עושי דברו ה\"א כמלקדמין<sup data-n=\"3746\">61</sup> בבנין שלם בע\"ס באו\"כ כשהן בבחי' מקור לבי\"ע (ובחי' העלאה כנקוד' באצי' למעלה הוא מכל בחי' ההתפשטו' בבנין קומה בבריאה כו' (וכמ\"ש ואמונה כל זא\"ת בחי' נוק' כיו\"ד באצי' ואח\"כ וקיים לשון זכ\"ר<sup data-n=\"3747\">62</sup> להיות מקור לבי\"ע כמ\"ו דזנב לאריות יותר עליון<sup data-n=\"3748\">63</sup> מראש לשועלים (וכתלמיד לפני רבו כיהושע אצל משה גדול ביותר<sup data-n=\"3749\">64</sup> מכאשר נעשה משפיע בריחוקו מרבו כו' (וכך במדת לילה דגם שנק' בחי' קטנות המוחין בדורמיט\"א בשינה שהוא הסתלקות המוחין ולא נשאר רק קיסטא דחיותא<sup data-n=\"3750\">65</sup> בלב כו' יש בזה מעלה יתירה<sup data-n=\"3751\">66</sup> הרבה יותר מגדלות המוחין ומדות שביום בהקיץ מצד בחי' העלאה דאו\"ח זה בעצמות הנפש דחי' יחידה דכל מה שנמשך ממנה בהתפשטות השכל ורצון כו' אינו רק נקוד' אחת שם (וכמו שא' בגמ' בלילא מה עביד קוב\"ה<sup data-n=\"3752\">67</sup> רוכ\"ב על כרו\"ב ק\"ל שלו שהוא בחי' המל'<sup data-n=\"3753\">68</sup> כאשר היא בקטנות המוחין כמו בחי' דומם וצומח ובשינה בלילה שעולה למעלה מעלה וד\"ל. וזהו ושט בח\"י אלף עולמות שהוא העלי' דז\"א בא\"א וע\"י שהוא יותר גדול ממה שיושב ועוסק בתורה ויושב וד\"ן בגדלות המוחי' ביו\"ם וד\"ל) (וכן בגלות שנק' לילה<sup data-n=\"3754\">69</sup> וחושך למעלה מאור היום דגאולה שמחמת העלאה זו דאו\"ח בגלות שנק' שינה<sup data-n=\"3755\">70</sup> הוא שחוזר ונמשך ממקום שעלה דוקא למטה באו\"י שזהו כמו בחי' השו\"ב שאחר הרצוא דוקא שבא לפ\"ע העלאה דרצוא דוקא וד\"ל) (ולפ\"ז הרי יובן דגם בענין קטנות וגדלות",[["3740","55","<b>אלקים אל דמי לך</b>: נסמן לעיל פ' יתרו רעג, ב."],["3741","56","<b>דאלקים. . המל'</b>: ראה זהר בראשית כב, א. אחרי סה, א. לעיל פ' וארא עה, ב. וש\"נ."],["3742","57","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["3743","58","<b>מל'. . ראש לשועלים</b>: ראה ז\"ח (מדהנ\"ע) שה\"ש עא, א. הנסמן לעיל פ' וארא נד, ב."],["3744","59","<b>נקודה תח\"י</b>: ראה זהר שבהערה הבאה. הנסמן לעיל פ' וארא עא, ד."],["3745","60","<b>שחורה אני כו' דאזעירת גרמה</b>: שה\"ש א, ה. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז."],["3746","61","<b>עושי דברו ה\"א כמלקדמין</b>: תהלים קג, כ. ראה זהר שם."],["3747","62","<b>ואמונה כל זא\"ת. . וקיים לשון זכ\"ר</b>: ברכת אמת ואמונה (ערבית). ראה לעיל פ' בשלח קפט, ג. וש\"נ."],["3748","63","<b>דזנב לאריות יותר עליון</b>: אבות פ\"ד, מט\"ו. ראה גם לעיל קפט, ב. וש\"נ."],["3749","64","<b>כיהושע אצל משה גדול ביותר</b>: ראה גם לעיל שם. וש\"נ."],["3750","65","<b>קיסטא דחיותא</b>: ראה זהר לך פג, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, ב</a> ובהנסמן במ\"מ לשם."],["3751","66","<b>יש בזה מעלה יתירה</b>: ראה גם לעיל פ' שמות לח, ד. וש\"נ."],["3752","67","<b>בלילא מה עביד קוב\"ה</b>: ראה ע\"ז ג, ב."],["3753","68","<b>כרו\"ב. . המל'</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תריג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680291\" data-slug=\"torat-chaim\" data-id=\"2300680291\">תו\"ח וישב רט, א</a>."],["3754","69","<b>בגלות שנק' לילה</b>: ראה זהר אחרי סז, רע\"ב. סה\"מ מלוקט ח\"ב ע' רסו הערה 16."],["3755","70","<b>בגלות שנק' שינה</b>: ראה זהר אמור צה, א. האזינו רפו, א. לעיל פ' שמות לז, ד הערה 4."]]],[2300550279,"דחשך ואור בנה\"א כמו ענין כובד ראש שקודם התפלה או קטנות המוחין בק\"ש דערבית ושעל המטה כמ\"ש בשכב\"ך כנ\"ל למעלה הוא מגדלות המוחין דק\"ש שחרית מטעם הנ\"ל.\n<b>וכמו\"כ</b> בענין ירידו' ועליו' בימי חיי האדם ברוחניות ובפרנסה מה שיורד ונופל ברוחניות ובגשמיות זהו למעלה מהעלי' שלו בתפלה ופרנסה א\"כ הירידה עלי' והעלי' ירידה, וכי אפשר דמה שנופל ממדריגתו למטה וגם למעלה זהו למעלה מעלי' שלו משפלות וקטנות לגדלות (שהרי א' בזוהר דמאן דנפל מדרגי'<sup data-n=\"3756\">71</sup> אקרי מיתה כו' וכמו מחיים למות ודאי נק' נפילה לארץ וממות לחיים נק' עלי' כו'. וכך בענין חסד דפרנסה ודאי עני חשוב כמת<sup data-n=\"3757\">72</sup> ונק' יורד <span data-k=\"pg\">936</span> ּ וכשמתעשר זהו עלי', וכך ברוחניות בקטנות דמרירות ושפלות קודם האור וחיות והתענוג האלקי וכו', וכן בזריעה שיזרע בדמע שלא יורקב בארץ ויפסיד ויקצור ברינה כו', וכן מיצוי הנפש עד שיאמר נואש בפרנסה כו', וכן בהצלחת הלימוד מה שממית עצמו עלי' תחלה ואח\"כ יחי' חיי עולם (וכענין הרוצה לחיות ימית א\"ע<sup data-n=\"3758\">73</sup> והרוצה למות יחי' א\"ע כו'). אלא צריך לומר דודאי זה אמת דאין אור בלא חשך וצמצום קודם (וכן ברצוא קודם לשוב), אבל אדרבה משום דאור החסד הוא במעלה ומדרגה גבוה ביותר ע\"כ א\"א שיבא אליו כ\"א בהקדם היפוכו שהוא הצמצום וההסתלקות שהוא בחי' דין כמו החשך דלילה וקדרות דצפרא שקודם לאור הבוקר כו' (וכך הוא בענין הרצוא שקודם לשוב דבחי' שוב הוא מעלה עליונה ביותר כענין התפשטו' השכל ומדות במוחא ולבא בגדלות המוחין א\"א להיות כ\"א ע\"י בחי' רצוא בתחלה שהוא ההסתלקות כנקודה א' במרירות ושפלות כנ\"ל).\n<b>ושרש</b> הענין הוא כידוע שזהו הכלל גדול בכל ההשתלשלו' למעלה ולמטה שא\"א להיות בחי' ההמשכה והשפעה האלקי' מאין ליש בבחי' גדלות אם לא שיוקדם תחלה היפוכו ממש שזהו בחי' קטנות בחי' ביטול היש לאין בתכלית כו', כמו שרואים בשפע הגשמי' בזריעה שבארץ הגשמי' שא\"א שיצמח מאין ליש בעלי' ותוס' ברכה כ\"א בהקדים תחלה ביטול היש לאין בתכלית שזהו רקבון הגרעין בארץ<sup data-n=\"3759\">74</sup> והי' כלא ממש שנכלל בכח הצומח אז חוזר ונמשך מכח הצומח מאין ליש בריבוי ותוס' כו'. וזהו ג\"כ בפרנסה שא\"א להשיג השפע והברכה בפרנסה כ\"א בהקדים תחלה בחי' ביטול הי\"ש לאין בפיזור הממון שזהו חיותו",[["3756","71","<b>דמאן דנפל מדרגי'</b>: ראה זהר (אד\"ר) נשא קלה, ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתצד. וש\"נ."],["3757","72","<b>עני חשוב כמת</b>: נדרים סד, ב. זהר (רע\"מ) משפטים קיט, א. רש\"י שמות ד, יט."],["3758","73","<b>הרוצה לחיות ימית א\"ע</b>: ראה תמיד לב, א."],["3759","74","<b>רקבון הגרעין בארץ</b>: ראה אגה\"ק ס\"ח (קיג, א). לעיל פ' שמות ב, ג. וש\"נ."]]],[2300550307,"ממש עד שיאמר נואש בנפשו, וכזורע בדמע כנ\"ל אז יומשך מאין ליש בשפע האלקי' שיתברך במעשיו כו'. וכמו\"כ בהצלחת הלימוד א\"א כ\"א שימית עצמו עלי' וכביטול הי\"ש לאי\"ן בתכלית כמאמר לא תמצאנה בגסי הרוח<sup data-n=\"3760\">75</sup> ולא במי שמרחיב דעתו עלי' כים כו'. וכן בתפלה א\"א בלא מרירות בתכלית השפלות כרקבון הגרעין כו' (וכולד שאינו נולד מן הטפה אא\"כ מסרחת<sup data-n=\"3761\">76</sup> להיות כלא וכאפרוח שיצירתו מאי\"ן<sup data-n=\"3762\">77</sup> דגובלא בעלמא כו'). וכך הוא גם למעלה בעליות העולמות ונשמות ממדרגה למדרגה א\"א כ\"א בירידה וקטנות תחלה שיהי' כלא וכאין מישותו ומדרגתו הראשונה לגמרי אז יוכל להיות בחי' כלי לקבל אור והשגה האלקי' שבעולם העליון יותר (כר\"ז ששכח תלמוד בבלי<sup data-n=\"3763\">78</sup> כשרצה לקבל תלמוד א\"י), כמו נשמות ומלאכים בג\"ע דעשי' שמתבטלים ממציאות שלהם הראשון (בעמוד שעולין בו<sup data-n=\"3764\">79</sup> ) בעלותם לג\"ע דיצי' שכדי שיאירו באור העליון דג\"ע דיצי' או בריאה, מוכרח שיופשטו לגמרי מכל השגות ומדות שלהם שהיו בג\"ע דעשי' וכן מיצי' לבריאה ומבריאה לאצי'. וגם בכללות העלי' דמל' כנ\"ל שכאשר בחי' המל' בכלל עולה למעלה באצי' להיות בבנין פרצוף באו\"כ בע\"ס דאצי' לפי שנבדל בערך מן בחי' הבריאה (שמסך מפסיק בין אצי' לבריאה<sup data-n=\"3765\">80</sup> ), <span data-k=\"pg\">תסח</span> ּ ע\"כ צריך להיות תחלה בחי' ביטול היש לאין שזהו מה שנעשית נקודה א' לבד באצי' כנ\"ל והוא מה שנסתר כל פרצוף שלה בבריאה ממוחין דחב\"ד ומדות כו'. וזהו דאזעירת גרמה עד דלית חיוורא בגו אתוון כו' ואח\"כ נבנית בבנין חדש באצי' בפרצוף שלם בבחי' אצי' וזהו ה\"א כמלקדמין באצי' מטעם הנ\"ל וד\"ל). ולפי\"ז מה דקארי נהורא תתאה לנהורא עילאה בבחי' רצוא למטה מבחי' שו\"ב באצי' ומטעם הנ\"ל בכל עלי' ממדריגה למדריגה העליונה יותר (וכמ\"ש במ\"א בענין נפ\"א ובענין והאיש משתאה לה<sup data-n=\"3766\">81</sup> כו'). וכך הוא למטה בקטנות וגדלות שירידה דקטנות ממש בשביל העלי' דגדלות ברוחניות וגשמיות, וכך הוא בבחי' רו\"ש שבאדם בהסתלקות וצמצום החיות שזהו בביטול היש לאין שגורם המשכת החיות דבחי' שוב שהוא מה שמתפשט האור וחיות במוח ולב כו', וזהו כמו שחושך קודם לאור והיינו בשכבך ובקומך דא\"א להיות בחי' גדלות המוחי' דיום בק\"ש דשחרית בלי הקדם תחלה קטנות דלילה כו' (אך באמת ענין ה\"א כמלקדמין דקאי",[["3760","75","<b>לא תמצאנה בגסי הרוח</b>: ראה ערובין נה, א."],["3761","76","<b>וכולד. . מסרחת</b>: ראה גם לקמן פ' ויקהל תכד, ג. פקודי תמז, ב. תנו, א. מאמרי אדה\"א דברים ח\"ג ע' תתקז. וש\"נ. קונטרסים ע' שע. וש\"נ. הנחות תקע\"ז ע' קכ."],["3762","77","<b>וכאפרוח שיצירתו מאי\"ן</b>: ראה תמורה לא, א. הנסמן במאמרי אדה\"א דברים וקונטרסים שם."],["3763","78","<b>כר\"ז ששכח תלמוד בבלי</b>: ראה ב\"מ פה, א. ראה גם הנסמן לקמן פ' ויקהל תט, ב הערה 667."],["3764","79","<b>בעמוד שעולין בו</b>: ראה זהר ויקהל ריא, א. ויחי ריט, א. לעיל פ' שמות ו, ד הערה 295."],["3765","80","<b>שמסך מפסיק בין אצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["3766","81","<b>בענין נפ\"א ובענין והאיש משתאה לה</b>: ראה סידור שער נפ\"א ע' 182 ואילך. שע\"ת מד, ב ואילך. תו\"ח ח\"ש קלז, ד ואילך ובהערה 1 שם."]]],[2300550332,"בגבורי כח שהן המלאכים דבריאה ויצי' שבהעלאת מ\"ן שלהם בביטול היש לאין האלקי דבחי' מל' גורמי' בנין המל' מחדש מאי\"ן ליש בע\"ס או\"כ כו' דזהו ודאי בהתפשטו' ט\"ס דמל' בבי\"ע מחדש אחר שנעשי' נקודה א' באצי' כנ\"ל דלא כדלעיל שנבנית בנין חדש באצי' עצמו כו' שהשוב הוא למטה בבריאה ולא באצי' כו'). ואפשר יכול להיות דגיבורי כח הללו שעושי דברו דבחי' מל' בכת\"ר מל' שנק' דבר\"ו שנצב בשמים דבחי' ז\"א<sup data-n=\"3767\">82</sup> דאצי' כמ\"ש וממשיכי' אותו להיות בנין בע\"ס דבריאה באו\"כ, לפי שגיבורי כח הללו הן המלאכים דאצי'<sup data-n=\"3768\">83</sup> בבחי' נה\"י דז\"א שהן למ\"ד כלים דנה\"י בראש תוך סוף דז\"א<sup data-n=\"3769\">84</sup> שנק' ג' עדרי צאן<sup data-n=\"3770\">85</sup> רובצים על הבאר כו', והן ל' מעלות דהאשה נקנית בהן שהיא בחי' המל'<sup data-n=\"3771\">86</sup> והן למ\"ד הגיבור\"י' שעוזרי' לדוד<sup data-n=\"3772\">87</sup> מלמעלה מאצי' להיות המל' כת\"ר לבריאה כו' להיות ה\"א כמלקדמין בכחב\"ד דבריאה כו', או שעושים דברו בבנין חדש באצי' והדר לשמוע בקול דברו<sup data-n=\"3773\">88</sup> בבנין בבריאה שנק' קול דבר מל' כו'. ואמנם יהי' איך שיהי' יכול להיות שיהי' יתרון מעלה לבחי' הרצוא על בחי' השוב כדלעיל בנקודה שבאצי' שלמעלה מכתר לבריאה, כי בעלי' דמל' באצי' הרי נבנית במוחין ומדות דאצי' שנבדל בערך הרבה גם ממה שנעשית אח\"כ כתר וראש לשועלים דבריאה שזהו בחי' שוב למטה להחיות רוח שפלים<sup data-n=\"3774\">89</sup> שזהו בחי' קטנות המוחין כו', וכך יכול להיות בבחי' רו\"ש דאדם דלא כנ\"ל וד\"ל).\n(ובכל זה יובן בתוספת ביאור בטעם דצמצום קודם להתפשטות גם למעלה בחשך שקדם לאור כברייתו ש\"ע וכמו שא' ויהי ערב כו', משום דהסתלקות דחושך בחי' ביטול היש לאין כמו בחי' רצו\"א שגורם בחי' נהור\"א דחכ' מאי\"ן ליש כו' שמזה מובן דרצוא למטה משום דכל הרצוא בשביל השוב ובקטנות וירידה בשביל הגדלות ועלי' כנ\"ל. ואמנם אע\"פ שבאדם וכל בריאה ועולם כן הוא מטעם הנ\"ל בהעלאה דביטול <span data-k=\"pg\">938</span> ּ היש לאין בתחלה, וכך הוא בענין עליות העולמות למעלה (וכנהר דינור שקודם לג\"ע<sup data-n=\"3775\">90</sup> וכן בג\"ע לילה קודם ליום דתרעין דג\"ע סתומים בלילה<sup data-n=\"3776\">91</sup> ובבוקר אור יאמרו כל המלאכים שירה ולא בלילה<sup data-n=\"3777\">92</sup> (ואע\"פ שבלילה בחי' אורות דגבורות כמו במזבח בהקטר חלבי'<sup data-n=\"3778\">93</sup> כו' והמצות נעשים ביום<sup data-n=\"3779\">94</sup>",[["3767","82","<b>בכת\"ר מל'. . ז\"א</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תפב. וש\"נ."],["3768","83","<b>המלאכים דאצי'</b>: ראה גם מאמרי אדה\"ז תקס\"ט ע' נז. שע\"ת צב, ג הערה 32."],["3769","84","<b>למ\"ד כלים. . דז\"א</b>: ראה ע\"ח (שער הפרצופים) ש\"ל, דרוש א. שם (שער השמות) שמ\"ד. מאמרי אדה\"ז תקס\"ט ע' רכב [וכן צ\"ל במאמרי אדה\"א שבהערה 86]. אוה\"ת ר\"ה ע' א'תג. אמרי בינה שער הק\"ש לד, ב. סה\"מ תר\"ן ס\"ע רפח ואילך."],["3770","85","<b>ג' עדרי צאן</b>: ויצא כט, ב. ראה זהר (ס\"ת) ויצא קנא, ב. ע\"ח (שער הפרצופים) ש\"ל ריש דרוש ב. שם (שער פרטי עי\"מ) שכ\"ז, פ\"ב."],["3771","86","<b>ל' מעלות דהאשה נקנית בהן. . המל'</b>: אבות פ\"ו, ו. ראה גם מאמרי אדה\"ז, אמרי בינה ואוה\"ת שבהערה 84. מאמרי אדה\"א דברים ח\"א ע' רכ."],["3772","87","<b>למ\"ד הגיבור\"י' שעוזר\"י' לדוד</b>: ראה גם לעיל פ' בשלח קצה, ב. וש\"נ."],["3773","88","<b>והדר לשמוע בקול דברו</b>: ראה שבת פח, א."],["3774","89","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["3775","90","<b>וכנהר דינור שקודם לג\"ע</b>: ראה לעיל פ' שמות ה, ד. וש\"נ."],["3776","91","<b>דתרעין דג\"ע סתומים בלילה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370054\" data-slug=\"torah-or\" data-id=\"3901370054\">תו\"א לך יב, ג</a>. לעיל פ' וארא מט, ד. וש\"נ."],["3777","92","<b>ובבוקר. . שירה ולא בלילה</b>: ראה גם לקמן שכא, ד. לעיל פ' וארא עד, א. וש\"נ."],["3778","93","<b>שבלילה. . בהקטר חלבי'</b>: מגלה כ, ב (במשנה). ראה גם ש\"א כט, א. מאמרי אדה\"א שמות ח\"ב ע' שלו. וש\"נ."],["3779","94","<b>והמצות נעשים ביום</b>: ראה גם ביאוה\"ז פינחס קיא, ד בשם רז\"ל. מאמרי אדה\"ז תקס\"ב ח\"א ע' קסב. תקס\"ז ע' שמח. ש\"א שם (ובהערה 2). מאמרי אדה\"א שמות שם. סה\"מ תרס\"ד ע' שנז."]]],[2300550357,"דוקא כידוע לאכללא שמאלא דגבורות בחסדים דדכורא כו'), אבל למעלה בבחי' מל' מקור כל העולמות שגם עז\"א והחיות רצוא ושוב בחי' הרצוא נק' עלי' למעלה באצי' עד שנעשי' בפרצוף חדש באצי' כנ\"ל ובחי' שוב זהו בחי' הירידה שלה למטה להיות כתר לבי\"ע בבחי' קטנות שהוא בהיפוך ממה שנמצא בנבראים ברו\"ש כנ\"ל, ואע\"פ שמבואר למעלה דהנפעל דומה לפועל ממש כו'. אך הענין הוא דודאי מתהפך מן המשפיע למקבל כחותם המתהפך<sup data-n=\"3780\">95</sup> כו' דמה שבמשפיע בסוף נעשה במקבל בתחלה שזהו מבחי' שוב בירידה דמל' דאצי' בבריאה כנ\"ל ואי\"ן ליש נעשה מזה בחי' הרצוא בנבראים בתחלה בביטול היש לאין כמו בשירה שלהם בהשגה מצומצמת כו', ומה שבמשפיע בתחלה שהוא עלי' דמל' למעלה שמזה נעשה בחי' שוב בנבראים שהוא בחי' המשכה דיראה וביטול עצמי לבא למעלה עליונה יותר כמו בעמדם תרפינה<sup data-n=\"3781\">96</sup> כו', וכמו בחי' רצוא באדם בכלל בתפלה לבא לבחי' שוב בתו\"מ כידוע וד\"ל (אך גם בעלי' המל' זהו בחי' מקבל שעולה ברצוא ושוב כמו הנבראי' שעולים לבחי' המל' וא\"כ גם במל' רצוא למטה משוב כמו בנבראים, וזהו שנעשית נקודה א' באצי' ואח\"כ נבנית והיינו בחסדי' דז\"א מבחי' שוב נעשה בחי' רצוא דמל' כנ\"ל.\n<b>ובמ\"א</b> מבואר דמן המשפיע למקבל נמשך בחי' מטי ולא מטי<sup data-n=\"3782\">97</sup> חסד קודם לגבו' היפוך דרצוא ושוב מן המקבל למשפיע וכמו ורוח אלקים מרחפת נוגע<sup data-n=\"3783\">98</sup> תחלה כו' התפשטו' קודם להסתלקות וכנשימה בחוטם בהמשכה תחלה בנקב הא' כו' והסתלקות למעלה מהתפשטות כמ\"ש בחד נוק' דחוטמא חיין ובנקב הב' בהסתלקות חיי דחיין<sup data-n=\"3784\">99</sup> כו'. וכך הי' במ\"ת שקדם המשכה דחסדי' דמ\"ע באנכ\"י קודם דגבו' דל\"ת בולא יהי' לך ושס\"ה ל\"ת בי\"ה למעלה מו\"ה<sup data-n=\"3785\">100</sup> דמ\"ע כידוע וד\"ל. וכך הי' בתורה הקדומה שהיתה שעשועי' כו' בבחי' מטולמ\"ט דחסדי' דתענוג הפשוט קודם לגבו' שבתענוג דחכ' הקדומה (כשעשועי האב בבנו כו') וגבורות שבתענוג הפשוט עולה בשעשועי' העצמיי' ממש כו' וד\"ל. וכך הוא גם בתורה הנגלית לנו בעשי' שדבר ה' שבמקרא ומשנה נמשך בבחי' מול\"מ בהתפשטו' ברוח הבל הדיבור ואח\"כ הסתלקו', כי דברי' שבמ\"ת הם חיים וקיימים, וכן כל דבר הוי' שמדבר עכשיו זהו מלמעלה למטה מן המשפיע למקבל כמו במ\"ת ממש. וכך גם בתענוג הפשוט בתורה בטעמים ונגינות שנק' רננא דאורייתא<sup data-n=\"3786\">101</sup> כמו שעשועי' שבתו' הקדומה בבחי' מולמ\"ט במקיף דכתר דח\"ע להחיות לכל נשמה במקיף ופנימי שבה כו' דנש\"י מתקשראן באותיות התורה<sup data-n=\"3787\">102</sup>",[["3780","95","<b>כחותם המתהפך</b>: ראה אגה\"ק ס\"כ (קלא, א). מאמרי אדה\"א נ\"ך ע' ריד. וש\"נ. קונטרסים ע' רפז."],["3781","96","<b>בעמדם תרפינה</b>: יחזקאל א, כד. כה."],["3782","97","<b>דמן המשפיע. . מטי ולא מטי</b>: ראה גם לעיל פ' וארא סג, ד. מאמרי אדה\"א קונטרסים ע' רפו. דברים ח\"ב ע' תרחצ."],["3783","98","<b>ורוח אלקים מרחפת נוגע</b>: בראשית א, ב. ראה ב\"ר פ\"ב, ד. רש\"י האזינו לב, יא."],["3784","99","<b>בחד נוק' דחוטמא חיין. . חיי דחיין</b>: ראה זהר (אד\"ר) נשא קל, רע\"ב. סידור שער התפילין ט, ב ואילך. אמ\"ב שם קכד, א."],["3785","100","<b>ושס\"ה ל\"ת בי\"ה למעלה מו\"ה</b>: נסמן לעיל פ' יתרו רנב, א הערה 82."],["3786","101","<b>רננא דאורייתא</b>: ראה זהר בהקדמה ח, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעא וע' תקפא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670213\" data-slug=\"torat-chaim\" data-id=\"2300670213\">תו\"ח בראשית ד, א</a>. ובהערה 7."],["3787","102","<b>דנש\"י מתקשראן באותיות התורה</b>: ראה גם לעיל פ' תרומה שז, ד. שיח, א."]]],[2300550377,"כידוע, אבל בתפלה שהוא בחי' המל' והן נש\"י שעולים מלמטה למעלה באו\"ח גבו' דרצוא <span data-k=\"pg\">תסט</span> ּ קודם לשוב והשוב למעלה מן הרצוא כנ\"ל. וידוע דמבחי' מולמ\"ט דמשפיע נעשה רו\"ש דמקבל<sup data-n=\"3788\">103</sup> כמו מנשימה דנשמה באפו נעשה דפיקו דלבא ברו\"ש בהיפוך כחותם המתהפך בציורו בשעוה כנ\"ל, ומבחי' מטי דחכמה דמשפיע נעשה גבו' דרצוא במקבל ומלא מטי דמשפיע נעשה שוב במקבל כו', שהרי מלמטה למעלה סו\"מ תחלה ואח\"כ וע\"ט דמ\"ע וסו\"מ בבינה וע\"ט בחכמה כמ\"ש הן יראת ה' כו' וסומ\"ר בינה<sup data-n=\"3789\">104</sup> היפוך דאנכי במ\"ע דהן קודם ללאו<sup data-n=\"3790\">*105</sup> מלמעלה למטה כו' ולאו קודם להן מלמטה למעלה כמ\"ש ולא תחללו כו' ואח\"כ ונקדשתי<sup data-n=\"3791\">105</sup> במ\"ע כו'. וראי' לזה מתפילה שהיא בבחי' רצוא קודמת לתו' שהיא בחי' שוב בכלל ובאמת תפלה במל' בבחי' מקבל שעולה ברו\"ש ותורה בת\"ת בחי' משפיע כנ\"ל, וא\"כ העלאה דנש\"י בתפלה גורם הירידה דמשפיע באור ישר באור התו\"מ כו' כמו שעולה הלב בדפיקו למוח גורם המשכת המוחין דנשמה בלב כו' ואם אין העלאה בביטול היש לאין אין המשכה מאין ליש ממוח ללב שהוא החכ' דתורה כו', וכמ\"ש אם אין יראה אין חכמה<sup data-n=\"3792\">106</sup> כו', אבל גם זה אמת דאם אין חכ' דתורה אור מלמעלה למטה אין יראה כו' וד\"ל (ועכ\"ז אין מתיישב ענין רו\"ש במקבל שהוא כמו שפלות ושמחה כנ\"ל דהלא הרצוא הוא בבחי' האהבה וקירוב בדביקות שהוא שרש למ\"ע דוקא כידוע והיראה שהוא שפלות וענוה כו' שהוא בחי' שוב שרש ל\"ת וא\"כ למה סו\"מ קודם לוע\"ט, וגם למה הרצוא נק' ירידה והשוב עלי' כנ\"ל מאחר שהאהבה ודביקות הוא בשמחה ויראה בשפלות כו' וצ\"ל דשמחה בשוב בהמשכ' אלקות וזהו ענין שמחה בצפרא ורננא ברמשא<sup data-n=\"3793\">107</sup> כו' (כמשי\"ת) וד\"ל.\n<b>והנה</b> עדיין יש להבין בשרש ענין מדת יום ומדת לילה שז\"ש ויהי ערב כו' מהיכן בא התחלקות זו בבחי' זמן דוקא להיות משך זמן י\"ב שעות לילה ומשך זמן י\"ב שעות יום כו'. אך הנה מבואר במ\"א בענין ג' מדריגות דעולם שנה נפש<sup data-n=\"3794\">108</sup> דעולם הוא מהות הנברא שהוא בא בגדר גבול ומדה ובבחי' יש מציאות דבר מה כו' והיינו בחי' הכלי לאור כחומר לצורה כו', ובחי' שנה זהו זמן קיומו באו\"כ צורה בחומר כנפש בגוף וכן כל בריאה למעלה ולמטה שהוא קשר הרוחניות בגשמיות באי\"ן לי\"ש נק' שנה, ונפש זהו בחי' אור וחיות עצמו כמו שהוא ממש כו'. וכמו שיש ג' מדריגות הללו דעש\"נ בנבראים מוכרח שנעשה זה מצד מקורם הראשון שהוא כח האלקי המהווה אותם, דהיינו בחי' נפש בכלל להיותו מקור כל החיים העליונים",[["3788","103","<b>מולמ\"ט דמשפיע נעשה רו\"ש דמקבל</b>: ראה גם לעיל פ' וארא סג, ד. וש\"נ."],["3789","104","<b>הן יראת ה'. . בינה</b>: איוב כח, כח."],["3790","*105","<b>דהן קודם ללאו</b>: ראה גם לקמן פ' פקודי תנו, ד."],["3791","105","<b>ולא תחללו. . ונקדשתי</b>: אמור כב, לב."],["3792","106","<b>אם אין יראה אין חכמה</b>: אבות פ\"ג, מי\"ז."],["3793","107","<b>שמחה בצפרא ורננא ברמשא</b>: זהר ויחי רכט, ב."],["3794","108","<b>דעולם שנה נפש</b>: ראה ס\"י פ\"ג, מ\"ג ואילך. מאמרי אדה\"א בראשית ע' נו ואילך. וש\"נ. לעיל פ' שמות נג, ב. וש\"נ."]]],[2300550396,"ותחתונים כו' שהוא מקור ההמשכה הכללי' להמשיך מאין ממש ליש כל מציאות הנבראים בע\"ג ויש בזה ג' מדרגות הנ\"ל. א' בחי' עולם כמו כי אמרתי עולם כו' וכן שא' והי' העולם<sup data-n=\"3795\">109</sup> שזהו להיות בריאה עצמה בבחי' יש ודבר מה שהוא מוגבל בשיעור ומדה כמלאכים שהן כוחות בגופי' דקי'<sup data-n=\"3796\">110</sup> צורה בחומר דק ביותר ומוגבלי' בשיעור ומדה (שזהו ודאי כלול מצמצום והתפשטות כא' שאם הי' <span data-k=\"pg\">940</span> ּ כח האלקי הבוראם ומהווה אותם מתפשט כפי כחו הבלתי בע\"ג הי' המהות של הבריאה מתפשט בלי גבול רק ע\"י צמצום נעשה ההגבלה וכמא' שהי' העולם מתפשט<sup data-n=\"3797\">111</sup> כו' עד שא' לעולמו די שזהו צמצום שאחר ההתפשטו', ובאמת זהו בא מצמצום שקודם ההתפשטות שהוא בחי' חשך שקודם לאור כברייתו ש\"ע כנ\"ל וד\"ל). והב' הוא בחי' שנ\"ה שזהו המשכת האור וחיות האלקי בעולמות בבחי' צמצום והתפשטות שזהו בחי' רו\"ש דוקא כנ\"ל (כמו ע\"י מא' תוצא הארץ<sup data-n=\"3798\">112</sup> כו' יש במא' זה רו\"ש כנ\"ל), וכמו דפיקו דלבא וכנשמת רוח חיים בחוטם כנ\"ל, דמצד שאור וחיות זה עולה ויורד תמיד מזה בא סיבת התהוות הזמן שבא בהתחלקות ובמשך רב כמו שמבואר במ\"א דמה שמסתלק החיות ונמשך מחדש מזה מתחלק הזמן לרגעי' ושעות וימים מאחר שהזמן ג\"כ בא בצמצום והתפשטות רו\"ש<sup data-n=\"3799\">113</sup> כו' וע\"כ מזה יבא בנבראי' ג\"כ בחי' התחלקות הזמן בגבול ומדה, והוא ג\"כ מחמת בחי' רו\"ש שבבריאה שמחמתו מתחלק הזמן מעבר והוה ועתיד ובא לחלקי' קצובים במספר כמה שנים וימים כמ\"ש כי ימים יוצרו<sup data-n=\"3800\">114</sup> כו'. וכך הוא למעלה בבחי' מל' שנק' נפש בכלל שמחי' את כולם מאין ליש שיש בבחי' ממוצע המקשר רוחני' האלקי' בעולמות והוא בחי' זמן שנק' שנה שזהו בא מבחי' רו\"ש דאלקו' בעולמות בכלל ולזאת הסיבה ימצא גם בעולם בחי' זמן מחולק בכלל בלילה ויום שממשיך זמן זה דיב\"ש הלילה ממקור הזמן בבחי' נפש הכללי' שבא בבחי' רו\"ש כנ\"ל ע\"כ יתהווה מזה בחי' זמן מחודש מאין ליש במהות העולם הנברא בבחי' גבול ג\"כ והוא משך זמן דיב\"ש הלילה וי\"ב שעות היום כו' ושרש התחלקות זו בכלל ובפרט שנק' שנ\"ה בין בנברא בבחי' גבול בין בכח האלקי הבלתי ב\"ג בא מסיבת רו\"ש דנפ\"ש בכלל ובפרט כו' וד\"ל.\n<b>ויובן</b> מזה עכ\"פ שהזמן בחי' נברא<sup data-n=\"3801\">115</sup> מחודש ובע\"ג, כמו מהות הבריאה וכך במקור הזמן שזהו שמחדש בכל יום מע\"ב, וכן בכל רגע כו' משום דכל שעה ורגע יש לו צירוף מחודש מעיקרו במקור התחלקות הזמן דשנה, כמו כל שעה דלילה נמשך מצירוף מחודש משם אד' כו' וכן בשעות ורגעי' דיום מחסד דשם הוי'. וחידוש זה בא בדרך פרט ובדרך כלל הכל רק מחמת שבא האור וחיות דנפש הכללי' בבחי' רו\"ש שהאור",[["3795","109","<b>שא' והי' העולם</b>: נוסח ברוך שאמר."],["3796","110","<b>כמלאכים. . בגופי' דקי'</b>: ראה תניא פ\"מ. מאמרי אדה\"א קונטרסים ע' רצב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670389\" data-slug=\"torat-chaim\" data-id=\"2300670389\">תו\"ח בראשית כה, ב</a>."],["3797","111","<b>שהי' העולם מתפשט</b>: ראה חגיגה יב, א."],["3798","112","<b>תוצא הארץ</b>: בראשית א, כד."],["3799","113","<b>דמה שמסתלק. . רו\"ש</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380963\" data-slug=\"likkutei-torah\" data-id=\"4001380963\">לקו\"ת בלק סה, א</a>. ר\"ה סא, א. מאמרי אדה\"א דברים ח\"ג ע' תת."],["3800","114","<b>כי ימים יוצרו</b>: תהלים קלט, טז [בהוספת תיבת כי — ראה מאמרי אדה\"א בראשית ע' רמג בהערה]."],["3801","115","<b>שהזמן בחי' נברא</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תשצג. וש\"נ."]]],[2300550413,"וחיות הראשון מסתלק ונמשך אור וחיות מחדש שלא הי' עדיין א\"כ נק' מחודש מעיקרו, ומזה בא ריבוי עיכוב הזמן מצד ריבוי ההתחלקות בפרט וגם בכלל כמו י\"ב שעות הלילה נכללי' בלילה שהוא בחי' רצוא בכלל יותר ובחי' שוב דחסד ביום שמתחלק ביב\"ש פרטיי' כו', וכך ל' יום בר\"ח וי\"ב חדש בר\"ה שכולל הכל כא' וממנו מתחלק לי\"ב חדש וכל חדש לל' יום וכל יום לכ\"ד שעות שזהו מלמעלה למטה כמ\"ש במ\"א<sup data-n=\"3802\">116</sup> וד\"ל. ועכ\"ז הגם שנתחלק זמן דיום ולילה לכ\"ד שעות מחולקי' נק' י\"ב שעות הלילה בכלל בחי' הסתלקות דרצוא ויב\"ש היום בבחי' שוב בהמשכו' החסדי' שאחר הסתלקות נמשך ההתפשטות כמ\"ש ויהי ערב כו' כנ\"ל (ולזאת עיקר ההתחדשות בכללות זהו בבוקר אור כמ\"ש חדשים לבקרים<sup data-n=\"3803\">117</sup> רבה אמונתך כאור וחיות חדש בפרט שנמשך אחר הסתלקו' <span data-k=\"pg\">תע</span> ּ אור וחיות הראשון (אע\"פ שבכל רגע דשעות הלילה יש ג\"כ רו\"ש). ומחמת זה אנו רואים שינוי אור חיות מחודש בכל בקר אור בכל הברואים שבעולם גם בבע\"ח קטן שבקטנים עד היותר עליון בצבא השמים ומלאכים עליוני' שאו' שירה בבוקר אור כמ\"ש בזהר ונק' כוכבי בקר<sup data-n=\"3804\">118</sup> והוא בקר דאברהם<sup data-n=\"3805\">119</sup> כו'. וזהו חדשי' במוחי' חדשי' לגמרי לבקרים דוקא וכמו שאמר בזוהר דשמחה בצפרא דוקא ורננה ברמשא כו', כמו שאנו רואים בנפש האדם וכל בע\"ח שבבוקר תשמח נפשו באור היום וירגיש בנפשו אור וחיות מחודש (וכמו הנותן לשכוי בינה להבחין<sup data-n=\"3806\">120</sup> כו') בשמחה וטוב לבב בחסד וטוב עם כל הבריו' כו' כי חסד אל כל בבקר מאיר בבחי' שוב למטה בכל הברואי' וגם במלאכים ונשמות שזהו שא' שמחה בצפרא דוקא. וכמו שאנו רואים בכל נשמה אלקי' באדם שבקומו בבוקר יגיל וישמח בנפשו בהשגה אלקי' והתפעלות אהבה בחדות הלב דוקא, ואם אח\"כ משפיל א\"ע בהכנעת הלב בענוה ושפלות ומרירות בכובד ראש קודם התפלה זהו שיוכל לבוא לבחי' שמחה ואהבה אלקי' שהאיר בנפשו בבוקר כמ\"ש חדשי\"ם לבקרי\"ם דוקא רבה אמונתך שמתרבה אור האמונה האלקי' בנה\"א באור חדש כנ\"ל, וזהו ענין ק\"ש ותפלה דשחרית צלותא דאברהם<sup data-n=\"3807\">121</sup> איש החסד<sup data-n=\"3808\">122</sup> כידוע. אבל בערבית כשבא אדם מן השדה בערב עיף ויגע הרי הוא בקטנות המוחין כנ\"ל ובלילה הוא בבחי' הסתלקות החיות גם בנשמות ומלאכים לפ\"ע כל הברואים למטה כו', ועכ\"ז א' בשכבך ובקומך כו' כנ\"ל שיקבל עליו עול מלכות שמים גם בק\"ש ערבית בבחי' הקטנות (והוא אמת ואמונה דערבית דאיהו אמת זהו בק\"ש שחרית שאו' אמת ויציב, כו' כמו ואמת ה' לעולם<sup data-n=\"3809\">123</sup> משום דחדשי\"ם לבקרים רב\"ה כו' בגדלות המוחי' אבל בלילה או' אמת ואמונ\"ה כל זאת בחי' נוק' בקטנות דאיה\"י אמונ\"ה בבחי' הקטנות דמקבל משא\"כ באו\"י דחסד דמשפיע שא' רבה אמונתך ממש וד\"ל).",[["3802","116","<b>כמ\"ש במ\"א</b>: ראה מאמרי אדה\"א דברים שם ע' תתא ואילך. עט\"ר ג, ב."],["3803","117","<b>חדשים לבקרים</b>: איכה ג, כג."],["3804","118","<b>כוכבי בקר</b>: איוב לח, ז."],["3805","119","<b>בקר דאברהם</b>: ראה זהר מקץ רג, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שכו."],["3806","120","<b>הנותן לשכוי בינה להבחין</b>: ברכות השחר (מברכות ס, ב)."],["3807","121","<b>דשחרית צלותא דאברהם</b>: ברכות כו, ב."],["3808","122","<b>דאברהם איש החסד</b>: נסמן לעיל פ' יתרו רנט, א."],["3809","123","<b>ואמת ה' לעולם</b>: תהלים קיז, ב."]]],[2300550430,"<b>וזהו</b> שרננה ברמשא דוקא דענין רננ\"ה זהו הבא מהצלת דבר שהי' מסוכן כמו היוצא מן השבי' ומן המלחמה וכה\"ג במי שיושב בחשך ומצפה לאור כמו נפשי אויתיך בלילה<sup data-n=\"3810\">124</sup> דוקא שהוא התגברות התשוקה ברינה לצאת מן החשך לאור, וכך בלילה יותר מתגבר אש הצמאון ותשוקה להאיר נפשו באור האלקי ולצאת מן החשך (כמו בזמן הגלות שיתגבר רשפי אש האהבה בכליון והסתלקות מצד הריחוק ביותר שהגלות נק' לילה וחשך כמו שא' העם ההולכים בחשך<sup data-n=\"3811\">125</sup> וזהו נפשי אויתיך בלילה כו' משום דרשפי אש בגלותא דוקא כו') ולכך רננ\"ה דוקא ברמשא והוא כמו בחי' רצוא שקודם לשוב וכמו בוא\"ו לפני\"ו ברננ\"ה<sup data-n=\"3812\">126</sup> שהוא בחי' או\"ח כו' וד\"ל (וזהו עבדו את ה' בשמחה<sup data-n=\"3813\">127</sup> זהו בצפר\"א בצלותא דשחרית כנ\"ל שא' חדשים לבקרים בקר דאברהם כו' בואו לפניו ברננה זהו ברמשא בתפלת ערבית (באמת ואמונה כו' שאמר השם נפשינו בחיים כו' כנ\"ל). אך מזה משמע דרננה ברמשא אחר שמחה בצפרא כפי סדר הפסוק דעבדו את ה' כו' ובאמת לילה קודם ליום כמו שרצוא <span data-k=\"pg\">942</span> ּ קודם לשוב בצמצום והתפשטות, הענין הוא דבמע\"ב היום הולך אחר הלילה שקדמה<sup data-n=\"3814\">128</sup> ובעבודה האלקי' הלילה הולך אחר היום שקדם כמו בעבודה דקרבנות בקדשים מצותן ביום דוקא ולילה שאחריו הולך אחר היום כידוע מענין נותר כו'. וכך כל עבודה אלקי' שנמשך מלמעלה למטה באו\"י כו' (והוא מטעם הנ\"ל כמו בבחי' או\"י דחסדי' דמשפיע הוא בבחי' מולמ\"ט כו' כמו אנכי ולא כו' במ\"ת ולכך גם בחי' יום ולילה שיש בתורה היום קודם ללילה כמ\"ש והגית בה יומם ולילה<sup data-n=\"3815\">129</sup> יום ואח\"כ לילה והיינו תושב\"כ שהיא ביום כמ\"ש יומם יצוה<sup data-n=\"3816\">130</sup> כו' ובלילה שירה עמי זהו רננא דאורייתא בתושבע\"פ דוקא כמ\"ש במ\"א והוא להיותו עולה בבחי' או\"ח מחושך לאור ולכך א' לא איברי לילה אלא לגירסא<sup data-n=\"3817\">131</sup> בתושבע\"פ כו' וד\"ל) (ומה שא' בק\"ש בשכבך ואח\"כ ובקומך כנ\"ל, זהו בק\"ש דוקא שהיא בהתכללות דחו\"ג לאכללא שמאלא בימינא כו' כידוע בענין ב\"פ דשמע והי' א\"ש כו'<sup data-n=\"3818\">132</sup> ובק\"ש דלילה הוא בחי' העלאה כמו בק\"ש שעהמ\"ט כו', וז\"ש יגעתי באנחתי מטתי בדמעת\"י<sup data-n=\"3819\">133</sup> כו' במרירות ושפלות דוקא. אבל מחצות לילה ואילך מתחיל בחי' החסדי' שבגבורות וז\"ש חצות לילה אקום להודות לך<sup data-n=\"3820\">134</sup> כו' וכמשז\"ל כנור הי'",[["3810","124","<b>נפשי אויתיך בלילה</b>: ישעי' כו, ט."],["3811","125","<b>העם ההולכים בחשך</b>: ישעי' ט, א."],["3812","126","<b>בוא\"ו לפני\"ו ברננ\"ה</b>: נסמן בהערה הבאה."],["3813","127","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["3814","128","<b>דבמע\"ב היום הולך. . שקדמה</b>: ראה בהתחלת המאמר."],["3815","129","<b>והגית בה יומם ולילה</b>: יהושע א, ח [ושם: בו — ראה גם תו\"ח מקץ הערה 18]."],["3816","130","<b>יומם יצוה</b>: תהלים מב, ט."],["3817","131","<b>לא איברי לילה אלא לגירסא</b>: ראה ערובין סה, א. (ראה גם) מאמרי אדה\"א שמות ח\"א ס\"ע צג ואילך."],["3818","132","<b>בק\"ש. . דחו\"ג. . שמע והי' א\"ש</b>: נסמן לעיל פ' תרומה שח, א הערה 208."],["3819","133","<b>יגעתי באנחתי מטתי בדמעת\"י</b>: תהלים ו, ז [בדילוג]."],["3820","134","<b>חצות לילה אקום להודות לך</b>: תהלים קיט, סב."]]],[2300550446,"תלוי<sup data-n=\"3821\">135</sup> כו' (ובאותו רגע זמן תיקו\"ן חצות על ח\"נ<sup data-n=\"3822\">136</sup> כו' (וא\"כ זמן רננה דאורייתא בלילה מחצות ואילך שבשעה זו מתחלק החסדי' מן הגבו'<sup data-n=\"3823\">137</sup> דקודם חצות וכמ\"ש ובלילה שיר\"ה עמי כו' וזהו הטעם שהיו קמים בחצות לילה דוקא לעסוק בתורה ובליל שבועות להיפך<sup data-n=\"3824\">138</sup> כמ\"ש במ\"א). והנה לע\"ל כתיב ולילה כיום יאיר<sup data-n=\"3825\">139</sup> (וכמו שהי' שמש בגבעון שלא אץ לבוא<sup data-n=\"3826\">140</sup> ביום<sup data-n=\"3827\">141</sup> תמים שהי' גם הלילה כיום, אך זהו מצד אור השמש שעמד בחצי השמים והאיר בלילה כמו ביום, אבל לע\"ל חושך דלילה עצמו יאיר<sup data-n=\"3828\">142</sup> כיום לפי שאור הלבנה יהי' כאור החמה<sup data-n=\"3829\">143</sup> ממש כמו שהיו שוין קודם מיעוט הירח כידוע, ולמעלה היינו שיהי' אור המל' בבחי' מאור משפיע אור כמו המאור דשם הוי' דאצי' (כמו ועינינו מאירות<sup data-n=\"3830\">144</sup> כו') וזהו שיהי' ק\"ש דערבית שוה לק\"ש דשחרית ממש גם בנש\"י ולא יהי' הפרש בין קטנות לגדלות כלל (וזהו בלא ל\"ב ול\"ב שניהן שוין כו').\n<b>וזהו</b> ושמתי כדכ\"ד שמשותיך<sup data-n=\"3831\">145</sup> כו' ב\"פ כ\"ד אותיות דשמע ישראל<sup data-n=\"3832\">146</sup> שחרית וערבית שיהי' באור בהיר בעצם כמו הכדכ\"ד שאין הכלי מעלים ומסתיר<sup data-n=\"3833\">147</sup> לאור כלל כמ\"ש במ\"א וד\"ל, והטעם הוא כי הוי' ואלקים עכשיו כשמש ומגן<sup data-n=\"3834\">148</sup> ע\"י הסתר והעלם דוקא לפי שההמשכה נמשכת ממשפיע למקבל בדרך עו\"ע שבזה שייך בחי' צמצום והתפשטות ברו\"ש דוקא, וכענין ביטול היש לאין שגורם המשכה מאין ליש כמו הזריעה בארץ כו' כנ\"ל. אבל לע\"ל לא יהי' בדרך המשכה במשפיע ומקבל כלבנה דעכשיו שמקבלת מן השמש שבהכרח שצריך שתהי' תחלה בבחי' נקודה בקירובה לשמש שנק' מולד הלבנה ואח\"כ תתפשט לקבל ככלה שמקבלת מחתן, אבל לע\"ל גם בבחי' המל' יהי' בדומה למשפיע וכמ\"ש ולילה כיום יאיר כנ\"ל (וכמו שאו' עתידה ארץ שתוציא גלוסקאות<sup data-n=\"3835\">149</sup> כו' שזהו מי\"ש ליש שלא בסיבת ביטול יש לאין כזריעה כו' וכן עתידה אשה שתלד בכל יום<sup data-n=\"3836\">150</sup> מכח עצמה שלא ע\"י איש כמו אשה כי תזריע<sup data-n=\"3837\">151</sup> וילדה <span data-k=\"pg\">תעא</span> ּ מעצמה כו'). וזהו דעו כי הוי' הוא האלקים<sup data-n=\"3838\">152</sup> בשוה ממש כמ\"ש הוי' אחד ושמו אחד<sup data-n=\"3839\">153</sup> למהוי אחד באחד<sup data-n=\"3840\">154</sup> ממש (שזהו כשזו\"ן שוין בקומתן<sup data-n=\"3841\">155</sup> וכתר א' לשניהם כו'). אך הנה גם עכשיו יש בדוגמא זו ממש רק שהוא בהעלם ולא בגילוי",[["3821","135","<b>כנור הי' תלוי</b>: ברכות ג, ב. ראה גם לעיל פ' בא פח, ג. וש\"נ."],["3822","136","<b>תיקו\"ן חצות על ח\"נ</b>: ראה גם לקמן שכה, א. ד\"ח ו, ב. שעה\"י קיג, סע\"ב."],["3823","137","<b>מחצות. . . מתחלק החסדי' מן הגבו'</b>: ראה גם לעיל פ' בא פח, ב ואילך."],["3824","138","<b>ובליל שבועות להיפך</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתקכ (ובהנסמן במ\"מ לשם). מאמרי אדה\"א ויקרא ח\"ב ע' תרמ ובהנסמן שם. במדבר ח\"ב ע' שכו."],["3825","139","<b>ולילה כיום יאיר</b>: תהלים קלט, יב."],["3826","140","<b>שלא אץ לבוא ביום תמים</b>: יהושע י, יג."],["3827","141","<b>ביום</b>: אינו ברור בגוכי\"ק ואולי כתוב כיום."],["3828","142","<b>חושך דלילה עצמו יאיר</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קסט ואילך."],["3829","143","<b>שאור הלבנה יהי' כאור החמה</b>: ישעי' ל, כו. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג."],["3830","144","<b>ועינינו מאירות</b>: תפלת נשמת. ראה גם לעיל פ' בשלח רג, ד. וש\"נ."],["3831","145","<b>ושמתי כדכ\"ד שמשותיך</b>: ישעי' נד, יב."],["3832","146","<b>כדכ\"ד. . ב\"פ כ\"ד אותיות דשמע ישראל</b>: ראה גם לקמן שמו, ג. מאמרי אדה\"א ויקרא ח\"א ע' שג. תו\"ח ח\"ש קלז, ג ובהערה 41."],["3833","147","<b>הכדכ\"ד שאין הכלי מעלים ומסתיר</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ס\"ע קצג. מארז\"ל ע' תפג בנו\"א. מאמרי אדה\"א דברים ח\"ב ס\"ע תמה."],["3834","148","<b>הוי' ואלקים עכשיו כשמש ומגן</b>: ראה שער היחוד והאמונה רפ\"ו. לעיל פ' שמות לד, ד. וש\"נ."],["3835","149","<b>עתידה ארץ שתוציא גלוסקאות</b>: ראה שבת ל, ב. לעיל פ' שמות כג, ב. וש\"נ."],["3836","150","<b>עתידה אשה שתלד בכל יום</b>: נסמן בהערה שלפנ\"ז."],["3837","151","<b>אשה כי תזריע</b>: תזריע יב, ב. ראה גם לעיל פ' שמות ט, ג. וש\"נ."],["3838","152","<b>דעו כי הוי' הוא האלקים</b>: תהלים ק, ג."],["3839","153","<b>הוי' אחד ושמו אחד</b>: זכרי' יד, ט."],["3840","154","<b>למהוי אחד באחד</b>: זהר תרומה קלה, סע\"א."],["3841","155","<b>כשזו\"ן שוין בקומתן</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו, פ\"א. פ\"ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצג ואילך."]]],[2300550461,"גמור כמו לע\"ל והוא מה שמתכללי' חו\"ג דהוי' ואלקי' גם עכשיו כמו שיהי' לע\"ל ממש (וכמו בשבת שאו' כגוונא דאינון<sup data-n=\"3842\">156</sup> כו' אוף הכי ממש כו' וכמו כ\"ו כל\"ח שמאירי' חסדי' דהוי' באלקי'<sup data-n=\"3843\">157</sup> בלי הסתר כלל כידוע). כי הנה הגם שמבואר למעלה בשרש התחלקות דיום ולילה בא מבחי' רו\"ש צמצום והתפשטות שהן ב' הפכי' כו' מ\"מ הרי הן מתכללי' כא' ממש אף במע\"ב, שהרי א' ויהי ערב ויהי בוקר יום אחד דכללות שניהם דערב ובוקר יחד נק' יום אחד ממש אבל בקר בלא ערב אינו יום כלל, וא\"כ גם הלילה בכלל יום נחשבת אע\"פ שא' ויהי ערב בפ\"ע ויהי בוקר בפ\"ע כו' שהן יב\"ש דלילה שהוא מבחי' הצמצום ליב\"ש דיום מחסדי' כנ\"ל. אבל יש עכשיו יחוד דהוי' ואלקים ע\"כ בכללותם יחד נק' יום אחד כיום דלע\"ל שלילה כיום יאיר ויהי' נק' יום אחד יום הגדול שכלול מכ\"ד שעות רק עכשיו הבדל בין לילה ויום בחושך ואור, אבל למעלה גם עכשיו יום אחד הוא ממש ואין הפרש כלל בין לילה ויום. וראי' מיום דשבת שהוא מעין דלע\"ל ביום שכולו שבת<sup data-n=\"3844\">158</sup> בעוה\"ב כידוע ע\"כ גם הלילה דשבת כיום יאיר למעלה למהוי אחד באחד כי מל' דאצי' בבריא' בשוה ליח\"ע דז\"א כמ\"ש אוף הכי ממש איהי כו'. וזהו צלותא דמ\"ש<sup data-n=\"3845\">159</sup> בתענוג האלקי להתענג על הוי' כמו שהוא באצי' ממש רק שהוא בתענוג דאו\"ח וביום השבת הוא בתענוג דאו\"י. אבל בבחי' התענוג העצמי דשבת כמו שעשועי' העצמי' דעוה\"ב אין לחלק כלל בין או\"ח לאו\"י ושניהם כלולים כא' ממש, ואע\"פ שהוא ג\"כ בבחי' רו\"ש צמצום והתפשטות, וזהו הילוך ב' שבתות כהלכתן<sup data-n=\"3846\">160</sup> שנק' שבתות שמתכללי' כא' ממש כו'), וכמו השיר והניגון בשפלות והגבהה כו'. אבל הכל א' ממש להיות הכל בבחי' עונג העצמי' ונק' אה\"ר בתענוגים דאו\"ח ואו\"י יחד והוא שרש תפלת השבת שמובדל במעלה מתפלת החול במה שנק' שיר אל<sup data-n=\"3847\">161</sup> בשיר שבא בעונג שלמעלה מן השכל בבחי' עצמיות ממש שאין לחלק בו בין העלאה והמשכה רו\"ש (כמו בנגינות וטעמים דתורה שגם הן בבחי' רו\"ש מלעיל ומלרע כו' וכלולים כא' ממש ונק' רננא דאורייתא שלילה ויום שוין ממש דלילה עיקר רינה של תורה וכמ\"ש ובלילה שירה עמי שוה לשיר דמשפיע שנק' שירות באו\"י בתענוג העצמו' בחכ' דתורה הקדומה שא' ואהי' אצלו שעשועי' משחקת לפניו ממש כו' וד\"ל). משא\"כ בתפלת החול שבחי' הגבו' דאו\"ח הוא במרירות ושפלות וקטנות המוחין כמו כובד ראש כו' שמובדל מבחי' החסדים דשוב בגדלות המוחין בשמחה בהרחבת ההשגה ולא ישכנו כא' כלל כנ\"ל (כמשי\"ת).",[["3842","156","<b>בשבת שאו' כגוונא דאינון</b>: סדר קבלת שבת מזהר תרומה קלה, א."],["3843","157","<b>כ\"ו כל\"ח שמאירי' חסדי' דהוי' באלקי'</b>: ראה גם לעיל פ' בשלח קמד, א. וש\"נ."],["3844","158","<b>מיום דשבת. . שכולו שבת</b>: ראה גם מכילתא תשא לא, יג. לעיל פ' שמות לג, ג. וש\"נ."],["3845","159","<b>דמ\"ש</b>: דמעלי שבתא."],["3846","160","<b>ב' שבתות כהלכתן</b>: שבת קיח, ב."],["3847","161","<b>תפלת השבת. . שיר אל</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקו. הנסמן לקמן הערה 475."]]],[2300550476,"<b>וזהו</b> וידעת היום והשבות אל לבבך<sup data-n=\"3848\">162</sup> כו' הזכיר כאן ג' דברים שכלולי' מבחי' <span data-k=\"pg\">944</span> ּ רו\"ש שהן בחי' יום ולילה ערב ובוקר ותלויי' זה בזה כפי הסדר שאומר תחלה וידעת היום דוקא שזהו יום אחד שכלול מערב ובוקר יחד שנק' יום, שהן בחי' הצמצום וההתפשטו' דנשמה במוח הדע\"ת שכולל חו\"ג<sup data-n=\"3849\">163</sup> באוי\"ר שבמוח עדיין שכלול בדעת והשגה האלקי' שזהו בחי' ב' דיעות ד\"ע וד\"ת שהוא הוי' ואלקי' שאומר בסוף כו'. שבד\"ע שהוא מיש לאי\"ן (שהוא שם הוי') בחי' סוכ\"ע בכלל מרחוק הוי' נראה לו<sup data-n=\"3850\">164</sup> דלמחת\"ב<sup data-n=\"3851\">165</sup> כו' ע\"כ מתפעל באהבה בחי' רצוא בכליון והסתלקות כמו אליך הוי' נפשי אשא<sup data-n=\"3852\">166</sup> כו', ומבחי' השגה בד\"ת שהוא מאין ליש בממלא בצמצום דשם אלקים שמקרוב יפול באימה ופחד גדול בבחי' שוב לאחו\"ר כו'. ואמנם במוח הדעת שכלול מחו\"ג יחד כולל ב' מיני דעות ד\"ע וד\"ת כא' ויתכלל במוח אוי\"ר יחד כו' וכמו וגילו ברעדה<sup data-n=\"3853\">167</sup> שא' במקום גיל\"ה עצמ\"ה שם תהא רעדה, דחדוה וגילה במוח הוא בהשגה מרחוק דסובב שמיש האמיתי לאין ובמקום גילה זו עצמה תהי' רעדה ופחד אלקי' מקרוב בהשגה דממלא כו' מאין ליש דכח הפועל האלקי בנפעל כו', וז\"ש עבדו את ה' ביראה<sup data-n=\"3854\">168</sup> דוקא וגילו ברעדה ולפעמים א' עבדו את ה' בשמחה תחלה שזהו בהמשכת אלקות בתו\"מ מסובב דהוי' ואלקי' אבל בק\"ש מייחד יחוד דהוי' ואלקי' במוח הדעת, וז\"ש וידעת היום שיום זה כלול מערב ובקר דערבית תחלה רק וגילו ברעדה כו'. וזהו ג\"כ מ\"ש ואהבת ב\"פ אור<sup data-n=\"3855\">169</sup> או\"י ואו\"ח שזהו התכללות דאהבה מיראה ויראה מאהבה גם בלב והוא בכל לבבך בב' לבבות<sup data-n=\"3856\">170</sup> שיתייחדו כא' ברצוא ושוב בדפיקו דלבא כו', והוא מ\"ש והשבות אל לבב\"ך דהיינו מה שבמוח הדעת וידע\"ת היו\"ם בהתכללות דערב ובקר כך גם בלבבך שהל\"ב יקבל מל\"ב חדרי' שבמוח הדע\"ת שבדעת חדרים<sup data-n=\"3857\">171</sup> כו', והוא מה שיתפעל האדם ברו\"ש בלב בתשוקה וכליון בצמאון ביסוד האש<sup data-n=\"3858\">172</sup> בבחי' רץ לב\"ך<sup data-n=\"3859\">173</sup> או בלב נשבר ובכי' על ריחוקו מיחודו ית' והולך אחורנית בבחי' פירוד מאלקות דבכי' זו ג\"כ מתוך האהבה והתשוקה שחפץ בקרבת אלקים מאד ע\"כ ימר לו ביותר עד שימאס בחיי הבלו כו' ונק' גבו' שבחסד כידוע (שזהו כקשר ע\"ג קשר שנק' אהבה דכלילת מב' סטרי'<sup data-n=\"3860\">174</sup> דחו\"ג מתקיימת כו'. וזהו כמו שא' בכי' תקיע בלבאי מסט' דא וחדוה מסט' דא<sup data-n=\"3861\">175</sup> דהכל בהתפעלות אחת בהשגה אלקי' שבמוח הדעת כנ\"ל שנמשך בלב יולד ב' הפכים כאלה יחד ברו\"ש בכי' וחדוה, בכי' מצד הריחוק שזהו שבא מהשגה דכח האלקי' המחי' לנשמתו מקרוב שיפול פחד ויראה",[["3848","162","<b>וידעת היום והשבות אל לבבך</b>: ואתחנן ד, לט."],["3849","163","<b>הדע\"ת שכולל חו\"ג</b>: ראה גם לעיל פ' וארא נז, ד. וש\"נ."],["3850","164","<b>מרחוק הוי' נראה לו</b>: ע\"פ ירמי' לא, ב."],["3851","165","<b>דלמחת\"ב</b>: ת\"ז בהקדמה (יז, א)."],["3852","166","<b>אליך הוי' נפשי אשא</b>: תהלים כה, א."],["3853","167","<b>וגילו ברעדה</b>: תהלים ב, יא. ברכות ל, ב. ראה גם שע\"ת לה, א ובהערה 1. לקמן פ' ויקהל תיג, א."],["3854","168","<b>עבדו את ה' ביראה</b>: התחלת הכתוב וגילו ברעדה."],["3855","169","<b>ואהבת ב\"פ אור</b>: ואתחנן ו, ה. פע\"ח (שער הק\"ש) ש\"ח, פכ\"ג. ראה לעיל פ' וארא סה, ג. וש\"נ."],["3856","170","<b>בכל לבבך בב' לבבות</b>: ראה ואתחנן ו, ה. תנחומא תבא א בסופו. ספרי ואתחנן שם. ברכות נד, א (במשנה). מאמרי אדה\"א דברים ח\"ד ע' א'תקו. וש\"נ."],["3857","171","<b>שבדעת חדרים</b>: משלי כד, ד."],["3858","172","<b>בלב. . ביסוד האש</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>. מאמרי אדה\"א בראשית ע' שצ. וש\"נ."],["3859","173","<b>רץ לב\"ך</b>: ס\"י פ\"א, מ\"ח."],["3860","174","<b>אהבה דכלילת מב' סטרי'</b>: ראה זהר בהקדמה יא, סע\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670314\" data-slug=\"torat-chaim\" data-id=\"2300670314\">תו\"ח בראשית לח, ג</a> ובהנסמן במ\"מ לשם."],["3861","175","<b>בכי' תקיע בלבאי. . מסט' דא</b>: ראה זהר אחרי עה, א. (היכלות) פקודי רנה, א. לעיל פ' וארא סח, ב. וש\"נ."]]],[2300550491,"כנ\"ל וחדוה מצד השגה דסובב בשם הוי' כו' כמו כי חדות ה' מעוזו<sup data-n=\"3862\">176</sup> וכן עבדו הוי' בשמחה כו', ונמצא כלול בלב ג\"כ מד\"ע וד\"ת שבמוח הדעת. וזהו שאומר בסוף על כל ב' דברים האלה שא' וידעת היום והשבות אל לבבך מהו ידיעה זאת ומה היא השבה זו ללבבך הוא רק מה שהוי' הוא האלקי' דהיינו ב' מדרגות דסובב וממלא שנק' ד\"ע וד\"ת שאינם ב' הפכים כלל דכולא חד ממש וכמו\"ש כי אל דיעות ה'<sup data-n=\"3863\">177</sup> כו' שסובל ב' הדיעות הנ\"ל יחד להיות דד\"ע וד\"ת זה אינו שייך רק <span data-k=\"pg\">תעב</span> ּ בבחי' ההשתלשלו' דממלא וסובב דוקא שצ\"ל מאין ליש ומי\"ש לאין שזהו ע\"י העלם והסתר אור העצמות ממש, אבל קמי' מהו\"ע ממש אין חילוק כלל (וכמשי\"ת) בין ד\"ע לד\"ת ויהי' שוה ד\"ת דשם אלקים שהוא מאין ליש כמו בחי' ד\"ע שמי\"ש לאי\"ן למהוי אחד באחד ממש כמו שיהי' לע\"ל שיהי' אור הלבנה כאור החמה כו' ויהי' הוי' אחד ושמו א' שניהם בשוה כו' כנ\"ל וד\"ל.\n<b>וזהו</b> שא' שבמקום גדולתו<sup data-n=\"3864\">178</sup> שם דוקא אתה מוצא הענוה שלו דלא כמדות באדם בחו\"ג בצמצום והתפשטות שלו דא\"א שיהי' שניהם כא' ממש דכשהוא בגדולה ורוממות בהתפשטות כמו בשמחה וטוב לב א\"א שיהי' אז בשפלות וענוה בצמצום עצמותו (או באוי\"ר כא' רק בהתפעלות אלקות יוכללו כא' כנ\"ל), אבל למעלה מתכללים ב' הפכים אלו שבמקום גדולתו שלגדולתו אין חקר<sup data-n=\"3865\">179</sup> כלל כמו שהוא בבחי' ד\"ע דסובב כ\"ע הכללי שם דוקא אתה מוצא ענוה וצמצום שלו שהוא בחי' ד\"ת שמאי\"ן ליש בצמצום דחוש\"ך קודם לאור כו' לפי שסובל ב' הדעות יחד (דגם מה שאוא\"ס למעלה מעלה עד אין קץ בעמ\"ר דשמים ממעל ובהמשכה וירידה למטה עד אין תכלית<sup data-n=\"3866\">180</sup> בארץ מתחת בעמ\"ת הכל בשוה אצל מהו\"ע ית' ממש בבחי' אין עוד מלבדו<sup data-n=\"3867\">181</sup> דאין שינוי כלל בין קודם ההשתל' לאחר ההשתלשלו' ע\"כ בארץ מתחת בממלא בחי' ד\"ת מאין ליש אין עוד מלבדו כמו בשמים ממעל ביח\"ע דמיש לאין ממש מטעם הנ\"ל וז\"ש וידעת כו' כי הוי' הוא האלקי' שמטעם זה דוקא בשמים ממעל ועל הארץ כו' אין עוד בשוה (או ה' הוא האלקים בשמים כו' דיחוד זה דה' אלקים הוא בעמ\"ר ועמ\"ת בדעת עליון ובדע\"ת אי\"ן עוד). וראי' לזה ממה דתפיס בכ\"ע<sup data-n=\"3868\">182</sup> בבחי' ממלא ולית מאן דתפיס בי' כו' כנ\"ל, א\"כ גדול\"ה וענו\"ה כא' הן ואין הצמצום דענוה שנתפס בעולמות נפרד מן החסד דגדולה דהוי' דלמת\"ב ואין העולם מקומו אפי' בשעה שהוא מקומו ש\"ע<sup data-n=\"3869\">183</sup> כנ\"ל וד\"ל. (וגם בבחי' מל' דאצי' עצמה שעולה למעלה בבחי' רצוא באצי' שנבנה בבנין חדש בגדלות המוחין כו' ואח\"כ יורדת למטה להיות כתר לבי\"ע בקטנות המוחין בבחי' שוב אין ירידה זו בבי\"ע נפרד כלל מבחי' עלי' זו דרצוא בהיותה באצי' אלא כעלי'",[["3862","176","<b>כי חדות ה' מעוזו</b>: ע\"פ נחמי' ח, י."],["3863","177","<b>כי אל דיעות ה'</b>: שמו\"א ב, ג."],["3864","178","<b>שבמקום גדולתו</b>: ראה מגילה לא, א. הנסמן לעיל פ' יתרו רנט, ב."],["3865","179","<b>שלגדולתו אין חקר</b>: תהלים קמה, ג."],["3866","180","<b>שאוא\"ס למעלה. . עד אין תכלית</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). סתנ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670361\" data-slug=\"torat-chaim\" data-id=\"2300670361\">תו\"ח נח סט, ב</a> ובהערה 11. לעיל פ' תרומה שיז, ג. לקמן שלב, א. פ' ויקהל שפח, ד."],["3867","181","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["3868","182","<b>ממה דתפיס בכ\"ע</b>: ראה זהר (רע\"מ) פינחס רכה, א. לעיל פ' יתרו רסב, א. וש\"נ."],["3869","183","<b>ואין העולם מקומו. . בשעה שהוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."]]],[2300550505,"וירידה דאור הנר שמיד שעולה יורד ומיד שיורד עולה כך ירידה זו בשביל העלי' כו' כמו גדולה וענוה שמתכללי' כא' ממש מטעם הנ\"ל, וראי' משבת דמל' דאצי' אתייחדת לתתא ממש כמו לעילא באצי' כו' וליל שבת דומה ליום בעלי' וירידה בתענוג דאו\"ח ואו\"י שכלולים כא' ממש כנ\"ל, וברו\"ש דתענוג שבח\"ע דתורה כנ\"ל).\n<b>ובזה</b> יתורץ מה שא' דעוז וחדוה במקומו<sup data-n=\"3870\">184</sup> דוקא באצי' ולמעלה, אבל בבי\"ע יש עוצב ובכי' כמו רחל מבכה<sup data-n=\"3871\">185</sup> כו' והלא אין עצבות לפני המקום<sup data-n=\"3872\">186</sup> וכמו שגזרו אומר שאין מתפללי' מתוך עצבות<sup data-n=\"3873\">187</sup> כו' שאין גילוי שכינה רק בשמחה כו', ואע\"פ שצ\"ל כובד ראש קודם התפלה כו', לפי שלמעלה מתכללת הגבו' דצמצום בעוצב בחדוה ושמחה דחסדי' כמו שהענוה נכללת בגדולה ע\"כ אין עצבות כלל למעלה, ומה שיש ירידה <span data-k=\"pg\">946</span> ּ ועלי' הכל בשמחה ועונג העליון שכלול מרו\"ש יחד וע\"כ אין שינוי כלל במל' דאצי' בעלי' וירידה שבה כמו גם מחול לשבת ומשבת לחול דאע\"פ שבחול יורד האור האלקי מאין ליש בעולמות גם בחיצוני' ובבירורי' דל\"ט מלאכות מרפ\"ח כו' שנק' וי\"ו ימי המעשה ובשבת עולה למעלה באצי' מלמעלה מן הבירורי' בפנימי' בחכ' כמו שהוא מי\"ש לאי\"ן בד\"ע כו' ואין חילוק כלל מטעם הנ\"ל וד\"ל) (משא\"כ ברו\"ש שבבי\"ע שנחלק לערב ובוקר הרי בחי' הצמצום שנק' חשך קדם לאור דהתפשטו' וכברייתו ש\"ע ברישא חשוכא כו' א\"כ אינם כא' ממש, כי במקום חושך אין אור ואין באור חושך שנבדלו זה מזה וכענין הנ\"ל בעולמות וכל הברואי' שהפועל ברא בהם ג\"כ באופן זה דצמצום ואח\"כ התפשטות בחשך ואור, שא\"א שיהי' כל ברי' במעמד אחד אלא יורד ועולה ובמקום שפלות אין עליי' והגבהה כו' ובשינוי הזמנים בטו\"ר שיש לכל א' עיתים מיוחדים ואין א' מתערב ושולט בחבירו כו' וכן בלא ביטול היש לאין א\"א להיות מאין ליש כמו בזריעה וכן בתפלה ובתורה כו'.\n<b>אך</b> הנה כל זה אינו רק בבחי' השתלשלות דממלא כו' כנ\"ל דאצי' בבריאה דוקא אחר בחי' המסך כו' וכמ\"ש כברייתו ש\"ע כו', אבל גם בזה הצמצום אין שינוי כלל וכמו שאו' אתה הוא קודם שנבה\"ע<sup data-n=\"3874\">188</sup> כו' כמו שהוא במל' דאצי' באצי' ממש כמו בשבת כנ\"ל דאין חול ושבת רק בבחי' של הצמצום והתפשטות בבי\"ע, אבל בבחי' האצי' עצמו שוין שם עלי' וירידה זו דגם שבירידה הוא כמו בעלי' וכמו בליל שבת דאתייחדת לתתא כו' ואז ימצא גם בנש\"י בחי' זו דרו\"ש עלי' וירידה כא' ממש, כמו השמחה ורוממות עם הענווה ושפלות דבמקום הגדולה ורוממות ימצא בעצמו השפלות וענוה בתכלית ובמקום הענוה ושפלות",[["3870","184","<b>דעוז וחדוה במקומו</b>: דהי\"א טז, כז."],["3871","185","<b>רחל מבכה</b>: ירמי' לא, יד."],["3872","186","<b>אין עצבות לפני המקום</b>: ראה חגיגה ה, ב."],["3873","187","<b>שאין מתפללי' מתוך עצבות</b>: ראה ברכות לא, א."],["3874","188","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה ג, ב. שעה\"י קטז, א ובהערה 1."]]],[2300550519,"יהי' בהגבהה ושמחה כמו למעלה שבמקום גדולתו כו', דהיינו שבחי' אי\"ן וי\"ש שוין ממש דצמצום דענוה בבחי' אין ובחי' התפשטו' דגדולה בבחי' יש שוין ויכול להחליף מזו לזו ברגע א' שישלטו כא' אע\"פ שהן ב' הפכי' ממש, וכנ\"ל בענין במקום גילה עצמה שם תהא רעדה כו' שהשמחה מבחוץ ורעדה מבפנים כמו קרב וכליות יזמרו ולבבות ויראוך<sup data-n=\"3875\">189</sup>, או בהיפוך באהבה דאברהם<sup data-n=\"3876\">190</sup> שכלולה בפחד יצחק ופחד יצחק כלולה באהבה דאברהם וישכנו כא' וכמו בכי' וחדוה בלב כא' ממש וכן כובד ראש ומרירות ושמחה אלקי' כא' ממש כו' ולא בהתחלקות זו מזו כלל אלא כלולים יחד (והי' דוגמא כזו בכמה צדיקים וכמו אברהם שהי' בדביקות האהבה רבה והי' בפחד ויראה ברגע זו עצמה כמ\"ש לו כי ירא אלקים אתה<sup data-n=\"3877\">191</sup> וביצחק פחד בחוץ ותוכו רצוף אהבה כו', וכן במשה בבחי' החכ' שמאי\"ן ליש תמצא ממש בתושב\"כ ושבע\"פ והוא עצמו בחי' מ\"ה ואין בעצם כאילו אינו במציאות כלל (והוא שהי' כב\"ד פ\"ה<sup data-n=\"3878\">192</sup> דחכמה בהיותו בבחי' אין דד\"ע דקמי' ממש כלא ממש חשיב ונק' ירא בושת<sup data-n=\"3879\">193</sup> ואוכם הוא לגבי עה\"ע<sup data-n=\"3880\">194</sup> ונעשה מאי\"ן ליש ב' הפכי' כא' מוכרח שסובל ב' דעות כמו מיש לאין הא' ומאי\"ן ליש כמו כל ממוצע<sup data-n=\"3881\">195</sup> כו' ולכך במ\"ת הי' ממוצע כמ\"ש מש\"ה ידב\"ר<sup data-n=\"3882\">196</sup> כו'.\n<b>והיינו</b> הטעם דרו\"ש דאי\"ן <span data-k=\"pg\">תעג</span> ּ וי\"ש כלולים כא' (וכאור הכת\"ר שנמשך מבחי' האחרונה שבעצמו' ונעשה ראש וכתר לנאצלים<sup data-n=\"3883\">197</sup> כמ\"ש אני ראשון<sup data-n=\"3884\">198</sup> שכולל אי\"ן וי\"ש אי\"ן למעלה ויש למטה ואינם ב' הפכי' כלל (כמו מי\"ש האמיתי לאי\"ן האמיתי דעצמו' א\"ס שכלולי' כא' כמו במקום גדולת\"ו העצמי' בבחי' יש האמיתי שבענוה דאי\"ן האמיתי), וכן בד\"ת מאי\"ן לי\"ש בבחי' המל' שלמעלה באצי' הוא בחי' אי\"ן כנקודה א' ובבי\"ע נעשה כתר וראש ונק' מטרוניתא ואימא תתאה<sup data-n=\"3885\">199</sup> ובחי' מלך על עם כו' (ואין זה היפוך מדלעיל שבאצי' המל' בגדלות המוחין כו' דגם זה אמת דמה שהיא בבחי' אין באצי' ה\"ז בבחי' גדלו' למעלה הרבה ממה שהמל' ראש לשועלים כו' מאי\"ן לי\"ש ממש (ויתפרש להיפוך במקום גדולתו בהתפשטו' מלך על עם שם ענוה שלו כמו שהוא באי\"ן דבחי' האצי' והכל שרש וענין א' הוא, שיוכל להיות דבר והיפוכו כא' ממש והיינו מבחי' אין יש ומי\"ש אי\"ן ברגע א' שהוא כמו הגדולה והענוה שיהי' כא' ממש. וכמו שמצינו בדוד מ\"י שהי' בחי' מרכבה למל'<sup data-n=\"3886\">200</sup> דאצי' כמו",[["3875","189","<b>קרב וכליות. . ויראוך</b>: ע\"פ תפלת נשמת. ראה מאמרי אדה\"א שמות ח\"א ע' מז. וש\"נ."],["3876","190","<b>באהבה דאברהם</b>: ראה גם אגה\"ק סי\"ג. מאמרי אדה\"א דברים ח\"ד ע' א'תלג, וש\"נ."],["3877","191","<b>כי ירא אלקים אתה</b>: וירא כב, יב."],["3878","192","<b>במשה. . כב\"ד פ\"ה</b>: ראה גם לעיל פ' יתרו רנו, ג ובהנסמן שם. לקמן פ' פקודי תנח, א."],["3879","193","<b>ירא בושת</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תט. לעיל פ' שמות יב, ב. וש\"נ."],["3880","194","<b>ואוכם הוא לגבי עה\"ע</b>: נסמן להלן הערה 228."],["3881","195","<b>שסובל ב' דעות. . ממוצע</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'ריד. וש\"נ. הנחות תקע\"ז ע' פא. וש\"נ."],["3882","196","<b>ממוצע. . מש\"ה ידב\"ר</b>: יתרו יט, ט. ראה גם לעיל פ' שמות יא, ג. יב, ב וארא פ, א. בשלח קנה, ג. יתרו רנו, ד. לקמן שמו, ד. פ' פקודי תנא, ג. מאמרי אדה\"א בראשית ע' תח. שמות ח\"א ס\"ע רלג ואילך. דברים ח\"ג ע' תשפג. הנחות תקע\"ז ע' נז. וראה שע\"ת קלג, א."],["3883","197","<b>הכת\"ר. . וכתר לנאצלים</b>: ראה גם לעיל פ' שמות יא, ג. וש\"נ."],["3884","198","<b>אני ראשון</b>: ישעי' מד, ו."],["3885","199","<b>המל'. . מטרוניתא ואימא תתאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא רפנ\"ב. ש\"א טו, סע\"ב</a> ובהנסמן במ\"מ לשם."],["3886","200","<b>בדוד. . מרכבה למל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג, מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."]]],[2300550532,"שהיא באצי' ונעשה כתר וראש לבי\"ע כידוע, וע\"כ הי' בו ב' הפכי' הללו דאי\"ן וי\"ש כא' ממש והוא הגדולה וענוה שבמקום גדולתו בהתפשטו' מלכותו על כ\"י ברוממות והתנשאות גדולה ביותר כטבע רוממו' המלוכה ובאותה שעה עצמה ממש הי' בעצמו בבחי' ביטול גדול מי\"ש לאי\"ן ושפלות בענוה יתירה, עד שהי' שפל ונבזה בעיניו כאחד הריקים כמו שהי' מפזז ומכרכר<sup data-n=\"3887\">201</sup> כו' וא' ונקלותי עוד מזאת<sup data-n=\"3888\">202</sup> כו' וקרא עצמו רש ונקלה<sup data-n=\"3889\">203</sup> עני ואביון<sup data-n=\"3890\">204</sup> והי' בשפלות ומרירות כבע\"ת ועני גמור בלב נשבר באמת, והי' מלך בהתנשאות יש גדול ואימה יתירה ב' הפכי' כא', לפי שהי' מרכבה למל' דאצי' שלמעלה בבחי' אין ולמטה בבי\"ע בבחי' י\"ש (או בהיפוך במקום גדולתו באצי' נמצא ענוותנותו להיות ראש לשועלים בבי\"ע כו'), דזהו ג\"כ ב' הפכי' דאי\"ן ויש כא' ממש כו' (והוא לפי שהמל' עומדת תחת קו האמצעי דת\"י<sup data-n=\"3891\">205</sup> שכולל ב' הפכי' דחו\"ג יחד ולכך מל' מקבל ב' הפכי' יחד (כמ\"ש במ\"א בענין אתרוג שדר באילנו<sup data-n=\"3892\">206</sup> כו'). ולכך המל' דוקא עולה עד הכת\"ר שלמעלה מהתחלקות קוין דחו\"ג שיש בו ב' הפכי' אלה דאין ויש מצד שנק' ממוצע כנ\"ל וד\"ל).\n<b>וכך</b> יכול להיות גם בכאו\"א כח אלקי הזה שכולל ב' הפכי' דאי\"ן וי\"ש, שנעשה מי\"ש לאי\"ן בביטול ושפלות גדולה וברגע זו עצמה מאי\"ן ליש בהגבהה ורוממות בחדוה אלקי' וכמ\"ש בכי' מסט' דא כו', רק בתפלת החול שהוא בבחי' ההשתל' רחוק זה מזה דמרירות ושפלות קודם להגבהה וכמו כובד ראש קודם התפלה, וכך הוא במילי דעלמא בפרנסה שמתייאש בשפלות ואח\"כ מצליח וכן בלימוד כו' כנ\"ל. אבל בתפלת השבת (וכן בק\"ש בכל יום שהוא מעין אור דשבת<sup data-n=\"3893\">*207</sup> כידוע) אין הענוה ושפלות נבדל מן הרוממו' והגבהה דהיינו אי\"ן וי\"ש כו' (כמו בדוד מ\"י ואוי\"ר באבות ומ\"ה דחכ' דמשה כנ\"ל) והוא כמו רו\"ש דתענוגי' דאו\"ח ואו\"י בשיר וניגון (וכר\"מ דמצלי בכל מיני ניגון<sup data-n=\"3894\">207</sup> כו' שאין הפרש כלל בין מרירות ושפלות לחדוה והגבהה בתנועות של השיר<sup data-n=\"3895\">*208</sup> הפשוט כו', וכמו במקום גילה עצמה תהא רעדה כו' לפי שזהו בדומה למעלה ממש שה' הוא האלקי' ד\"ע וד\"ת שוין ממש כנ\"ל ע\"כ מתכללים ב' הפכים דרו\"ש במוח ולב כנ\"ל. ובזה יתורץ בהפרש שבין תורה לתפלה דבאו\"י מולמ\"ט הן קודם <span data-k=\"pg\">948</span> ּ ללאו ובאו\"ח דתפלה לאו קודם להן דיראה קודם לאהבה לכך סומ\"ר תחלה דאם אין",[["3887","201","<b>מפזז ומכרכר</b>: שמו\"ב ו, טז."],["3888","202","<b>ונקלותי עוד מזאת</b>: שם שם, כב."],["3889","203","<b>וקרא עצמו רש ונקלה</b>: שמו\"א יח, כג."],["3890","204","<b>וקרא עצמו. . עני ואביון</b>: תהלים פו, א. קט, כב."],["3891","205","<b>שהמל' עומדת. . דת\"י</b>: ראה פרדס (שער סדר עמידתן) ש\"ו, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670079\" data-slug=\"torat-chaim\" data-id=\"2300670079\">תו\"ח לך פ, ד</a> הערה 46."],["3892","206","<b>אתרוג שדר באילנו</b>: סוכה לה, א. ראה מאמרי אדה\"א דברים ח\"ד ס\"ע א'שיא ואילך. וש\"נ."],["3893","*207","<b>בק\"ש בכל יום. . אור דשבת</b>: ראה גם לקמן פ' ויקהל תטו, ג. תלו, ד."],["3894","207","<b>וכר\"מ דמצלי בכל מיני ניגון</b>: ראה זהר (רע\"מ) משפטים קיד, סע\"ב. השמטות לזח\"א רסו, ב. מאמרי אדה\"א קונטרסים ע' סו. וש\"נ. שע\"ת פח, ד ובהערה 13. לקמן של, ב."],["3895","*208","<b>של השיר</b>: בגוכי\"ק ליתא תיבת של. וקודם תיבת השיר נרשם סימן. ועה\"ג נרשם רק אות ש."]]],[2300550545,"יראה<sup data-n=\"3896\">208</sup> כו', ומ\"ש עבדו את הוי' בשמחה שהוא האהבה דרצוא שרש למ\"ע<sup data-n=\"3897\">209</sup> זהו באהבה ויראה דתורה שהן קודם כו' וכמ\"ש והיו הדברים האלה<sup data-n=\"3898\">210</sup> כו' מצוך היו\"ם שיו\"ם זה כלול מערב ובוקר כמו לע\"ל ממש דלילה כיום יאיר לכך מצות ת\"ת תמידית<sup data-n=\"3899\">211</sup> יום ולילה בשכבך כמו ובקומך (כמו בלא ל\"ב ול\"ב שניהם שוין כמו שאין ויש שוין כך קטנות וגדלות שוין כמו שיהי' לע\"ל (כמשי\"ת).\n<b>ונמצא</b> מובן מכל זה שיש ב' מדרגות א' כמו שעכשיו בנבראים מאין ליש וביטול היש לאין ברו\"ש שאינם כא' והב' כמו שיהי' לע\"ל כנ\"ל דלילה כיום יאיר בשוה (והוא בבחי' י\"ש מי\"ש ממש בלי ביטול כלל כמו דו\"ד מ\"י שהי' יש והי' אין ממש (וכמשיח שא' וגבה מאד<sup data-n=\"3900\">212</sup> יהי' בחי' אי\"ן ממש דכל המשפיל עצמו ה' מגביהו<sup data-n=\"3901\">213</sup> והוא לפי ששרשו בעצמו' הכת\"ר שכלול שם אין ויש, כמו התענוג שבריח החוטם דנשמה באף בב' נקבים בעלי' וירידה כא' ממש וכמ\"ש והריח\"ו ביראת ה'<sup data-n=\"3902\">214</sup> דמורח ודאין, וכמו שהנשמ\"ה תהלל<sup data-n=\"3903\">215</sup> כו', וכרשב\"י שאמר בי' אחידא בי' להיטא<sup data-n=\"3904\">216</sup> כו', וכתפלה דשבת שאין עונ\"ג המורגש בבחי' י\"ש כלל, משא\"כ עונג דתפלת חול, וכדפיקו דלבא במרירות ושמחה כו'. והוא לפי שגם עכשיו יש בחי' יחוד דהוי' ואלקי' דד\"ע וד\"ת הנ\"ל כמו שיהי' לע\"ל ממש וכמ\"ש וידעת היום כיו\"ם דלע\"ל שכולו טוב וכן יום דתורה כמ\"ש אשר אנכי מצוך היו\"ם כו' מטעם הנ\"ל דבחי' ערב ובוקר דתורה כלולים כא' ממש כמו שהיתה שעשועי' עצמי' כו'. וראי' לזה ממה שמ\"ע ול\"ת דאנכי ולא<sup data-n=\"3905\">217</sup> כו' כלולים כא' ממש בתורה וכמ\"ש מימינו א\"ש דת<sup data-n=\"3906\">218</sup> כו' וכן זכור ושמור בשבת כלולי' כא' בדיבור א'<sup data-n=\"3907\">219</sup> וכנ\"ל בהתכללו' דב' שבתות כהלכתן כו' (וכן תורה ותפלה גם עכשיו דויו נחלק מה\"א כו' ויש יראה בלא חכ' וחכ' בלא יראה כו' משא\"כ בזמן הבית<sup data-n=\"3908\">220</sup> כידוע, מ\"מ גם עכשיו יש יחו\"ע דד\"ת ומל' שהוא הוי' ואלקי' כמו שיהי' לע\"ל כנ\"ל וד\"ל (וראי' ממה שא' בבכי יבואו<sup data-n=\"3909\">221</sup> בבכי' של שמחה ושמחה בבכי' כיוצא משבי' ורואה אביו וכה\"ג) (וכמשי\"ת).\n<b>והנה</b> להבין בתוס' ביאור ענין הנ\"ל בבחי' התפעלות ותולדות השמחה והענוה שהוא שפלות והגבהה כא' בבחי' רו\"ש שעולה ויורד כא' ממש מהיכן יוכל להיות ב' הפכים כא' ממש. הנה אנו מוצאים כדוגמתו גם עכשיו כמו השמחה ביסורים, שגם",[["3896","208","<b>דאם אין יראה</b>: אבות פ\"ג, מי\"ז."],["3897","209","<b>האהבה. . שרש למ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא</a> פ\"ד ובמ\"מ הגהות והע\"ק לשם. של\"ה נא, ב. מאמרי אדה\"א קונטרסים ע' פז. וש\"נ."],["3898","210","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["3899","211","<b>מצות ת\"ת תמידית</b>: ראה מנחות צט, סע\"ב. לעיל פ' וארא פא, א. וש\"נ."],["3900","212","<b>וגבה מאד</b>: ישעי' נב, יג."],["3901","213","<b>דכל המשפיל עצמו ה' מגביהו</b>: ערובין יג, ב."],["3902","214","<b>והריח\"ו ביראת ה'</b>: ישעי' יא, ג. סנהדרין צג, ב. ראה הנסמן לעיל פ' בשלח קנח, ג הערה 428."],["3903","215","<b>שהנשמ\"ה תהלל</b>: תהלים קנ, ו."],["3904","216","<b>בי' אחידא בי' להיטא</b>: נסמן לעיל פ' משפטים רפט, ב."],["3905","217","<b>שמ\"ע ול\"ת דאנכי ולא</b>: נסמן לעיל פ' יתרו רנב, א."],["3906","218","<b>מימינו א\"ש דת</b>: ברכה לג, ב."],["3907","219","<b>זכור ושמור. . בדיבור א'</b>: ר\"ה כז, א. מכילתא יתרו כ, ח."],["3908","220","<b>יראה בלא חכ'. . משא\"כ בזמן הבית</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670315\" data-slug=\"torat-chaim\" data-id=\"2300670315\">תו\"ח נח נ, ד</a> ובהערה 57."],["3909","221","<b>בבכי יבואו</b>: ירמי' לא, ח."]]],[2300550558,"שיסורי' הן היפוך השמחה, כי יסורים בגוף בחי' צמצום וקטנות ותכלית הדין הקשה וכן יסורים בבני ומזוני וכל הביטושים הן מחמת קטרוגי' קשים למעלה ולמטה וע\"כ הרי הוא בשפלות מאד כעני ואביון המדוכא כו'. ועכ\"ז הוא יכול לקבל באהבה ושמח ביסורים הללו כראב\"ש שאמר חביבי' יסורים<sup data-n=\"3910\">222</sup> כו' וכה\"ג, וא\"כ אין השמחה הזאת ענין הגבהת הלב והמוח בבחי' הגדלות כלל דאיך יוכל לשמוח ולהתענג ברוחב הלב מאחר שמדוכא ושפל ביותר. וצריך לומר בזה ב' טעמי' שהן א', דהיינו ששמחה זאת אינה באה רק <span data-k=\"pg\">תעד</span> ּ מתוך שפלות זו עצמה דוקא ולא מתוך איזה דבר מעלה וחשיבות בעצמו או דבר טוב לנפשו כלל, אדרבה מצד שנחשב בעיניו כמותר ממש בעולם ואינו ראוי לשום דבר טוב ומעלה כלל, כי נפשו כעפר ממש וכמו אברהם שקרא עצמו עפר ואפר<sup data-n=\"3911\">223</sup> ממש, ע\"כ גם כל היסורים שבאים מהעדר הטוב מקבל באהבה ושמחה כי אין צריך לכלום ושוין אצלו רע וטוב עד שיכול לברך על הרעה כמו על הטוב<sup data-n=\"3912\">224</sup> ממש כאיוב שא' את הטוב נקבל<sup data-n=\"3913\">225</sup> והרע לא נקבל ובירך גם על הרעה כמו על הטובה. והיינו ענין השמחים ביסורים שמקבלי' גם הרע כטוב, דודאי אין שמחה זו רק מצד השפלות העצומה ולזאת אין שמחה כמו מי שא\"צ לצפות לשום דבר טוב לנפשו שבהעדרו לא יעצב כלל וע\"כ יקבל גם יסורים באהבה ורצון כו', וא\"כ אין השמחה ושפלות זו ב' הפכים כלל אלא הכל א' ממש. משא\"כ בשמחה שמורכבת בדבר מה כדבר הטוב בעצם שמטיב לנפש בגדולה ועושר וכה\"ג בשמחה בהתבוננו' בטוב טעם ודעת כו' שיגביה הלב והמוח זהו שמנגד לשפלות וענוה כנ\"ל, וזהו באי\"ן וי\"ש שהן ב' הפכים וכחשך ואור וכה\"ג. אבל בשמחה שמצד הענוה ושפלות מתכללי' כא' ממש (וכמו בדוד שהי' י\"ש בשמחה במורגש כמפזז ומכרכר אבל הי' זה רק מתוך שפלות והי' יכול להיות בהתנשאות דוקא מתוך שמחה זו מאחר שהוא מצד תכלית השפלות. וכמו בשמחת בית השואבה שא' הלל הזקן אם אני כאן הכל כאן<sup data-n=\"3914\">226</sup> ואם אין אני כאן מי כאן אע\"פ שהי' חסיד ועניו גדול כו', משום דאדרבה היא הנותנת דלפי שהי' עניו גדול לא הי' בנפשו בחי' יש ודבר מה במציאות כלל לכך הי' שמחה זו רק מצד עוצם השפלות וענוה יתירה שהוא דוקא יכול לומר אם אני כאן הכל כאן כו', דאני זה אינו בחי' יש כלל אלא אדרבה הוא בחי' אי\"ן וביטול דהכל הולכי' ונכללי' באי\"ן שמיש נעשה אי\"ן, וכמ\"ה דחכ' דמשה שהי' עניו מכל האדם<sup data-n=\"3915\">227</sup> הי' הכל בו. ואם אין אנ\"י כאן שאין בחי' ביטול וענוה מי כאן דאפי' אור צח אוכם<sup data-n=\"3916\">228</sup>",[["3910","222","<b>כראב\"ש שאמר חביבי' יסורים</b>: ראה ב\"מ פד, ב אחיי ורעיי בואו. בתו\"ח כאן כתוב: חביבין עלי יסורים. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תקז: כר\"א שאמר חביבין יסורים. שם ע' תרלג: כמ\"ש ר\"א חביבין עליך יסורים. ח\"ג ע' תתפה, לעיל פ' בשלח רטו, א."],["3911","223","<b>אברהם שקרא עצמו עפר ואפר</b>: וירא יח, כז."],["3912","224","<b>לברך על הרעה. . הטוב</b>: ראה ברכות נד, א (במשנה)."],["3913","225","<b>את הטוב נקבל</b>: איוב ב, י [בדילוג. ושם: ואת הרע]."],["3914","226","<b>אם אני כאן הכל כאן</b>: סוכה נג, א (כגי' הע\"י). ראה גם שע\"ת כה, ג ובהערה 29."],["3915","227","<b>דמשה שהי' עניו מכל האדם</b>: בהעלותך יב, ג. ראה גם לעיל פ' שמות מד, ב."],["3916","228","<b>אור צח אוכם</b>: ראה ת\"ז ת\"ע (קלה, ב). לעיל פ' שמות יב, ב הערה 548."]]],[2300550571,"כו' ולמחת\"ב כלל והיינו בחי' המל' שכל הנחלים הולכים אל הים<sup data-n=\"3917\">229</sup> כו'. וכך הי' בדוד שהי' בתכלית הביטול ומזה דוקא הי' השמח\"ה וההתנשאו' האלקי' בבחי' אי\"ן ממש, כמו רשב\"י שיכול לומר אנא סימנא בעלמא<sup data-n=\"3918\">230</sup> בהתנשאות כו' וכה\"ג).\n<b>וכמו</b> כן ענין הטעם הב' והוא כמו שמצינו ביעקב כשהי' צר לו מעשו וירא מאד שלא יכנו אם על בנים א' אלקי אבי אברהם כו' קטנתי מכל החסדי'<sup data-n=\"3919\">231</sup> ומכל האמת כו' במקלי עברתי את הירדן הזה כו'. דהיינו מה שהשפיל א\"ע בתכלית לומר שכל החסד והטוב שנתן לו ה' אינו שלו כלל ואינו ראוי כלל לכל זה. וז\"ש קטנת\"י מכל החסדי' שקטן מאד ערכו וזכותו לקבל כל החסדים והאמת (דאוי\"ר דאברהם ויצחק שכלולים בו) ונעשה מי\"ש אי\"ן ממש כאלו עני ואביון הוא מצד עצמו גם עכשיו ברוב החסד והשפע כמ\"ש במקלי כו' ועתה הייתי לב' מחנות, ואין זה מכחי ועוצם ידי כי מידך נתת לי ואין לצער עצמו כלל בהעדרם ממנו וצריך לקבל באהבה ושמחה מצד השפלות בעצם דלית לי' מגרמי' כלום (וכמ\"ש דוד מידך נתנו לך<sup data-n=\"3920\">232</sup> ע\"כ התנדבו בשמחה). וכך צריך כל אדם שלא ישמח ברוב <span data-k=\"pg\">950</span> ּ עשרו בגשמיות וגם ברוחניות מחמת הישות וגסות שנדמה לו ששלו הן ורחב לבבו ויתנשא בשמחה וטוב לב כי יפול העולה כו', אלא צריך שישפיל א\"ע בתכלית לומר קטנתי מכל כו', ואין זה שלו כלל כאלו עני ואביון הוא מצד עצמו ויהי' בלב נשבר ובשפלות אמיתי' רק על ה' ישלך יהבו כי הוא הנותן כח כו' ואז יהי' בשמחה מתוך שפלו' כמו העני ממש. וכן להיפוך בצר לו בעניו' ודחקו' לא יתרעם ויעצב ביותר אלא יהי' שמח ביסורי' ועוני מתוך שפלות כנ\"ל. ונמצא שזהו רק מצד ביטול הי\"ש לאי\"ן ע\"כ יסורי' ושמחה שוין ויכול לשמוח ביסורי' ולהיות שפל ונשבר גם בהצלחתו בעושר וכבוד כו', שזהו היפוך ההשתל' מאין ליש דא\"א להיות בחי' אי\"ן וי\"ש שהוא בשפלות ושמחה כא' כנ\"ל וד\"ל (וזהו שבמקום גדולתו שם אתה כו' כמ\"ש לך ה' הגדולה והגבו'<sup data-n=\"3921\">233</sup> ב' הפכי' כא' כו' דלא כמדת ב\"ו שהגדולה היא בבחי' יש ודבר במורכב כמו התנשאות מצד העושר והמעלה שנחשב בעצמו בבחי' יש מורגש ומתפעל מהתנשאות זו בישות וגסות גדולה בעצם, אבל למעלה הרי גם בחי' התנשאות אלקי' הוא בבחי' אי\"ן האלקי בלתי מורכב בדבר מה בהגבלה דכולא קמי' כל\"א כו' (וגם בבחי' ד\"ע מיש האמיתי לאי\"ן היינו שגם בחי' יש האמיתי בבחי' אין האמיתי כו', ולכך יכול להיות מי\"ש אין גם למטה בצדיקים והוא כמו התנשאות דמל' דוד שהוא בבחי' אי\"ן ממש וכהלל שא' אם אני כאן כו'",[["3917","229","<b>שכל הנחלים הולכים אל הים</b>: קהלת א, ז."],["3918","230","<b>רשב\"י. . אנא סימנא בעלמא</b>: זהר ויחי רכה, א. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקלח. וש\"נ. שערי אורה עג, א ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670480\" data-slug=\"torat-chaim\" data-id=\"2300670480\">תו\"ח בראשית טז, א</a>."],["3919","231","<b>אלקי אבי אברהם. . קטנתי מכל החסדי'</b>: וישלח לב, י. יא."],["3920","232","<b>מידך נתנו לך</b>: דהי\"א כט, יד [ושם: ומידך]."],["3921","233","<b>לך ה' הגדולה והגבו'</b>: דהי\"א כט, יא."]]],[2300550582,"וכמ\"ה דמשה (וכן רשב\"י וכה\"ג כנ\"ל), לפי ששרש נשמות הצדיקי' בבחי' אין האמיתי כיעקב שהי' איש חלק חלק ה'<sup data-n=\"3922\">234</sup> ממש כמו שהוא קודם הצמצום דחשך סתרו<sup data-n=\"3923\">235</sup> כו' לכך א' קטנתי מכל החסדים העליונים כו' שזהו יכול לעשות ביטול די\"ש לאי\"ן מחוש\"ך לאו\"ר כבע\"ת כו'. ולכך גדולים מעשה צדיקים<sup data-n=\"3924\">236</sup> ממעשה שמים וארץ דמע\"ב נבראו מאין ליש וצדיקי' יכולים לעשות ביטול היש לאי\"ן שמזה מורה בשרשם למעלה מאי\"ן וי\"ש שהוא כמו למעלה דבמקום גדולתו כו' דגדולה וענוה כא'<sup data-n=\"3925\">*237</sup> ממ\"ש כנ\"ל.\n<b>(וזהו</b> ויספו ענוי\"ם בהוי' שמחה<sup data-n=\"3926\">237</sup> דצדיקים נק' ענוים<sup data-n=\"3927\">238</sup> מצד עוצם הביטול במציאות בהעדר ההרגשה בעצמם כלל, ע\"כ מוסיפים שמחה בהוי' למעלה שזהו שמחה שבבחי' אי\"ן האמיתי דלמת\"ב כלל כנ\"ל ביעקב, אבל אביוני אדם שהן בע\"ת<sup data-n=\"3928\">239</sup> שעושים מיש דחוש\"ך אי\"ן כמו לב נשבר ונדכא וכעני ואביון שא' את מי אשכו\"ן<sup data-n=\"3929\">240</sup> כו', בקדוש ישראל עצמו יגילו למעלה משמחה דצ\"ג שאין צ\"ג יכולים לעמוד שם כלל, כידוע דגם שצ\"ג יכולים לעשות מי\"ש אי\"ן זהו ע\"י שמחה בעבודתם שמורכב בדבר מה רק שהוא בבחי' אין וביטול דמ\"ה דחכ' דתו\"מ כו'. משא\"כ בע\"ת שנק' אביונ\"י אדם בלא שמחה דתו\"מ כלל, שאין השמחה הזאת רק מתוך השפלות האמיתי רק במה שיצא מאפילה לאור גדול כמו ממות לחיים, כיוצא מן הסכנה בשבי' ובית האסורים שנק' שמחה שבאה מן הבכי' שבוכה מגודל השמחה שהיתה לו לנפשו לשלל שניצול מן המות ואבדון, זהו שמחה עצמי' הרבה יותר <span data-k=\"pg\">תעה</span> ּ מכל בחי' שמורכבת בדבר מה אף בתענוג וחכמה ורצון נפלא כו', להיותה פשוטה לגמרי בלתי מורכבת כלל רק בעצם הנפש ממש שנק' שמחת הנפש מתוך ההיפוך דוקא שניצולה שזהו מתוך השפלות בתכלית כשירת הים וכה\"ג. ולכך א' לע\"ל שם נשמחה בו<sup data-n=\"3930\">241</sup> ממש במהו\"ע ית' דלמת\"ב כלל שנק' קדוש ישראל כי עיקר הגאולה יהי' ע\"י התשובה דוקא כידוע כמ\"ש אם יגאלך טו\"ב<sup data-n=\"3931\">242</sup> זו תו\"מ וא\"ל כו', וזהו משיח שיעשה מצ\"ג בע\"ת<sup data-n=\"3932\">243</sup> שיהפכו מיש עצמו לאין שלא ע\"י בחי' אין דחכ' דתורה וד\"ל.\n<b>וזהו</b> שלע\"ל א' בבכי יבואו כו' ואע\"פ שא' שם נשמחה בו שזהו בקיבוץ גליות כשיעברו בנהר פרת<sup data-n=\"3933\">244</sup> כו', אך בחי' שמחה זו תהי' מתוך בכי' והבכי' מתוך השמחה דהיינו שמחה ובכי' כא', והוא ממה שיצאו מחשך לאור פתאום כמ\"ש העם ההולכים בחוש\"ך ראו אור גדול ששמחה זו מן ההיפוך ע\"י בכי' שבוכה",[["3922","234","<b>כיעקב שהי' איש חלק חלק ה'</b>: תולדות כז, יא. האזינו לב, ט. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680078\" data-slug=\"torat-chaim\" data-id=\"2300680078\">תו\"ח וישלח קפא, ב</a> ובהערה 32. לעיל פ' שמות מא, ב."],["3923","235","<b>הצמצום דחשך סתרו</b>: ראה גם לעיל פ' בא קכג, ג הערה 445."],["3924","236","<b>גדולים מעשה צדיקים</b>: ראה כתובות ה, א. מאמרי אדה\"א ויקרא ח\"ב ע' תתי. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670399\" data-slug=\"torat-chaim\" data-id=\"2300670399\">תו\"ח בראשית כה, ג</a> הערה 29."],["3925","*237","<b>כא'</b>: תיבה זו אינה ברורה בגוכתי\"ק."],["3926","237","<b>ויספו ענוי\"ם בהוי' שמחה</b>: ישעי' כט, יט. ראה גם לעיל פ' בשלח קעח, א. וש\"נ."],["3927","238","<b>דצדיקים נק' ענוים</b>: ראה גם לעיל שם. וש\"נ."],["3928","239","<b>אביוני אדם שהן בע\"ת</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."],["3929","240","<b>את מי אשכו\"ן</b>: ראה ישעי' נז, טו. לעיל פ' וארא פג, ב הערה 727."],["3930","241","<b>שם נשמחה בו</b>: תהלים סו, ו."],["3931","242","<b>אם יגאלך טו\"ב</b>: רות ג, יג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקעב. קונטרסים ע' ריח ובהנסמן בהנ\"ל."],["3932","243","<b>משיח שיעשה מצ\"ג בע\"ת</b>: ראה זהר (רע\"מ) בהעלותך קנג, ב. לעיל פ' שמות מא, ב. וש\"נ."],["3933","244","<b>כשיעברו בנהר פרת</b>: ראה ישעי' יא, טו ובמפרשים שם. לעיל פ' שמות מ, ד. וש\"נ."]]],[2300550593,"מגודל השמחה כמו התינוק שנולד שיבכה<sup data-n=\"3934\">245</sup> מיד בהולדו מתוך שיצא מן המיצר כזה ונפתחו עיניו<sup data-n=\"3935\">246</sup> כו' (כמשי\"ת). וא\"כ יובן שיוכל להיות שמחה ושפלות כא' ממש שהשמחה אינה רק מתוך השפלות היפך השמחה שבהגבהה כו' (וכך הוא השמחי' ביסורים כו' שמקבלים הרע לטוב כשימצאו ברע טוב ויברכו עליו בשמחה וטוב לב כנ\"ל, שלא נודע בין טוב לרע כי גם בטוב יש רע בהעלם וברע יש טוב כו' והגילוי מן ההעלם בטוב הגנוז שברע זהו השמחה ביציאה מן החשך דרע לטוב כמו שיצאו מנש\"ט<sup data-n=\"3936\">247</sup> דמצרים כגר שנתגייר וכמברך שלא עשני גוי<sup data-n=\"3937\">248</sup> כו' וכבע\"ת שנהפך מרע לטוב כו' (ויש גם עכשיו כדוגמא דלע\"ל שבבכי דוקא יבואו כו' כמו בכל תיקון חצות שבכה יבכה במר נפשו על ח\"נ כו' וכמו מטתי בדמעתי כו', ומיד יקום לעסוק ברינה של תורה בשמחה וכמו שאו' חצות לילה אקום להודות לך על משפטי צדקיך כו' שממתיק לגבורות דק\"נ שנאחזי' בנשמה בב' דברים בבכי' ושמחה יחד, לפי ששמחה זו מתוך השפלות דתשוב' מעין דלע\"ל כו' שבזה נהפך חשך לאור. וזהו שלע\"ל לילה כיום יאיר והוא בכל חצות לילה גם עכשיו שכלול מחו\"ג כא' וכמ\"ש כנור הי' תלוי למעלה ממטתו כו' והי' מנגן מאליו ואע\"פ שהי' בוכה ברגע זו עצמה לפי שרגע זו כלול מחו\"ג (כמו שהי' במצרים בחצות לילה שנגלה עליהם כו', (כמ\"ש במ\"א ע\"פ ויהי<sup data-n=\"3938\">249</sup> כו') (וזהו ההפרש בין צדיקי' גמורים לבע\"ת כו', אך דוד הי' צ\"ג ובע\"ת<sup data-n=\"3939\">250</sup> יחד כמו לע\"ל שצדיקים יהיו בע\"ת וכיעקב שלבש בגדי עשו ונעשה בע\"ת<sup data-n=\"3940\">251</sup> לעלות מי\"ש לאי\"ן (וזהו שצריך לברך על מ\"י שחלק מכבוד\"ו ליריאי\"ו<sup data-n=\"3941\">252</sup> דוקא בבחי' התנשאות אלקי' שבבחי' אין כמשיח שהי' י\"ש ובטל במציאות ביראה עילאה כמ\"ש והריחו ביראת ה' כו' אבל בעוה\"ב גדול במעלה גם מזה שא' להנחיל אוהבי יש<sup data-n=\"3942\">253</sup> מיש ליש בלא ביטול במציאות כלל כמ\"ש ונח\"י' לפני\"ו<sup data-n=\"3943\">254</sup> ממש בלתי אמצעי כלל (כמשי\"ת) וד\"ל.\n<b>והנה</b> מעתה יש להבין בשרש ענין הגדולה וענוה שיהי' כא' למעלה מצד שלמעלה יתכללו ב' הפכי' דבחי' ד\"ע וד\"ת הנ\"ל והוא מ\"ש וידעת היום כו' כי ה' <span data-k=\"pg\">952</span> ּ הוא האלקים ממש",[["3934","245","<b>השמחה כמו התינוק שנולד שיבכה</b>: ראה לעיל פ' וארא סו, סע\"ג ואילך."],["3935","246","<b>ונפתחו עיניו</b>: ראה לעיל פ' וארא סו, ד הערה 337."],["3936","247","<b>מנש\"ט</b>: ראה גם לעיל פ' יתרו רנא, ד. וש\"נ."],["3937","248","<b>שלא עשני גוי</b>: ברכות השחר. ראה גם לעיל פ' וארא עד, סע\"ב ואילך."],["3938","249","<b>ע\"פ ויהי</b>: ראה גם לעיל פ' בא פז, ב. פח, ב."],["3939","250","<b>דוד. . ובע\"ת</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תסג. וש\"נ. שמות ר\"ע תקיג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680401\" data-slug=\"torat-chaim\" data-id=\"2300680401\">תו\"ח וישלח קצה, ג</a>."],["3940","251","<b>וכיעקב. . בע\"ת</b>: ראה מאמרי אדה\"א בראשית ע' תצה. וש\"נ. שמות ח\"ב ע' תקיא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680470\" data-slug=\"torat-chaim\" data-id=\"2300680470\">תו\"ח תולדות קסג, ב</a> ובהערה 7. לקמן שדמ, ב. פ' ויקהל תו, א."],["3941","252","<b>שחלק מכבוד\"ו ליריאי\"ו</b>: ברכות נח, א."],["3942","253","<b>להנחיל אוהבי יש</b>: משלי ח, כא. ראה גם הנסמן לעיל פ' בשלח קנט, ב הערה 466."],["3943","254","<b>ונח\"י' לפני\"ו</b>: הושע ו, ב."]]],[2300550604,"וכמ\"ש יעקב והי' הוי' לי לאלקים<sup data-n=\"3944\">255</sup> וכן או' ה' אלקינו<sup data-n=\"3945\">256</sup> כו' וזהו כמו שיהי' לע\"ל שלילה כיום יאיר כו' כנ\"ל. דהנה לע\"ל א' ובאו במערות צורים<sup data-n=\"3946\">257</sup> מפני פחד ה' והדר גאונו כו', והיינו לפי שיהי' התגלות דשם הוי' בבחי' סוכ\"ע הכללי להיות בבחי' ממלא ממש כמ\"ש ונגלה כבוד ה'<sup data-n=\"3947\">258</sup> וראו כ\"ב כו' דגם כל בשר הגשמי כעין הגשמי דאדם יראה אור האלקי (ואף בהמות וחיות<sup data-n=\"3948\">259</sup> כמו שאו' וידע כ\"פ כי אתה פעלתו<sup data-n=\"3949\">260</sup> ויבין כל יצור כו' וכמו שהי' קודם חטא אדה\"ר וחמורו של רפב\"י<sup data-n=\"3950\">261</sup> יוכיחו<sup data-n=\"3951\">262</sup> וכמו פרות גשמיו' שנשאו הארון<sup data-n=\"3952\">263</sup> האלקי' בביטול המציאות כו'). וזהו פלא גדול לכאורה דאיך יוכל עיני בשר לראות בראי' המהות באור הוי' שנק' סוכ\"ע עכשיו שלמעלה מממכ\"ע דאפי' מלאכים עליונים דבריאה כשרפי'<sup data-n=\"3953\">264</sup> וחיות<sup data-n=\"3954\">265</sup> או' קדוש<sup data-n=\"3955\">266</sup> הוי'<sup data-n=\"3956\">267</sup> ואפי' בכח האלקי דממלא בשם אלקי' נבדל ומרומם מהם רק בבחי' הארה דהארה לבד כידוע.\n<b>אך</b> צריך להקדים תחלה ענין הידוע בבחי' שם אלקי' דממכ\"ע דגם הוא אינו רק בבחי' אור וזיו לבד (וכתרגום כבוד\"ו זיו יקרי'<sup data-n=\"3957\">268</sup> וכמו הודו על ארץ<sup data-n=\"3958\">269</sup> כו' והוא בחי' שם כבוד מלכותו ית' כידוע), וע\"כ אין שינוי כלל בין קודם שנברא העולם לאחר שנבה\"ע ממש וכמו שאו' אתה הוא כו'. אבל אי אפשר לומר שהמשכת העולמות מאלקות בא בבחי' שפע כשאר שפע והמשכה דעו\"ע שנמשך ממהות המשפיע למקבל כשכל דרב דמשפיע למקבל וכצדקה דעשיר לעני מיד ליד וכה\"ג כמים שנשפע' מכלי אל כלי כו', דא\"כ הרי הי' שינוי בעצמו' אלקות בין קודם שנבה\"ע כו' (וגם הי' לנברא ערך ויחוס לבורא ואין ערוך כלל לבע\"ג לגבי בל\"ג<sup data-n=\"3959\">270</sup>, וגם איך ימצא ב\"ג מבלתי בע\"ג כו'). ולפ\"ז צ\"ל דגם בלשון כח וחיות א\"א לומר בזה כמו שנז' בספרים, וכמובן מפשט הכתובים במע\"ב שבכח האלקי ממש נבראו הברואים מאחר שנק' בבחי' עשי' ופעולה כמו ביום עשות ה'<sup data-n=\"3960\">271</sup> כו' וכן אשר ברא אלקי' לעשות<sup data-n=\"3961\">272</sup> וכה\"ג וכמ\"ש כולם בחכ' עשית<sup data-n=\"3962\">273</sup> שזהו שנק' כח הפועל בנפעל<sup data-n=\"3963\">274</sup> שמהות כחו של הפועל ועושה נמשך בפעולה זו כמו אף ידי יסדה ארץ<sup data-n=\"3964\">275</sup> כו', שזהו כמו כח יד הפועל כשפועל דבר מה שמכחו הנמשך מידו נעשה עצם",[["3944","255","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא. ראה לקמן שכט, א. שלא, ב."],["3945","256","<b>ה' אלקינו</b>: בא י, כו. ועוד."],["3946","257","<b>ובאו במערות צורים</b>: ישעי' ב, יט [בדילוג. ושם: ומהדר — ראה לעיל פ' בשלח קנד, ד]."],["3947","258","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["3948","259","<b>וראו כ\"ב. . בהמות וחיות</b>: ראה גם לעיל פ' וארא עד, א הערה 100."],["3949","260","<b>וידע כ\"פ כי אתה פעלתו</b>: תפלת העמידה לר\"ה."],["3950","261","<b>וחמורו של רפב\"י יוכיחו</b>: ראה חולין ז, סע\"א ואילך. לעיל פ' בשלח קצה, ד הערה 595."],["3951","262","<b>יוכיחו</b>: בגוכתי\"ק: יוכיח ומקום פנוי ואח\"כ ו. וכנראה שמתחלה רצה לכתוב בשורה זו גם תיבת וכמו. ואח\"כ החליט לכותבה בשורה שלאח\"ז."],["3952","263","<b>פרות גשמיו' שנשאו הארון</b>: ראה שמו\"א ו, יב. מאמרי אדה\"א דברים ח\"ג ע' תתלד. וש\"נ."],["3953","264","<b>מלאכים עליונים דבריאה כשרפי'</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["3954","265","<b>מלאכים. . דבריאה. . וחיות</b>: פע\"ח (שער הק\"ש) ש\"ח, פ\"א. לקמן פ' ויקהל תג, רע\"ג."],["3955","266","<b>כשרפי'. . או' קדוש</b>: ישעי' ו, ב. ג. תוד\"ה ברוך חולין צב, רע\"א."],["3956","267","<b>וחיות או' קדוש הוי'</b>: ראה גם להלן (במאמר זה) שכח, ג."],["3957","268","<b>וכתרגום כבוד\"ו זיו יקרי'</b>: תרגום יונתן לישעי' ו, ג. תרגום לתהלים עב, יט."],["3958","269","<b>הודו על ארץ</b>: תהלים קמח, יג. ראה גם לעיל פ' וארא עה, א. וש\"נ."],["3959","270","<b>ואין ערוך. . בל\"ג</b>: ראה גם לעיל פ' בשלח קעא, ב. וש\"נ."],["3960","271","<b>ביום עשות ה'</b>: בראשית ב, ד."],["3961","272","<b>אשר ברא אלקי' לעשות</b>: שם ב, ג."],["3962","273","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3963","274","<b>כח הפועל בנפעל</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">לקו\"ת שלח מז, א</a>: בספרים וראה בהנסמן במ\"מ לשם. ספר הישר (לר\"ת ) סוף שער ג."],["3964","275","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."]]],[2300550613,"הדבר כו' שזהו בא ממהות החיות וכח שביד שנמשך בנפעל ונתפס בו ממש. ויש כאן ערך והשתוות בנפעל לעצם הפועל, וגם יש שינוי בכח הפועל ממה שנחלק ונחסר קצת כח זה שנמשך בפעולה זו לחוץ<sup data-n=\"3965\">276</sup> להיות שכח הכללי מוגבל בחלקי' (עד שאין בכחו רק להגביה משא כפי ערך כחו ולא יותר). ולא כאור הדולק שמדליקי' ממנו כמה נרות ולא נחסר בו כלום כמ\"ש בזהר כהאי בוצינא דאדליק לכל סטר<sup data-n=\"3966\">277</sup> כו', שהרי אנו רואי' כשגמר כל פעולתו הרי חוזר אותו הכח שנתפשט מידו אל עצמו וניתוסף ונשלם בכחו יותר מתחלה שנמשך מכחו בפעולה ומלאכה זו. א\"כ הרי יש שינוי בין קודם פעולתו לשעת פעולתו ואח\"כ כו', וגם יש בחי' יחוס וערך עד שהוא מתפעל בעצמו מפעולה זאת. דגם שכח הפועל בפעולתו מצומצם מאד כמעשה הציור וכתיבה וכה\"ג, מ\"מ גם בתנועה זו מתפעל דכל מניע <span data-k=\"pg\">תעו</span> ּ מתנענע<sup data-n=\"3967\">278</sup> בעצם (כמ\"ש הרמב\"ם במניע לגלגל היומי<sup data-n=\"3968\">279</sup> שאין מניע זה מתנענע דא\"כ גם לו יש פועל המניעו כו'). ועוד שכח הפועל כשידיו מסולקו' נשאר הפעולה במהות בפ\"ע כידוע, וא\"א לומר עד\"ז כלל למעלה באלקי' חיים שאין לברואי' בע\"ג ערך לו כלל שיהי' כמ\"כ כח הפועל האלקי בנבראים, דא\"כ הרי נמצא ממהות ועצמו' כח אלקי חלק א' מאלף אלפים כו' במהות הבריאה שבזה הן חיים וקיימים, וא\"כ הרי כללות העולמות הן נק' חלק וכח מכח אלקו' ממש שיכול<sup data-n=\"3969\">*280</sup> עי\"ז שינוי והתפעלות בכח הפועל כנ\"ל שיחסר משלימות כחו או יושלם אחר גמר הפעולה כו', שא\"א לומר כזה כלל למעלה שאין באלקו' שום שינוי כלל ע\"י המשכה הזאת האלקי' שמהווה העולמות כמו שא' אני הוי' לא שניתי<sup data-n=\"3970\">280</sup> כו'. וגם לא בענין שינוי בהתפעלו' כהתפעלו' המניע בתנועתו ופעולתו כנ\"ל, כי אין זה בא בבחי' המשכת כח ממש מכח עצמו' אלקות שהוא כח בלתי בע\"ג ואינו מתחלק לחלקי' כלל, שנוכל לומר שנמשך חלק א' ממנו שמוגבל בעולמות וכמ\"ש גדול אדונינו ורב כח<sup data-n=\"3971\">281</sup> בבחי' א\"ס ממש שאינו מתחלק כלל. ואם הי' מתחלק חלק א' כמו ניצוץ מן השלהבת הי' גם הוא בבחי' א\"ס ממש, ואנו רואים שכח זה המצומצם בכל השתל' העולמות הוא בבחי' גבול ומדה ואיך ימצא בחי' הגבול מבלתי בע\"ג כו' וד\"ל (וכמו שא\"א לומר שימצא בחי' מספר מלמעלה מן המספר דא\"א לומר דאלף ורבבה חלק ממנו כו').\n<b>אך</b> הנה בהכרח לומר דכל מה שנז' בכתובים ובס' המקובלים בבחי' מל' דאצי' שהוא שם אלקים שבורא הכל בלשון כח",[["3965","276","<b>לחוץ</b>: תיבה זו נכתבה עה\"ג ולא נסמנה מקומה בפנים. ואולי מקומה כאן."],["3966","277","<b>כהאי בוצינא דאדליק לכל סטר</b>: ראה זהר (אד\"ז) האזינו רפח, א. מאמרי אדה\"א שמות ח\"א ע' קסג. וש\"נ. לקמן פ' ויקהל שפט, א."],["3967","278","<b>דכל מניע מתנענע</b>: מו\"נ ח\"ב הקדמה התשיעית."],["3968","279","<b>כמ\"ש הרמב\"ם במניע לגלגל היומי</b>: ראה מו\"נ ח\"ב, פ\"א."],["3969","*280","<b>שיכול</b>: כ\"ה בגוכתי\"ק."],["3970","280","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["3971","281","<b>גדול אדונינו ורב כח</b>: תהלים קמז, ה."]]],[2300550620,"הפועל בנפעל שזהו שם המושאל לבד דדברה תורה כלשון בנ\"א<sup data-n=\"3972\">282</sup>, דודאי א\"א לומר למעלה באלקי' חיים שום כינוי ותואר מתוארי אדם בגוף שיהי' בו שינוי והתפעלות וגבול כמו הכח באדם שיש לו גבול וכיליון ושינוי כו' שאין לו גוף<sup data-n=\"3973\">283</sup> ודמות הגוף כלל (וכמ\"ש לא ייעף ולא ייגע<sup data-n=\"3974\">284</sup> כו'. ומ\"ש בשבת וישבות כי בו שבת<sup data-n=\"3975\">285</sup> לא מצד היגיעה דאין גבול לכח דא\"ס, ולא שייך בו יגיעה ולא שביתה ומנוחה ולא בחי' או\"ח מן הנפעל שיהי' נשלם מחסרון הכח כנ\"ל, כי אין בזה המשכת מהות כח ממש ולא יש בו שינוי כלל, רק מה שא' לעולמו די<sup data-n=\"3976\">286</sup> כו' ע\"י צמצום לפי שכל יכול הוא ויש בו ג\"כ כח המגביל כל גבול ומדה זהו בחי' השביתה דשבת להפסיק ממלאכתו לפי שאמר לעולמו די כו', וגם זה רק באור וזיו הנמשך ממנו שאינו ממהו\"ע שלו כלל וכלל. ועכ\"ז הי' מתפשט בלי גבול כלל (וכמשי\"ת) דמ\"ש ורב כח גם זה אינו כמו כח האדם ממש וכן מ\"ש קול ה' בכח<sup data-n=\"3977\">287</sup> וכה\"ג, ואע\"פ שהוא בבחי' א\"ס כקול אלקים ששמעו בה\"ס עכ\"ז א\"א שיומשך כמו כח הפועל באדם שהנפש בעצמה מוגבלת היא ומחודש מאי\"ן ליש ולזאת גם הכח המתפשט ממנה בחי' גבול ונק' כח ממש שבא בערך כח הנפעל ממנו ויש בו שינוי ומתחלק לחלקי', ואמנם בעצמו' א\"ס אף באצי' אין לומר שם בבחי' כח עצמי מעצמות דא\"ס כלל רק בחי' אור וזיו לבד שהרי גם ע\"ס דאצי' לא נק' רק בחי' אורות כאור המאיר מעצם המאור (וכדמיון שא' בס\"י כמו שלהבת בגחלת<sup data-n=\"3978\">288</sup> וכה\"ג). וגם <span data-k=\"pg\">954</span> ּ זה אינו במציאות אור ממש שהרי א' ע\"ס בלי מה<sup data-n=\"3979\">289</sup> מהות<sup data-n=\"3980\">290</sup> כלל, אלא נקראי' בבחי' שמות ואותיות כמ\"ש בזהר דכל ע\"ס בכלל נק' שמא קדישא<sup data-n=\"3981\">291</sup> שהוא שם הוי' בכלל יו\"ד בשם ע\"ב דחכ'<sup data-n=\"3982\">292</sup> וה\"א בשם ס\"ג בבינה<sup data-n=\"3983\">293</sup> וא\"ו בשם מ\"ה במילוי אלפי\"ן במדות כו' וכה\"ג במל' דאצי' בה\"א אחרונה דשם הוי' שהוא בחי' שם ב\"ן והוא שם אלקי'<sup data-n=\"3984\">294</sup> שמתלבש בעולמות בבחי' ממכ\"ע כידוע (ומה שא' בע\"ס הגנוזו'<sup data-n=\"3985\">295</sup> בעצמות המאציל שזהו ענין גליף גליפו בטה\"ע<sup data-n=\"3986\">296</sup> שהוא מה ששיער בעצמו בכח<sup data-n=\"3987\">297</sup> מה שעתיד להיות בפועל, אין זה ככח האדם בנפשו וברצונו אלא היינו רק בחי' ההעלם דרצון וחכ' ומדות שכלולים בעצמו' המאציל כשלהבת הקשורה בגחלת בהעלם וכמו ויאצל מן הרוח<sup data-n=\"3988\">298</sup> דמשה על ע' הזקנים שתחלה היו כלולים ברוחו של משה כו') ולא ככח ופועל ממש שא\"כ הי' גם האצי' בבחי' עצמו' דא\"ס ואין ערך לאצי'<sup data-n=\"3989\">299</sup> לגבי עצמות המאציל כמו הבריאה לגבי הבורא לפי שנאצל ע\"י צמצום דקו\"ח שזהו ע\"י בחי' אותיות ושמות כנ\"ל) וזהו דגליף",[["3972","282","<b>דדברה תורה כלשון בנ\"א</b>: ברכות לא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["3973","283","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'."],["3974","284","<b>לא ייעף ולא ייגע</b>: ישעי' מ, כח."],["3975","285","<b>וישבות כי בו שבת</b>: בראשית ב, ב. ג."],["3976","286","<b>שא' לעולמו די</b>: חגיגה יב, א."],["3977","287","<b>קול ה' בכח</b>: תהלים כט, ד."],["3978","288","<b>שא' בס\"י כמו שלהבת בגחלת</b>: ראה שם פ\"א, מ\"ז."],["3979","289","<b>ע\"ס בלי מה</b>: ראה ס\"י פ\"א, מ\"ב ובמפרשים שם."],["3980","290","<b>מהות</b>: אוצ\"ל: בלי מהות."],["3981","291","<b>דכל ע\"ס בכלל נק' שמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם."],["3982","292","<b>ע\"ב דחכ'</b>: ראה לעיל פ' וארא פד, ד הערות 805. 809. פה, ג הערה 837."],["3983","293","<b>בשם ס\"ג דבינה</b>: ראה גם לעיל פ' תרומה שיב, ג. וש\"נ."],["3984","294","<b>בשם מ\"ה. . ב\"ן והוא שם אלקי'</b>: נסמן לעיל פ' תרומה שיג, א."],["3985","295","<b>בע\"ס הגנוזו'</b>: נסמן לעיל פ' יתרו רסה, ג הערה 116."],["3986","296","<b>גליף גליפו בטה\"ע</b>: זהר בראשית טו, א."],["3987","297","<b>מה ששיער בעצמו בכח</b>: מובא לעיל פ' בשלח קעח, ג בשם הע\"ח. ראה מק\"מ לזהר שם. ראה גם מאמרי אדה\"א קונטרסים ע' רא. וש\"נ."],["3988","298","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה. ראה גם לעיל פ' שמות יא, ד."],["3989","299","<b>ואין ערך לאצי'</b>: ראה גם לעיל פ' בשלח קע, ב. וש\"נ."]]],[2300550626,"גליפ\"ו בחקיקת אותיות לבד רק שהן בחי' שמות העצמיי' ממל' דא\"ס שנמשך בקו\"ח שנק' שמו הגדול<sup data-n=\"3990\">300</sup> או שמי'<sup data-n=\"3991\">302</sup> רבא<sup data-n=\"3992\">301</sup> ועכ\"ז גם מל' דא\"ס אינו רק בחי' שם בלבד (כמשי\"ת).\n<b>וגם</b> ענין של האור וזיו אינו כאור וזיו השמש המאיר לארץ שיש לו יחוס וגוף וערך עכ\"פ לגוף המאור דשמש עצמו שהרי אור זיו זה מאיר מן המאור והוא מחוייב המציאות שא\"א למאור שלא יאיר אור ממנו, ולמעלה גם דמיון זה א\"א לומר בענין משל אמיתי אע\"פ שנזכר ל' אור וזיו בכתובים בכמה מקומות כמו הוד\"ו על ארץ כו' וכתי' מלא כל הארץ כבודו זיו יקרי' וכמו והארץ האירה מכבודו<sup data-n=\"3993\">303</sup> מאיר לארץ<sup data-n=\"3994\">304</sup> כו', בהיות שזהו משל לענין התהוות יש מיש כזיו ממאור, אבל התהוות העולמות מאלקו' זהו מאין ליש שהוא מאין ממש ומה גם שאור וזיו האלקי גם הוא בבחי' א\"ס בין באצי' בין בבי\"ע בלי הפרש כלל וכלל כו' כמ\"ש אני ראשון ואני אחרון<sup data-n=\"3995\">305</sup> דקאי במל' דא\"ס עד מל' דעשי' דגם שאינו רק בחי' אור וזיו ולא העצמו' מ\"מ גם באור א\"ס אין שינוי כלל כמו בעצמותו (ואע\"פ שהקו\"ח נפסק מאצי' ולמטה<sup data-n=\"3996\">306</sup> זהו רק ע\"י מסך שמבדיל בין אצי' לבריאה ואין שם רק בחי' הארה דהארה כו' וכן מל' דא\"ס בקו\"ח ע\"י צמצום דאלקי' אבל אני ראשון זהו מל' דא\"ס עצמו שכמו שקודם ההשתל' הי' הוא ושמו בלבד שהוא בחי' שמו הגדול כנ\"ל, כך גם אחר ההשתל' דאבי\"ע כו'. אלא צריך לומר דאין זה האור וזיו כמשמעות אור וזיו בגשמיות אלא זהו בחי' אור וזיו בבחי' הרוחניות (כמראה הנבואה בבחי' אספקלריא דנהרא<sup data-n=\"3997\">307</sup> כמו במראה אליו אתוודע<sup data-n=\"3998\">308</sup> כו'), והיינו כמו אור וזיו המאיר מעצמות הנפש להחיות הגוף שנק' אור וחיות שחיות זה אין לו ערך ויחוס כלל לגבי עצם הנפש ממש שהיא בבחי' רוחניות ממש שמושללת לגמרי מגדר וסוג חיות גשמי כחיות הגוף ועכ\"ז ממנה דוקא יחי' הגוף בחיי בשר גשמי (שתתפעל הנפש ממקרי חיות הגוף הגשמי כידוע). והענין הוא דאין אור וחיות זה הגשמי נמשך מעצם ומהות הנפש ממש אלא זהו רק בחי' גילוי <span data-k=\"pg\">תעז</span> ּ ההעלם דעצמותה לבד כמו גילוי המראה והגוון כאדום ולבן בעצם הדבר ובגילוי התנועה בעצם החי (ולא כשבא בהמשכת כח ממש) דזה הגילוי נק' אור הנפש, וגם הוא בא בדרך דילוג הערך כשבא להיות חיות בד\"ם הוא הנפש החיוני שמורכב מד\"י גשמיי' שנק' חיי בשר, דלפי זה אין שינוי כלל וכלל בנפש וגם לא באור העצמי רק במה שמתגלה ממנה בחומר הגוף כמו כח הראיה בעין לראות ובאוזן לשמוע בראי' ושמיעה גשמי' שאינו רק הארה דהארה כו' בשינוי המהות לגמרי כמו אור הנראה מן",[["3990","300","<b>ממל' דא\"ס. . שמו הגדול</b>: ראה גם לעיל פ' שמות ה, ג. וש\"נ."],["3991","302","<b>שמו הגדול או שמי' רבא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380791\" data-slug=\"likkutei-torah\" data-id=\"4001380791\">לקו\"ת ראה יח, ד</a>."],["3992","301","<b>ממל' דא\"ס. . שמי' רבא</b>: ראה גם לעיל פ' בשלח קעח, ד ובהערה 648."],["3993","303","<b>והארץ האירה מכבודו</b>: יחזקאל מג, ב."],["3994","304","<b>מאיר לארץ</b>: ראה ברכת יוצר."],["3995","305","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו. ראה גם שעה\"י קיד, א ובהערה 11."],["3996","306","<b>שהקו\"ח נפסק מאצי' ולמטה</b>: ראה ע\"ח (שער סדר האצי') ש\"ג בתחלתו. תו\"ח ויצא קעו, ג הערה 45."],["3997","307","<b>אספקלריא דנהרא</b>: זהר בראשית כג, סע\"ב. לג, ב."],["3998","308","<b>במראה אליו אתוודע</b>: בהעלותך יב, ו."]]],[2300550632,"המסך כו', שמטעם זה אין הנפש עצמה ולא בגילוי שלה מתפעלת ממקרי הגוף כלל רק מה שמלובש מהארה דהארה זו באברי הגוף תתפעל ממקרי הגוף<sup data-n=\"3999\">309</sup> כו' (וזהו שנק' רוחניות שבגשמי' הגוף שמקבל ע\"י דילוג הערך מגשמיות שברוחניות דנפש עצמה כידוע בענין אדם א' דם<sup data-n=\"4000\">310</sup> כו', וכמו כח הצמיחה המלובשת בצומח דעשב שנמשך מגשמיות דכח הצומח הכללי כו' וד\"ל). ולכאורה כל זה הוא משל ודמיון אמיתי למעלה בהמשכת אלקות להחיות כל העולמות מאין ליש שהוא בא ג\"כ בבחי' אור וחיות כחיות הנפש בגוף כו' וכמו שמקרא מפורש ואתה מחי\"ה את כולם<sup data-n=\"4001\">311</sup> ונק' אלקי\"ם חיים ומלך עולם<sup data-n=\"4002\">312</sup> דהיינו שם אלקים שמתפשט בעולמות להחיותם מאי\"ן ליש ממש ונק' ממכ\"ע כנפש בגוף נק' אלקים חיים בבחי' התפשטות גילוי החיות בבע\"ג שבא בדילוג הערך רק בבחי' הארה דהארה מעצמות מל' דאצי' או מדות דאצי' שנק' חי העולמים בעצם (כמו גילוי העצמות דנפש טרם שמתצמצמת להחיות הגוף כו') או חיי החיים וכה\"ג ע\"י בחי' מסך מפסיק בין אצי' לבי\"ע וכמ\"ש כי עמך מקור חיים<sup data-n=\"4003\">313</sup> דעולמות באורך נראה אור בלבד כו' כמ\"ש במ\"א (וגם באצי' אין בו רק בחי' אור וחיות כנשמה בגוף במל' דאצי' בבי\"ע שהרי א' אי אנת תסתלק מנייהו אשתארו כגופא בלא נשמתא<sup data-n=\"4004\">314</sup> כו', וגם ממאציל לאצי' בא בשינוי המהות דרך בחי' פרסא<sup data-n=\"4005\">315</sup> עד מל' דא\"ס לגבי מהו\"ע א\"ס ב\"ה אינו גם כאור המאיר משמש וכה\"ג אלא הוא רק בחי' גילוי ההעלם דעצמות אוא\"ס שנק' טה\"ע בגילוי ההעלם בעצמות הנפש טרם שבא להיות מקור לחיות הגשמי' וזהו שהי' הוא ושמו בלבד כו') וד\"ל.\n<b>ולפ\"ז</b> יתורץ ג\"כ כל ענין הנ\"ל בג' דברים שא\"א לומר למעלה שהוא השינוי וההתפעלות והערך והשתוות דנברא בע\"ג עם בלתי בע\"ג וגם איך ימצא ב\"ג מבלתי בע\"ג שאם הנפעל דומה לפועל האלקי ממש הי' צריך שיהי' גם הוא בלתי מוגבל ומאחר שרואים הנפעל מוגבל איך הכח הפועל בלתי בע\"ג. אך כל זה אינו שייך רק בבחי' השתלשלו' דרך קירוב הערך כעו\"ע בבחי' שפע דמהות משפיע למקבל כנ\"ל, והיינו כמו כן בחי' כח המתפשט מפועל לנפעל כו', אבל כשהוא בבחי' אור שהוא כמו בחי' חיות הרוחני שמאיר מעצם אלקות הבלתי בע\"ג יכול להיות שאין כאן ג' דברים הנ\"ל, לא שינוי אף בגילוי האור שהוא החיות אלקי בנבראים אף שמתפעל בין טו\"ר שבעולמות עד עוה\"ז כמ\"ש ולו נתכנו עלילות<sup data-n=\"4006\">316</sup> ועיניו פקוחות<sup data-n=\"4007\">317</sup> כו' וא' מחטו לי כמחט<sup data-n=\"4008\">318</sup> כו' כחיות הנפש בגוף שתתפעל ממקרי הגוף כטו\"ר",[["3999","309","<b>הנפש. . תתפעל ממקרי הגוף</b>: ראה גם לעיל פ' שמות כח, ב. תרומה שיג, ב."],["4000","310","<b>אדם א' דם</b>: ראה מבו\"ש ש\"ה, ח\"ב פ\"ה. לעיל פ' וארא עב, ד הערה 22."],["4001","311","<b>ואתה מחי\"ה את כולם</b>: נחמי' ט, ו."],["4002","312","<b>אלקי\"ם חיים ומלך עולם</b>: ברכת יוצר."],["4003","313","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה גם לעיל פ' וארא ס, ב ובהערה 24."],["4004","314","<b>אי אנת. . כגופא בלא נשמתא</b>: ראה ת\"ז בהקדמה (יז, ב)."],["4005","315","<b>ממאציל לאצי'. . פרסא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560027\" data-slug=\"or-hatorah-hb\" data-id=\"8316560027\">אוה\"ת בראשית (כרך ג) ע' תפ</a>."],["4006","316","<b>ולו נתכנו עלילות</b>: נסמן לקמן הערה 322."],["4007","317","<b>ועיניו פקוחות</b>: ירמי' לב, יט [ושם: עיניך — ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קו]."],["4008","318","<b>מחטו לי כמחט</b>: וירא כ, ו. ראה זהר ויקרא ח, א."]]],[2300550638,"כו', וראי' מחטאת סדום שא' הכצעקתה הבאה אלי<sup data-n=\"4009\">319</sup> ממש כמ\"ש בזוהר. אבל באמת זהו ג\"כ ע\"י צמצום ודילוג גדול בבחי' הארה דהארה לבד כנ\"ל <span data-k=\"pg\">956</span> ּ מענין אד\"ם<sup data-n=\"4010\">320</sup> שרוחניות שבגשמיות הגוף אין לו ערך לרוחניות בעצם כו', וא\"כ ודאי אין שינוי והתפעלות וערך בעצם אור האלקי קודם שמתלבש בתוך כל נברא ממש ומצד דילוג המדריגות יכול להיות בע\"ג מהארה דהארה זו בשינוי המהות לפי שצמצם אור העצמי שהוא גילוי ההעלם ונסתלק ושם אין שינוי כלל ולא התפעלות וכמו אם צדקת<sup data-n=\"4011\">321</sup> כו' ול\"א נתכנו בא'<sup data-n=\"4012\">322</sup> כו'. וז\"ש אתה הוא כו' בלי שינוי כלל וכמ\"ש בזהר מסטרא דשכינה לא ראיתם כל תמונ\"ה<sup data-n=\"4013\">323</sup> כו'. ומ\"ש עיני ה'<sup data-n=\"4014\">324</sup> אזני ה'<sup data-n=\"4015\">325</sup> וכל תוארי אדם שזהו בא בשינוי והתפעלות וערך כו', הכל הוא רק בבחי' גילוי החיות בכלים נבדלים בערך שהן המלאכים שנק' אברי דשכינה<sup data-n=\"4016\">326</sup> כמו היוצר עי\"ן שהוא המלאך המשגיח כו' הלא יביט<sup data-n=\"4017\">327</sup> שבהעדר הכלי אין גרעון באור וחיות האלקי הרוחני' בעצם כלל, כמו שאין גרעון בנפש אף בגילוי הכחות שבה עצמה בראיה ושמיעה והילוך הרוחני במה שנחסר מן האברים כעין ואוזן כו' (וראי' מן הגלגולים שהנפש תתלבש באבן<sup data-n=\"4018\">328</sup> ובהמה ואין האבן שכל ומדו' ואין שינוי כלל בנפש בהתלבשותה באיש זה לאיש אחר, אע\"פ שמחולקים בטבעם כע\"ה וחכם תינוק וגדול כו' הנפש אחת היא וכן ראי' ממה שסומא וקיטע מוליד שלם<sup data-n=\"4019\">329</sup> שאין חסרון זה הגשמי בכח המוליד שבנפש כלל) (וכמו\"כ יובן גם בעולם האצי' בע\"ס או\"כ כחכמה מוחא חסד דרועא<sup data-n=\"4020\">330</sup> כו' שנק' כלים נבדלים לאורות שהם אשתארו כגופא כו', א\"כ זהו ג\"כ בחי' אור שנק' חיות בכלים דאצי' כמו מל' דאצי' בבי\"ע ממש כו').\n<b>אך</b> באמת גם משל זה אינו משל ודמיון אמיתי למעלה באלקות דהגם שלפ\"ז המשל אין לנברא ערך כלל להיותו נמשך רק מהארה דהארה האלקית מבחי' גילוי דגילוי העצם כחיות הגופני למטה כנ\"ל, אבל מ\"מ גם בחי' גילוי דגילוי זה האלקי' נחשב גם הוא בבחי' אלקות עכ\"פ (כמו חיי בשר ודם בגוף שמקבל עכ\"פ מחיי הרוחניו' דנפש בעצם), וא\"כ גם בזה לא יתכן ג' דברים הללו דשינוי והתפעלות וערך ויחוס, ולפי הנ\"ל בדילוג אור וגילוי זה שנק' הארה דהארה נתפס הוא בעולמות כערך וקירוב ומתפעל כו' כמו הנשמה בגוף ממש כך המלאכים נק' אברי השכינה מארי דעיינין<sup data-n=\"4021\">331</sup> ואודנין<sup data-n=\"4022\">332</sup> וכה\"ג כנ\"ל. ובאמת הרי גם בבחי' כח ואור גילוי אלקות זה המצומצם בתוך כל עלמין לא יתכן בו שינוי והתפעלות וערך כלל כמו שא' דאת\"ה הוא קודם כו' שמדבר באת\"ה שמחי' את כולם כנפש שמחי' לגוף כו'. וראי'",[["4009","319","<b>הכצעקתה הבאה אלי</b>: וירא יח, כא. ראה זהר שם קו, א."],["4010","320","<b>אד\"ם</b>: אולי כתוב: א' דם."],["4011","321","<b>אם צדקת</b>: איוב לה, ז."],["4012","322","<b>ול\"א נתכנו בא'</b>: נסמן לעיל פ' יתרו רסא, ד."],["4013","323","<b>מסטרא דשכינה לא ראיתם כל תמונ\"ה</b>: נסמן לעיל פ' יתרו רסה, א."],["4014","324","<b>עיני ה'</b>: עקב יא, יב. ראה ת\"ז ת\"ע (קלא, א)."],["4015","325","<b>אזני ה'</b>: בהעלותך יא, א. יח. ראה ת\"ז שם."],["4016","326","<b>המלאכים שנק' אברי דשכינה</b>: ראה פרדס (שער היכלות) שכ\"ד, פי\"א."],["4017","327","<b>היוצר עי\"ן. . הלא יביט</b>: נסמן לעיל פ' יתרו רסה, א."],["4018","328","<b>הגלגולים. . באבן</b>: ראה גם לעיל פ' שמות כח, ב. וש\"נ."],["4019","329","<b>שסומא וקיטע מוליד שלם</b>: ראה גם לעיל שם. וש\"נ."],["4020","330","<b>כחכ' מוחא חסד דרועא</b>: ראה ת\"ז בהקדמה (יז, א)."],["4021","331","<b>מארי דעיינין</b>: ראה זהר בשלח נ, ב. ויקהל רב, א. ת\"ז ת\"ל (עה, א). ת\"מ (פ, א). ת\"ע (קלא, א)."],["4022","332","<b>מארי. . ואודנין</b>: ראה זהר ויקהל שם. ת\"ז שם. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490133\" data-slug=\"or-hatorah-hb\" data-id=\"8316490133\">אוה\"ת וירא כרך ד ע' תשלו</a> ואילך."]]],[2300550644,"לזה ממה שא' דהוא מקומו ש\"ע ואין העולם מקומו דגם במדריגה זו דנתפס בעולמות ונק' מקומו ש\"ע גם הוא אינו מקומו כמא' דתפיס בכולהו עלמין ולית מאן דתפיס בתפיסא זו דממכ\"ע (ולא כחיי הנשמה בגוף שמתפעלת כו') (וכנ\"ל בענין ד\"ת שהוא מאין ליש אין בזה שינוי כלל ונחשב כמו ד\"ע דהוי' סוכ\"ע (וכמשי\"ת). ועוד דגם בבחי' גילוי דגילוי החיות בעצם מ\"מ נק' בשם תואר ושם חיות עכ\"פ, רק שנמשך מרוחניות לגשמיות כצמיחה גשמי' מצמיחה רוחני' א\"כ זהו ערך ויחוס ונק' יש מיש ולא יש מאין ממש ובמע\"ב העיקר הוא מה שמהווה אותם מאי\"ן ממש. ועוד דלפי הדמיון מחיות הנפש בגוף הלא יש לגוף וחומר מציאות <span data-k=\"pg\">תעח</span> ּ קודמת בפ\"ע לבד האור וחיות דצורה הרוחניות שנמשכת בו אח\"כ להחיותו וכמו שאמר אשתארו כגופא כו', ולמעלה א\"א לומר דודאי א\"א להיות שום מציאות דבר מה בעולם שיהי' לו התהוות מעצמו כ\"א כהתהוות מאין ליש מאור האלקי שאין לך דבר חוץ ממנו וממך הכל<sup data-n=\"4023\">333</sup> כתיב גם החומר של הנבראים כמו הצורה וכמו במע\"ב שא' תוצא הארץ נפש חי' ויצא חומר וצורה דבע\"ח כשור וארי' כא' וכמו שא' בקומתן נבראו<sup data-n=\"4024\">334</sup> כו', וא\"כ איך יתכן ענין התגלות<sup data-n=\"4025\">335</sup> החיות האלקי בתוך כל עולם ובריאה כנפש בגוף דמהיכן נמצא מציאות גוף החומר דבריאה (וכן באצי' שא' אשתארו כגופא כו' מהיכן יש התהוות מציאות לגופא זה כו' (וכמ\"ש במ\"א).\n<b>אלא</b> צריך לומר בהכרח דגם לשון זה דבחי' ההתגלות דחיות בגילוי חיות הנפש בגוף הוא ג\"כ שם המושאל למעלה באלקו', ואע\"פ שנק' אלקי' חיים וכן חי העולמים וכמ\"ש ואתה מחי' את כו' דברה תורה כלשון בנ\"א וכן מארז\"ל כמו שהקב\"ה ממלא<sup data-n=\"4026\">336</sup> כו', זהו הבא לדמות כמו שיוכל האדם להשיג לפי אופן שכלו ודעתו המצומצם שהוא נברא בע\"ג ומחודש כו' דא\"א להשיג באלקו' בעולמות כ\"א בלשון זה דחיות שיודע ומכיר באופן זה בחיי נפשו. אבל באמת אין לו דמיון כלל מדמות ותואר חיות כחיי הנפש בגוף מאחר שאין לו ית' דמיון וערך להיות כגוף ונשמה שנברא גם הוא מאין ליש רק לפי שנעשה בצלם אלקים<sup data-n=\"4027\">337</sup> כו' ע\"כ א' מבשרי אחז\"ה אלו\"ה<sup data-n=\"4028\">338</sup> כידוע, ולזה או' בפייט חי ולא בחיים<sup data-n=\"4029\">339</sup> דאע\"פ שנק' חי או אלקים חיים זהו בבחי' חיים העליונים שאין לחיים התחתונים ערך ודמיון לזה כלל. ואף בגילוי דגילוי מעצמות אלקות בהארה דהארה אין זה בחי' חיים ממש אלא ענין הארה דהארה זאת, ומה שנמשל לאור וחיות בציור ותמונה דאדם בכתובי' ובזוהר וגמ' אע\"פ שאין לו דמות הגוף כמ\"ש כי לא ראיתם כל תמונה ועכ\"ז א' ותמונת ה' יביט<sup data-n=\"4030\">340</sup>",[["4023","333","<b>וממך הכל</b>: דהי\"א כט, יד."],["4024","334","<b>בקומתן נבראו</b>: חולין ס, א."],["4025","335","<b>התגלות</b>: אולי כתוב: התחלקות."],["4026","336","<b>כמו שהקב\"ה ממלא</b>: ראה ברכות י, א."],["4027","337","<b>שנעשה בצלם אלקים</b>: בראשית א, כז. נח ט, ו."],["4028","338","<b>מבשרי אחז\"ה אלו\"ה</b>: איוב יט, כו [ושם — ומבשרי]. נסמן לעיל פ' בא צח, ב."],["4029","339","<b>בפייט חי ולא בחיים</b>: ראה מו\"נ ח\"א, פנ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תקד."],["4030","340","<b>ותמונת ה' יביט</b>: בהעלותך יב, ח."]]],[2300550650,"כמו בבחי' פב\"פ במ\"ת וכמשה וכל הנביאים כו'. הענין הוא רק בבחי' אותיות ושמות בלבד שבחי' גילוי האור האלקי מבחי' ההעלם דעצמותו בא למטה בבחי' צרופי אותיות ושמות כמ\"ש לכו חזו מפעלות אלקים<sup data-n=\"4031\">341</sup> אשר שם שמות ש מות בארץ, ואותיות ושמות הללו נק' גילוי האו\"ר וזיו או כ\"ח וחיו\"ת הגם<sup data-n=\"4032\">342</sup> שכל זה אינו אלא שם המושאל לבד כנ\"ל, מ\"מ מכנים לגילוי האותיו' ושמות בשם אור וזיו ובשם כח וחיו', ואינם כמו אור וזיו שנק' יש מיש ויש לו ערך ויחוס ולא כמו כ\"ח וחיות מטעם הנ\"ל והוא כמו שם אלקים ושם אדנ\"י דאשתמודע אדון על כולא<sup data-n=\"4033\">343</sup> כו', דשם זה הוא עיקר ומקור כל התהוות הנבראים בצורה וחומר שלהם דוקא שזהו הנק' בשם מאי\"ן ליש מאי\"ן ממש ולא בבחי' יש מי\"ש כאור וחיות כו', ובשמות אלה אין שינוי והתפעלות וערך לא מיני' ולא מקצתי' כו'. וגם במה שנתפס מבחי' שמות וצירופי' אלה בעולמות כמו אדנ\"י ב\"ם<sup data-n=\"4034\">344</sup> ממש אין זו תפיסא כלל וכמו שא' דלית מחת\"ב כלל ואין העולם מקומו כנ\"ל והוא שאו' אתה הוא קודם כו' בלא שינוי כנ\"ל וד\"ל.\n<b>ולהבין</b> זה בדרך פרט, הנה באמת אנו מוצאי' במע\"ב שכל עיקר מקור מוצא התהוות כל הנבראים מאלקות הי' דוקא ע\"י האותיות של הדיבור בלבד ואותיות <span data-k=\"pg\">958</span> ּ הדיבור נמשך משם אלקים דוקא, וכמו ויאמר אלקים יהי אור ויהי אור וכן ויאמר אלקי' יהי רקיע ויהי כן וכן בכל המא' וכמו ויאמר אלקים תדשא הארץ<sup data-n=\"4035\">345</sup> תוצא הארץ נפש חי' כו' ויאמר אלקים יהי מאורות<sup data-n=\"4036\">346</sup> כו' עד מאמר נעשה אדם<sup data-n=\"4037\">347</sup> כו'. וא\"כ הרי הי' בזה ב' תנאי' א' שהמאמר הי' בדבר אלקי' דוקא שדבר אלקי' יקום<sup data-n=\"4038\">348</sup> בפועל וכן הי' שמיד שא' אלקי' נעשה הבריאה בפו\"מ כי הוא אמר ויהי<sup data-n=\"4039\">349</sup> הוא ציוה ונבראו<sup data-n=\"4040\">350</sup> וכל בריאה והתהוות הוא מאי\"ן לי\"ש דוקא ולא יש מיש שאין זה מחודש מעיקרו כידוע. והתנאי הב' הי' במה שנמשך משם אלקים זה באותיות הדיבור דוקא, שהוא בצירופי אותיות דמאמר זה שא' יהי אור יהי רקיע וכה\"ג משום דדבר מלך שלטון<sup data-n=\"4041\">351</sup> וכשמלך גוזר ואומר כן יקום וכל זמן שלא בא בדיבור אינו נעשה בפו\"מ, וא\"כ האותיות הללו של יהי אור ותוצא הארץ וכה\"ג הוא עיקר מקור המהווה הבריאה דאור ורקיע וגם החיות ובהמות וצומח דעשב ופירות למטה בגשמיות (וכן למעלה בעולמות הרוחניי' כפני ארי' ושור דמרכבה ואור ורקיע העליונים שיצאו מדיבור העליון כו' דשם אלקים (רק בצומח וחי הי' הציווי לארץ שתדשא הארץ ותוצא הארץ כו') וכמ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאם כו'. ובאמת אין דבר ה' כאותיות הדבור שלנו ולא מחשבותיו כמחשבותינו כמ\"ש כי לא מחשבותי<sup data-n=\"4042\">352</sup> כו' רק לקרב לאוזן דברה תורה כלשון בנ\"א, כמו שהאדם הוא נפש השכלי' שנק' נפש המדברת<sup data-n=\"4043\">353</sup> בחי'",[["4031","341","<b>לכו חזו מפעלות אלקים</b>: נסמן לעיל פ' יתרו רנג, א."],["4032","342","<b>הגם</b>: תיבה זו אינה ברורה."],["4033","343","<b>דאשתמודע אדון על כולא</b>: ת\"ז בהקדמה (יז, ב)."],["4034","344","<b>אדנ\"י ב\"ם</b>: תהלים סח, יח."],["4035","345","<b>ויאמר אלקים תדשא הארץ</b>: בראשית א, יא."],["4036","346","<b>ויאמר אלקים יהי מאורות</b>: בראשית א, יד."],["4037","347","<b>נעשה אדם</b>: בראשית א, כ."],["4038","348","<b>שדבר אלקי' יקום</b>: ישעי' מ, ח."],["4039","349","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["4040","350","<b>הוא ציוה ונבראו</b>: תהלים קמח, ה."],["4041","351","<b>דדבר מלך שלטון</b>: קהלת ח, ד."],["4042","352","<b>כי לא מחשבותי</b>: ישעי' נה, ח."],["4043","353","<b>נפש השכלי' שנק' נפש המדברת</b>: ראה גם לעיל פ' שמות מז, ב. וש\"נ."]]],[2300550656,"רוח ממללא כו', הרי בחי' התגלות האותיות של הדיבור גם מנפש המדברת בלא גוף אינו בא ממהו\"ע הנפש ולא מכחה העצמי' ולא מאור וזיו או חיות העצמי' רק שהן בחי' גילוי ההעלם לבד, כמו אותיות הדבור בה\"מ הפה שנבדלים לחוץ מן העצמות שאינם רק גילוי המחשבה שבהעלם ואינם שייכים כלל וכלל לעצם אור וחיות הנפש, ומ\"מ הן מגלים כל העלם שבנפש כשכל ומדות ומח' ורצון ותענוג הנעלם כו'. אבל גופי האותיות הן כמו בחי' דומם ממש ואין להם ערך כלל לעצם חיות ואור הנפש וכ\"ש לכחות שלה וגם לא לאברים שנק' כלי\"ם מגבילים האור וחיות הגשמי שנחשב מן החיות העצמי' וגם אותיות הרוחני' שבנפש עצמה שנק' רוח ממללא כו' הן ג\"כ רק בחי' גילוי בעלמא (ונק' כ\"ב תנועות רוחניות באופן המשכה וגילוי בתנועות החי שאינו רק מגלה העצם דחי כו').\n<b>וכך</b> הן למעלה בצרופי אותיות דמא' דשם אלקי' שנבראו בהן כל העולמות עליונים ותחתונים כצומח וחי והאור ורקיע וכל אשר בהם מאין ליש כי הוא אמר ויהי שאין דיבור העליון כדיבור האדם שאינו פועל ועושה שום התהוות מאי\"ן ליש, משא\"כ בחי' צרופי אותיות הדיבור האלקי ממנו נתהווה המציאות הברואים מאין ממש בחידוש גמור מעיקרו כו', ולא בבחי' יש מיש. ואע\"פ שאותיות הללו אינם רק בחי' התגלות דאור האלקי בעצם כאותיות הדבור באדם למטה שהאותיות יוצאים לחוץ, כך למעלה באלקו' דבר אלקי' יוצא בגילוי דגילוי מן ההעלם דעצמו' ונק' אותיות שנבראו בהן שמים כו' כמו בצלאל הי' <span data-k=\"pg\">תעט</span> ּ יודע<sup data-n=\"4044\">354</sup> לצרף אותיות שנבראו בהן שמים וארץ כו'. וזהו שא' בזוהר דאתוון אתגליפו<sup data-n=\"4045\">355</sup> פי' בחקיקה לחקיקה שהן צירופים שונים שנמשכים מגילוי האותיות דאלקי' עצמו בריבוי ההשתלשלו' מעילה לעילה בכל עולם ועולם עד האותיות דמא' שנבראו בהן שמים וארץ, והוא כל מע\"ב שמחדש גם עכשיו כו' כמו ממאמר דתדשא הארץ נמשך גם עכשיו כל התהוות תולדה מכח הצומח שבארץ מאין ליש ממש ומאמר דתוצא הארץ גידול כל בע\"ח וכן יהי אור מהווה אור ויהי רקיע מהוה לרקיע זה מאין ליש בדבר מלך שלטון. וכמו\"כ גם בהתהוות העולמות העליונים בחיות ושרפים ואופנים<sup data-n=\"4046\">356</sup> דמרכבה דיצי' ובריאה כו' יש לכאו\"א צירוף מיוחד מאותיות דשם אלקים מהן שנק' מפעלות אלקים בשמות וצירופי' מיוחדים כו' וד\"ל (כמו רחב\"ד שאמר מי שא' לשמן וידליק<sup data-n=\"4047\">357</sup> כו' שהפך הצירוף דשמן לחומץ כו').\n<b>ומובן</b> מזה דאותיות ושמות הללו הן באים בבחי' מהות נבדל מאלקו' עצמו כאותיות דיבור האדם שנבדלים ויוצאים",[["4044","354","<b>בצלאל הי' יודע</b>: ראה ברכות נה, א."],["4045","355","<b>דאתוון אתגליפו</b>: ראה זהר בראשית טו, ב. שעה\"י קמא, ב הערה 46."],["4046","356","<b>בחיות ושרפים ואופנים</b>: ראה אוה\"ת על נ\"ך כרך ג' ע' א'רסה."],["4047","357","<b>מי שאמר לשמן וידליק</b>: תענית כה, א (ובע\"י). ראה גם לעיל פ' שמות כ, א. וש\"נ."]]],[2300550662,"לחוץ כמו כח הזורק שנבדל כח זריקה זו מן היד כו', כך אותיות ושמות שמתלבשי' בתוך כל בריאה בהתהוות צורה וחומר שלה הרי נבדל בריחוק ערך משם אלקים ונק' רק הארה דהארה שבא בשינוי המהות כמו האור שמאיר ע\"י מסך כנ\"ל. וגם שמובן מזה דיש כח האלקי באותיות הללו אחר שהן בחי' גילוי העצמו' לכך הי' ביכולתם להוות עולמות בלי שיעור כלל כמ\"ש בס\"י מכאן ואילך צא וחשוב<sup data-n=\"4048\">358</sup> עד אין שיעור למספר הצירופים כו', מ\"מ באים במספר וגבול כמו המוציא במספר צבאם<sup data-n=\"4049\">359</sup> כו', והוא ע\"פ בחי' הצמצום דשם אלקי' שאמר לעולמו די כו' כי הי' התפשטו' העולם בלי גבול, להיות שגם בחי' האותיות באי' מכח בלתי בע\"ג אע\"פ שאינו רק בחי' גילוי דגילוי ההעלם לבד, וזהו בחי' שם אלקים המצמצם האור וזיו דשם הוי' בכלל ונותן מדה וגבול לצירופי' די\"מ בכל העולמות כו'. ואמנם גם בבחי' אותיות הללו אין שינוי והתפעלות וערך עם הנבראים ונתפס ואינו נתפס כנ\"ל, לפי שגם שנק' האותיות בשם אור וחיות כמו ואתה מח\"י' את כולם<sup data-n=\"4050\">360</sup> את\"ה זה דכ\"ב אותיות דקבען בפה העליון וה' מוצאות כו' דבה\"א בראם<sup data-n=\"4051\">361</sup> מאין ליש והוא ה\"א אחרונה דשם הוי' שמאיר בשם אלקים ע\"י צמצום כשמש ומגן המעלים כו', זהו בענין שם המושאל שאינו בבחי' אור וכח וחיות ממש, שא\"כ ה\"ז בבחי' יש מיש שיש בזה ערך כו'. וגם הרי יהי' למציאות התהוות החומר בלעדי החיות האלקי שמהווה אותו והרי א' ממך הכל כו' שגם החומר של המלאכי' ונבראי' נמשכו מאין ממש והוא מבחי' אותיות בצירופי' שירדו למטה מטה, ועכ\"ז נק' בשם ממכ\"ע כנשמה בגוף וכמו ואתה מחי' כו' וכעיני ה' וכאזני ה' כו' הן בחי' אותיות גשמיות מגבילי' והוא שם המושאל לבד כו' וכן א' אד' ב\"ם ממש. אבל זהו בחי' מקור התהוות של הצורה וחומר כמו ברקיע ומזלות עד גם עשב הגשמי שמקבל מכח הצומח שבארץ ע\"י מא' תדשא הארץ וכה\"ג, רק ששם אד' ושם אלקי' הוא למעלה מן הצירופי' ואותיות ושמות הפרטי' כאותיות הדבור שיוצאי' ונבדלי' מן העצמו' דשם אלקי' הוא הגוף האומר המאמר הפרטי וכן <span data-k=\"pg\">960</span> ּ שם אד'.\n<b>והענין</b> הוא דבחי' צירופי אותיות הדבור נק' מפעלות אלקי' לבד ששם שמות כו', ואלקי' עצמו הוא מקור הראשון שממנו נמצאו כל האותיות כמו ויאמר אלקי' כו' כדבר מלך שגוזר ואומר ועושה. ואמנם שם אלקי' או שם אד' אע\"פ שנחשבו מז' שמות<sup data-n=\"4052\">362</sup> שאינם נמחקין והן בבחי' אלקות ממש כמו שם הוי' כו' עכ\"ז הרי נק' בבחי' שם עכ\"פ כמו שמו של אדם שאינו שייך למהו\"ע שלו רק שנק' בשם זה לזולתו כשקוראי' אותו ולעצמו א\"צ כלל לשם זה כידוע, וכמו קריאת שם ראובן",[["4048","358","<b>מכאן ואילך צא וחשוב</b>: ס\"י פ\"ד, מי\"ב."],["4049","359","<b>המוציא במספר צבאם</b>: ישעי' מ, כו."],["4050","360","<b>ואתה מח\"י' את כולם</b>: נחמי' ט, ו. ראה זהר בראשית טו, ב. (היכלות) פקודי רסא, א. שער היחוה\"א פ\"ב."],["4051","361","<b>דבה\"א בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["4052","362","<b>שם אלקי'. . אד'. . מז' שמות</b>: ראה לעיל פ' בא קיב, א. וש\"נ."]]],[2300550668,"שאין זה שם מצד עצמו ומהותו שאין חילוק לעצמו ומהותו אם היו קוראי' אותו בשם אחר רק שיהי' נפנה לקוראו שבלא שם אין תפיסא בו לקוראו שיפנה לשם וזהו כמו בית יד לכלי שיהי' נתפס בו וכה\"ג. וכך יובן למעלה דמה שיהי' נתפס למעלה מאור<sup data-n=\"4053\">363</sup> האלקי הבלתי בע\"ג צריך להיות בקריאת שם שאין זו תפיסא ממש במהו\"ע רק בבחי' הקריאה לבד, ואמנם קריאה זו היא לפ\"ע הנפעל ממנו והוא שנק' שם הפעולה שנק' ע\"ש פעולתו שנפעל ממנו בדיבור ומעשה, כך הוא קריאת השם שיהי' נתפס על ידו למטה. וכמו\"כ עד\"מ למעלה שם אד' או שם אלקים הוא ע\"ש הפעולה האלקי' ששם אלקים הוא הגוזר ואומר ועושה בדבר אלקי' כמו בי\"מ נק' ע\"ש פעולתו בשם אלקי' כמו אלקי השמים והארץ וכל צבא העליונים כו', דאלקים לשון כח<sup data-n=\"4054\">364</sup> וחיות כמו אל מאלקי' ענין כח ותוקף שממנו נמצא כל הנמצאים כמו ורב כח כו', וגם לשון שררה<sup data-n=\"4055\">365</sup> וממשלה כמו נשיא אלקים אתה<sup data-n=\"4056\">366</sup> כו' עד האלקי' יבוא<sup data-n=\"4057\">367</sup> כו'. והוא האור האלקי שנמשך בבחי' מל' כמ\"ש מלכותך מלכות כ\"ע וממשלתך<sup data-n=\"4058\">368</sup> כו', כמו ששם המל' על אנשי המדינה שנקראו על שמו בלבד ובזה השם המה נקראי' שלו אע\"פ שנבדל ומרומם בעצם מהותו מהם וגם שמו נשגב ומרומם על הכל בבחי' מקיף שהוא רק בחי' ההתנשאות דשם מלכות עליהם שבזה נתפס בהם ונקראי' על שמו ממש כאלו בראם ועשאם כו'. וכך במל' שמים דקריאת שם מלכותו ית' על כל העולמות הוא קריאת שם בהתנשאות האלקי' מרחוק בבחי' מקיף על הכל, וגם זה אינו רק בחי' שם לבד רק שהוא שם מלכותו המתפשט ונק' אדון ומושל כמו אדון כל הארץ<sup data-n=\"4059\">369</sup> דאשתמודע אדון על כולא ונק' אל אדון על כל המעשים<sup data-n=\"4060\">370</sup>, וכן שם אלקי' שם זה הוא בחי' נבדל מן העצמות ע\"ש השררה ואדנות כמו כי אלקי' שופט<sup data-n=\"4061\">371</sup> כו' ומרומם בשם זה על כל העולמות בבחי' מקיף כו'. ולא יתכן לומר שיומשך משם זה דאד' ואלקים בחי' אור או כח וחיות ושפע ממש בתוך כל עולם ובריאה מאחר שאינו אלא בחי' שם מלכותו שמתנשא על כל כו'. ואמנם עכ\"ז ה\"ז מקור הראשון לענין אור ושפע והמשכה האלקי' לכל העולמות להחיותם בעיקר מציאותן מאין ליש ממש כמו כח הפועל ע\"י הדיבור העליון שמקבל משם אלקים ושם אד' כמו אד' ב\"ם כו', רק שאותיות ושמות דדבר אלקי' זה הוא נמשך רק בבחי' הארה דהארה מאותיות השם דאלקי' שיש בו ק\"ך צירופי'<sup data-n=\"4062\">372</sup> בכלל כו'. ואע\"פ שנק' שם הפעולה כמו בשם אד' שנק' אדו\"ן וכן אלקי השמים והארץ<sup data-n=\"4063\">373</sup> כו' מ\"מ נחשבו מז' שמות כו' כשם הוי' ושם שדי וצבאות<sup data-n=\"4064\">374</sup> כו', משום ששם אלקי' מתאחד בעצמות אוא\"ס שבאצי' דאיהו וגרמוהי חד כו' <span data-k=\"pg\">תפ</span> ּ שגם בחי' המל' שנק' אלקי' או אד'<sup data-n=\"4065\">375</sup> הוא",[["4053","363","<b>מאור</b>: תיבה זו אינה ברורה בגוכתי\"ק."],["4054","364","<b>דאלקים לשון כח</b>: נסמן לעיל פ' תרומה שה, א."],["4055","365","<b>דאלקים. . לשון שררה</b>: ראה רש\"י בראשית ו, ב. לעיל פ' וארא ס, א. וש\"נ."],["4056","366","<b>נשיא אלקים אתה</b>: ח\"ש כג, ו."],["4057","367","<b>עד האלקי' יבוא</b>: משפטים כב, ח."],["4058","368","<b>מלכותך. . וממשלתך</b>: תהלים קמה, יג."],["4059","369","<b>אדון כל הארץ</b>: יהושע ג, יא."],["4060","370","<b>אל אדון על כל המעשים</b>: ברכת יוצר דשבת. זהר תרומה קלב, א."],["4061","371","<b>כי אלקי' שופט</b>: תהלים עה, ח."],["4062","372","<b>השם דאלקי' שיש בו ק\"ך צירופי'</b>: נסמן לעיל פ' יתרו רסג, ג."],["4063","373","<b>אלקי השמים והארץ</b>: ח\"ש כד, ג [ושם: ואלקי הארץ]."],["4064","374","<b>מז' שמות. . הוי' ושם שדי וצבאות</b>: ראה לעיל פ' בא קיב, א. וש\"נ."],["4065","375","<b>המל'. . אד'</b>: ראה זהר ויקרא יא, א. לעיל פ' וארא עה, ב. וש\"נ."]]],[2300550673,"כשאר שמות העצמיי' דאצי' שנק' שם התואר או שם העצם כמו קריאת שמות לאדם שמורה על עצם מהותו (כמו שקרא אדם שמות לכל הבהמה וחי'<sup data-n=\"4066\">376</sup> שזהו ע\"ש עצם מציאותו ומהותו שא\"א לקרותו בשם אחר כלל כשם ארי' ושור וכן קריאת שם אדם כו' וכמו קריאת שם האותיות אל\"ף בי\"ת (כמ\"ש במ\"א). ויש בזה ב' מדרגות א' באור, והב' בכלי, שהכלי המגביל האור נק' שם התואר כמו שמתארי' שם חכם ע\"ש עצם חכמתו שעכ\"ז אין בשם זה עצם מהות חכמתו ממש כאור השכל שבכלי מוח, אך בכלי המוח יתכן לקרותו חכם ע\"ש גילוי אור חכמתו במושכלות הנגלות בהשגה שבמוח חו\"ב כו', וכמ\"כ שם חסדן ורחמן בכלים דמדות שבלב שמתארי' ומציירים לעצם האור דחסד ורחמים ונדבן וכן להיפוך למדת הדין וכה\"ג. והב' שם העצם שהוא באורות עצמן כאור החכ' ובינה שמוגבל בכלים דחו\"ב וכן אורות דחו\"ג כו' דאע\"פ שגם הן רק שמות של העצמו' דחכ' ובינה של הנפש מ\"מ נק' שם העצם ממש ולא ע\"ש התגלות בכלים מגבילים כו' (כמ\"ש במ\"א).\n<b>ומזה</b> יובן בדוגמא למעלה בהפרש בין שמות דע\"ב ס\"ג מ\"ה ב\"ן דע\"ס דאצי' באו\"כ כמו שנק' חכים ומבין כו' שהוא בשם ע\"ב וס\"ג כנ\"ל היינו כמו שמות התואר בכלי המגביל לאור ושם העצם דאור דחו\"ב כו', שע\"ז א' בכלל דאיהו אור א\"ס עצמו וגם חיוהי שהן האורות דע\"ס וגרמוה\"י הן הכלים דחו\"ב ומדות שנק' שמו' התואר שמתארי' ומגבילי' לאורות כו' חד ממש, כי אין אותיות ושמות אלה בחי' נבדל כ\"כ מעצמו' אע\"פ שאינו אלא שם ואותיות כמו שא' בר\"מ עביד מאנא וקרא בה גרמי' חכ\"ם<sup data-n=\"4067\">377</sup> כו'. ומה שא' בלשון ציור אור וכלי כמו כלי הגוף בחכ' מוחא חסד דרועא כו', זהו שם המושאל שאין לו גוף ולא דמות כו' אפי' בהתלבשות אור האלקי בבי\"ע כנ\"ל בשם אלקים ושם אד' שנק' שם הפעולה מ\"מ הוא בבחי' מקיף דשם ומל' על כל העולמות כנ\"ל וגם שם ב\"ן דמל' איהו וגרמוהי חד כשמות דע\"ב וס\"ג דחו\"ב כו' כידוע. אך לשון זה דאשתארו כגופ\"א כו' זהו כמו אותיות ושמות דע\"ב וס\"ג ומ\"ה שבחכ' ומדות שבבחי' כלי\"ם בלא אורו' כו' (כמ\"ש בסידור<sup data-n=\"4068\">378</sup> ), וכך הוא בענין או\"כ כאור הנשמה באברי' במל' דאצי' במלאכים דבריאה כמו עיני ה' כו' וכמו רגלי השכינה<sup data-n=\"4069\">379</sup> וכה\"ג זהו הכל שם המושאל שאין בחי' עין ואוזן בציור ותמונה דאד\"ם אפי' ברוחניות למעלה, רק שהן בחי' שמות וצירופי' שמגבילי' בכלי\"ם שונים שהן מלאכים שמגבילי' לאור הראי' דחכ' דמל' ושמיעה דבינה שבמל' וכן גם בכינויי' דשם הוי' דאצי' כמו עיני ה' משוטטי'<sup data-n=\"4070\">380</sup> כו' וישמע הוי'<sup data-n=\"4071\">381</sup> וישב וילך<sup data-n=\"4072\">382</sup> כו' וכל תוארי",[["4066","376","<b>שקרא אדם שמות לכל הבהמה וחי'</b>: בראשית ב, כ. ראה מאמרי אדה\"א דברים ח\"ד ע' א'רסח ואילך. לעיל פ' בא קיג, ג."],["4067","377","<b>עביד מאנא וקרא בה גרמי' חכ\"ם</b>: ראה זהר (רע\"מ) בא מב, ב."],["4068","378","<b>כמ\"ש בסידור</b>: ערב שבת קסו, א."],["4069","379","<b>רגלי השכינה</b>: ברכות מג, ב. ת\"ז ת\"ע (קלא, א). ראה גם מאמרי אדה\"א שמות ח\"א ע' קט. וש\"נ."],["4070","380","<b>עיני ה' משוטטי'</b>: זכרי' ד, י [בדילוג]."],["4071","381","<b>וישמע הוי'</b>: בהעלותך יא, א."],["4072","382","<b>וישב וילך</b>: תהלים כט, י. וירא יח, לג."]]],[2300550678,"אדם הן רק בחי' כלים מצירופי אותיות ושמות המגבילים לאורות כנ\"ל בכלים דע\"ס דאצי' וד\"ל.\n<b>ובכל</b> זה יתורץ כל ענין הנ\"ל בבחי' התפשטות האור האלקי להוות העולמות מאין ליש שגם שנק' בבחי' אור וחיות או כח הכל <span data-k=\"pg\">962</span> ּ הוא רק בבחי' צירופי אותיות ושמות דשם אלקי' ושם אד' שכוללים כל הצירופי' ושמות ומצד שנתפסי' בכל העולמות נק' כמו כח וחיות, וכמו ציור אדם בכח הפועל בנפעל כמו שא' אף ידי יסדה ארץ וימיני טפחה שמים ובאמת הרי בדבר ה' שמים נעשו כו' כמ\"ש יהי רקיע ואיך א' ימיני כו', אלא שדברה תורה כלשון בנ\"א שזהו כמו בחי' כח הפועל דאדם ביד ימין וכמארז\"ל נטה ימינו וברא השמים<sup data-n=\"4073\">383</sup> והוא בחי' חסד העליון שנק' דרועא ימינא בשם הוי' דאצי' שירד למטה בהתלבשות דמאמר יהי רקיע וכן במא' יהי אור וכה\"ג בכל מע\"ב שנק' בבחי' עשי' ופעולה גשמי' דוקא ונק' מעשה ידיו כו' כמו כולם בחכ' עשית כו', זהו הכל מבחי' צירופי אותיות די\"מ שבא בבחי' מעשה בפו\"מ מאי\"ן ליש ממש כנ\"ל ושרשם הכללי הוא בחי' שם אלקים ושם אד' שנק' שם הפעולה וע\"ש האדנות ושררה דוקא מטעם הנ\"ל וד\"ל.\n<b>והנה</b> לפי כל הנ\"ל יובן עכ\"פ שכל עיקר ומקור הראשון שממנו נמצא מקור כל התהוות העולמות והברואי' מאין ליש שהוא התהוות בע\"ג מבלתי בע\"ג באין שינוי וערך כו' כנ\"ל זהו רק מבחי' שם כבוד מלכותו ית' דמלכותו מכ\"ע כו' וכמ\"ש כבוד מלכותך יאמרו<sup data-n=\"4074\">384</sup> כו', ואינו רק בחי' שם בלבד שמובדל מן העצמו' דאלקו'. אמנם זהו בחי' הרוממות וההתנשאו' דאלקו' להיות מתנשא מימו\"ע כמו ה' מלך גאות לבש<sup data-n=\"4075\">385</sup> שמתלבש בגיאות המצומצם הזאת להיות ראש ומקור לעולמות ונק' אדון על כולא שצ\"ל ע\"י צמצום גדול, והיינו צמצום דשם אלקי' שמצמצם על שם הוי' שהוא שם העצם והתואר שהן ע\"ס דאצי' ברצון וחו\"ב ומדות בכלל באו\"כ שנכללים בשם הוי' יו\"ד בחכמה כו' והן ד' שמות דע\"ב ס\"ג כו'. ואמנם שם אלקים זה מסתיר ומעלים על שם הוי' כמגן לשמש כידוע במ\"ש כי שמש ומגן<sup data-n=\"4076\">386</sup> הוי' ואלקים דאלקים כמו מגן ונרתק לשם הוי' וכמ\"ש בזוהר דשם הוי' הוא כמו השמש עצמו ונרתק שלו שמעלימו בכדי שתאיר אור וזיו לבד זהו שם אלקי' שהוא בחי' המל' שמתלבש בהתנשאות על העולמות ומזה דוקא יבא סיבת מקור התהוות שלהם להחיותם מאין ליש (וכמו המלאכי' עכשיו שעיקר חיותם וקיומם גם עתה מקבלת מ\"ש באימה וכמו וכולם מקבלים עליהם<sup data-n=\"4077\">387</sup> כו' וכמ\"ש יראת ה' לחיים<sup data-n=\"4078\">388</sup> ולכך המלאכים נצחי'",[["4073","383","<b>נטה ימינו וברא השמים</b>: ראה פדר\"א פי\"ח. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>."],["4074","384","<b>כבוד מלכותך יאמרו</b>: תהלים קמה, יא."],["4075","385","<b>ה' מלך גאות לבש</b>: תהלים צג, א. ראה גם הנסמן לעיל פ' וארא עה, א."],["4076","386","<b>כי שמש ומגן</b>: תהלים פד, יב [ושם: אלקים]. ראה שער היחוה\"א רפ\"ו. הנסמן לעיל פ' שמות לד, ד."],["4077","387","<b>וכולם מקבלים עליהם</b>: ברכת יוצר."],["4078","388","<b>יראת ה' לחיים</b>: משלי יט, כג. ראה סידור שער הק\"ש פב, סע\"ג בשם הה\"מ. לעיל פ' בא ק, א. וש\"נ."]]],[2300550683,"יותר כידוע), ולע\"ל ה' יוציא חמה מנרתקה<sup data-n=\"4079\">389</sup> שהוא שם אלקי' כמ\"ש ונגלה כבוד הוי' כו' (כמשי\"ת).\n<b>והנה</b> יובן מזה דאותיו' וצירופי' של כל מע\"ב מקבלים משם אלקי' כמו ויאמר אלהים כו' או שם אד' כמ\"ש אד' ב\"ם ממש כמרכבה שנושא לרוכב לכך נק' רוממי שדי<sup data-n=\"4080\">390</sup> ונק' רכב אלקי'<sup data-n=\"4081\">391</sup> כו', ושם הוי' מלובש בהעלם בשם אלקי' ושם אד' כמו אור השמש שמתעלם במגן ונרתק או בלבנה. ונמצא האור המאיר משם אלקי' ושם אד' בצירופי אותיות דמע\"ב שנמשכים מק\"ך צירופי' דשם אלקי' אינו רק בחי' הארה דהארה לבד כמו מאור של הלבנה שמקבלת משמש המאירה לארץ וכה\"ג, וגם זה נמשך מאדון כל הארץ או אלקי השמים כו' רק מבחי' מקיף דהתנשאות דמל' כמו מל' דבריאה שמהווה עולם הבריאה ומל' דיצי' ביצי' עד מל' דעשי' בעשי' כו'. ואמנם הגם שכל זה נמשל לבחי' אור וזיו עכ\"פ רק שהוא בבחי' הארה דהארה לבד כנ\"ל, מ\"מ אינו ענין משל ודמיון אמיתי דאור וזיו בכל <span data-k=\"pg\">תפא</span> ּ מקום שהוא יש לו שייכות וערך לגבי המאור עצמו לפי שכל עצם בהיר בהכרח יבהיק ויאיר אור כדוגמתו שהוא מאור, אבל בחי' אותיות דשם אלקי' (וגם אותיות דשם הוי' כנ\"ל) אין לו שייכות וערך לגבי אור העצמות רק במה שנקרא שמו לגבי המקבלים שנתפס בהן כו', וכן צירופי אותיות ושמות שהן מקוריי' לכל בריאה אינם בבחי' אור וזיו אלקי רק בחי' אותיות לבד שהוא רק גילוי דגילוי ההעלם בבחי' מהות וערך נבדל כנ\"ל. ועכ\"ז נק' בחי' אותיות דשם מלכותו בשם זיו יקרי' כמו קדוש הוי' כו' מלא כה\"כ<sup data-n=\"4082\">392</sup> ונק' הוד והדר<sup data-n=\"4083\">393</sup> כמו וכבוד הדר מלכותו<sup data-n=\"4084\">394</sup> כו' וכמו כי עמך מקור חיים שהוא בחי' אלקי' באורך נראה אור כנ\"ל וד\"ל (וכמו בשם הוי' דאצי' אע\"פ שהוא בבחי' שם התואר והעצם באו\"כ דאצי' בחכמה מוחא כו' נק' בבחי' שם עכ\"פ כמו שם ע\"ב במילוי יודין<sup data-n=\"4085\">395</sup> בחי' כלי לאור החכ' דאצי' ושם ס\"ג כו' וכה\"ג. ובכלל נק' רזא דשמא קדישא<sup data-n=\"4086\">396</sup> שהוא שם הוי' שאינו כמו בחי' אור זיו של המאור שהוא עצמות המאציל אלא רק בחי' שמו שמתואר בשם חכים ומבין ומצד עצמו לא בחכ' ידיעא כו'. וגם מה שנאצל בחי' אור דחכמה או בינה בא ג\"כ ע\"י בחי' אותיות ושמות רק שהן בחי' ושמות דעצמות המאציל בבחי' ההעלם דע\"ס הגנוזות בעצמות שנק' סדכ\"ס כו' וכמו שא' אנת ממלא כל שמהן כו' (כמ\"ש במ\"א).\n<b>והנה</b> בזה יובן מה שמצינו שגם המלאכים דבריאה וגם דיצי' ועשי' כאופנים וחיות או' קדוש הוי'<sup data-n=\"4087\">397</sup> כו' מכה\"כ דקאי על שם הוי' דוקא והאופני' או' ברוך<sup data-n=\"4088\">398</sup> כבוד הוי' ממקומו דוקא,",[["4079","389","<b>ה' יוציא חמה מנרתקה</b>: ראה ע\"ז ג, סע\"ב. לעיל פ' שמות לט, ב. וש\"נ."],["4080","390","<b>רוממי שדי</b>: ברכת יוצר. ראה גם לעיל קעט, ב. וש\"נ."],["4081","391","<b>רכב אלקי'</b>: תהלים סח, יח."],["4082","392","<b>קדוש. . מלא כה\"כ</b>: ישעי' ו, ג."],["4083","393","<b>הוד והדר</b>: תהלים כא, ו. ועוד."],["4084","394","<b>וכבוד הדר מלכותו</b>: תהלים קמה, יב."],["4085","395","<b>ע\"ב במילוי יודין</b>: נסמן לעיל פ' וארא פה, ג."],["4086","396","<b>רזא דשמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם. מאמרי אדה\"א הנחות תקע\"ז ע' שנ. וש\"נ."],["4087","397","<b>וחיות או' קדוש הוי'</b>: ראה גם לעיל (במאמר זה) שכה, ב."],["4088","398","<b>והאופני' או' ברוך</b>: יחזקאל ג, יב. ראה חולין צב, א ובתוד\"ה ברוך."]]],[2300550688,"וגם צבא השמים דעשי' כשמים ומלאכים דעשי' או' שירה לשם הוי' דוקא כמו הללו את הוי' מן השמים<sup data-n=\"4089\">399</sup> הללוהו כל מלאכיו<sup data-n=\"4090\">400</sup>, וגם שמש וירח והמים אשר מעל השמים<sup data-n=\"4091\">401</sup> יהללו את שם הוי'<sup data-n=\"4092\">402</sup> (וכן הללו את הוי' כל גוים<sup data-n=\"4093\">403</sup> כו'), ואע\"פ שהמלאכים דבריאה ויצי' וכ\"ש דעשי' וכשמים וכו\"מ מקבלים רק מבחי' אותיות וצירופי שמות המתגלגלי' ומסתעפי' משם אלקים דוקא כנ\"ל (ולכך נק' המלאכים בני אלקים כמו ויבואו בני האלקי'<sup data-n=\"4094\">404</sup> ) ששם אלקי' מסתיר על שם הוי' ולכך או' קדוש הוי' כו' ואיך יהללו לשם הוי' אף השמים וכמו השמים מספרים<sup data-n=\"4095\">405</sup> כו' (שמקור התהוות הרקיע שנק' שמים רק ממאמר יהי רקיע כו' כנ\"ל), וידוע שגם שמים הרוחני' שהן מקיפים דבריאה והמים שמעל השמים הן בחי' מ\"ע שמעל למקיף דרקיע העליון דבריאה כרקיע שבג\"ע דבריאה וכה\"ג מ\"מ שרש מציאותם אינו רק משם אלקים שברא השמים העליונים והתחתונים ע\"י מאמר לבד כנ\"ל. אך הענין הוא דשם הוי' זה הוא שמאיר אפס קצהו בצמצומי' גדולים בשם אלקי' שנק' מגן ונרתק לשם הוי' כנ\"ל, ומשם אלקים יוצא ענין המשכה והארה גם משם הוי' דאצי' בבי\"ע למלאכים ונשמות עד גם לצבא השמים שלמטה יוכל להיות הארת אור דש' הוי' דאצי' כי מרחוק הוי' נראה גם להם, ולא עוד אלא גם לארץ הגשמי' וכל אשר בה שהרי אמר הללו את הוי' מן הארץ תנינים כו' עץ פרי<sup data-n=\"4096\">406</sup> כו' שגם ברוחניות היינו כמו ג\"ע דעשי' שעץ פרי וארזי' הן מלאכים דעשי' שהן בבחי' צומח וחי עד ע' שרים<sup data-n=\"4097\">407</sup> שנק' מלכי ארץ כו', מ\"מ אין מקרא יוצא מידי <span data-k=\"pg\">964</span> ּ פשוטו<sup data-n=\"4098\">408</sup> ומסיים יהללו את שם הוי' דוקא כי נשגב שמו לבדו הודו על ארץ ושמים וירם קרן לעמו כו'.\n<b>והענין</b> הוא לפי שגם עכשיו ששם הוי' מלובש בהעלם בשם אלקי' ושם אלקי' מלובש בשמות וצירופי' שונים עכ\"ז יש יחוד דהוי' באלקי' גם עתה כמו שיהי' לע\"ל שיוציא חמה מנרתקה כו' (כמשי\"ת), ולכך גם עכשיו גם שמים וארץ וכל צבאם הגשמיי' יוכלו להלל לשם הוי' ממש מטעם זה, רק שעכשיו נשגב שמו לבדו בבחי' העלם מרחוק עליהם ורק בחי' הודו על ארץ ושמים פי' הודו זה אינו בחי' הוד וזיו של האור דשם הוי' שהוא בערך ויחוס לעצם המאור כנ\"ל שזה לא יתגלה רק לע\"ל דכתיב ונגלה כבוד הוי' ממש (כמשי\"ת). אבל פי' הודו היינו בחי' הוד וזיו של שמו הנשגב לבדו שהוא שם אלקי' שמקבל מזיו והארה בעלמא משם הוי' הוא שנמשך גם לעולמות בריבוי צמצומים, וגם זה ההוד של שמו דשם הוי' ואלקים על ארץ ושמים בבחי' מקיף מרחוק דוקא והיינו בחי' הוד וזיו שם כבוד מלכותו ית' שהוי' מלך גיאות לבש כו' בהתנשאות האלקי'",[["4089","399","<b>הללו את הוי' מן השמים</b>: תהלים קמח, א."],["4090","400","<b>הללוהו כל מלאכיו</b>: תהלים שם, ב."],["4091","401","<b>שמש וירח והמים אשר מעל השמים</b>: תהלים שם, ג. ד."],["4092","402","<b>יהללו את שם הוי'</b>: תהלים קמח, יג."],["4093","403","<b>הללו את הוי' כל גוים</b>: תהלים קיז, א."],["4094","404","<b>ויבואו בני האלקי'</b>: איוב א, ו. ב, א. ראה גם לעיל פ' יתרו רנב, ד. וש\"נ."],["4095","405","<b>השמים מספרים</b>: תהלים יט, ב."],["4096","406","<b>הללו את הוי'. . עץ פרי</b>: תהלים קמח, ז. ט."],["4097","407","<b>ע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["4098","408","<b>אין מקרא יוצא מידי פשוטו</b>: שבת סג, א."]]],[2300550693,"מרחוק מקבלים גם הם מהוד זה לפרקים (כמו בשבת ויו\"ט שיש עליות לכל המלאכים ועולמות כמו הבו להוי'<sup data-n=\"4099\">409</sup> כו'). ומ\"ש הודו על ארץ תחלה לשמים משום דסוף מעשה דארץ עבמ\"ת<sup data-n=\"4100\">410</sup> לשמים וכידוע בטעם שא' ביום עשות ה' אלקי' ארץ ושמים כמ\"ד דארץ קדמה לשמים<sup data-n=\"4101\">411</sup> לכך הודו דשם הוי' על ארץ תחלה כו' וד\"ל (אבל ברישא שא' יהללו מלמטה למעלת<sup data-n=\"4102\">*412</sup> שמים תחלה לארץ כמ\"ש בראשית ברא השמים<sup data-n=\"4103\">412</sup> כו' וכמ\"ש כי הוא צוה ונבראו בשם אלקים ממילא כמו שאמר והי' העולם אבל בארץ אמר כי נשגב שמו לבדו כו'). ואמנם מובן עכ\"פ שבחי' הודו של שם הוי' אע\"פ שאינו אלא הוד וזיו לבד מ\"מ אינו כהוד וזיו השמש המאיר לארץ שמתייחס למאור אלא רק גילוי הוד שם מל' לבד כו', וגם זה הוא בחי' מקיף מרחוק כנ\"ל. וא\"א לומר שמהוד זה יהי' אף מקור לחיות הנבראים וכ\"ש שיחי' אותם ממש מאין ליש כ\"א הודו על ארץ כו' ובדרך העלם והסתר מהוד זה דשם הוי' באלקי' נמשך בצירופי' ושמות להיות מקור לחיותם כנ\"ל.\n<b>אך</b> הנה לע\"ל כתיב ונגלה כבוד הוי' דוקא וראו כ\"ב כי פי ה' דיבר בי\"מ דשם אלקי' דמע\"ב כו', והענין הוא שיתגלה עצם דשם הוי' דאצי' כמו שהוא שנק' עכשיו בחי' מקיף וסוכ\"ע בכלל ורק בחי' הודו על ארץ כו', אבל לע\"ל כבוד הוי' זה יתגלה מן העלמו בשם אלקי' שלא יסתיר לו כלל כמא' שיוציא חמה מנרתקה שהוא שם הוי' משם אלקי' וראו כ\"ב כו', והוא מה שיהי' שם הוי' עצמו בבחי' אלקי' שיהי' ממנו מקור חיות כל בריאה ובריא' כמו משם אלקי' בצירופי אותיות דמל' דאצי' עד מל' דעשי' כו', וזהו הטעם שיראו כ\"ב כי פי הוי' דאצי' דיבר בבחי' אותיות הדיבור דוקא שבא בבחי' אור וחיות ממש (וזהו שא' יעקב והי' הוי' לי לאלקי\"ם ממש (כמשי\"ת). כי הנה לע\"ל אמר הסתיו עבר הגשם חלף והלך לו<sup data-n=\"4104\">413</sup> הנצנים נראו בארץ<sup data-n=\"4105\">414</sup> כו' ע\"כ קומי לך רעייתי<sup data-n=\"4106\">415</sup> כו', פי' בא לרמז על בחי' הסתר וצמצום דשם אלקי' עכשיו שהוא בחי' <span data-k=\"pg\">תפב</span> ּ שם ב\"ן שמתלבש בריבוי הצמצומים עד בחי' נוגה דעשי' (כמ\"ש כמראה הקשת ביום הענן<sup data-n=\"4107\">416</sup> שהוא יום הגשם כן מרא\"ה הנוג\"ה כו' שהענן מסתיר על השמש ע\"כ מתגלי' ג' גווני' דשמש<sup data-n=\"4108\">417</sup> בענן בשינוי המהות לגמרי כן מראה הנוגה<sup data-n=\"4109\">418</sup> שנק' חשמ\"ל שמסתיר לשם הוי' וזהו הוא מראה דמות כבוד הוי' בלבוש דשם אלקים כנ\"ל) (וכמ\"ש הסבא דזרענא פולין לנ\"ב גוונין<sup data-n=\"4110\">419</sup> שהוא שם ב\"ן ביומא",[["4099","409","<b>הבו להוי'</b>: תהלים כט, א-ב. ראה פע\"ח (שער השבת) שי\"ח, פ\"ב. פ\"ו. פ\"ח. מאמרי אדה\"א בראשית ע' מו. וש\"נ."],["4100","410","<b>דסוף מעשה. . עבמ\"ת</b>: ע\"פ פיוט לכה דודי."],["4101","411","<b>דארץ קדמה לשמים</b>: חגיגה יב, א."],["4102","*412","<b>למעלת</b>: כ\"ה בגוכתי\"ק."],["4103","412","<b>בראשית ברא השמים</b>: בראשית א, א [בדילוג]."],["4104","413","<b>הסתיו עבר הגשם חלף והלך לו</b>: שה\"ש ב, יא."],["4105","414","<b>הנצנים נראו בארץ</b>: שם, ב, יב."],["4106","415","<b>קומי לך רעיתי</b>: שה\"ש שם, יג. י."],["4107","416","<b>כמראה הקשת ביום הענן</b>: יחזקאל א, כח [ושם: כמראה הקשת אשר יהי' בענן]."],["4108","417","<b>הקשת. . ג' גווני' דשמש</b>: ראה זהר (ס\"ת) וירא צח, ב. ש\"א מד, א הערה 16."],["4109","418","<b>הקשת. . כן מראה הנוגה</b>: ראה גם ביאוה\"ז פקודי נז, ג. שע\"ת טז, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תנד. וש\"נ. דברים ח\"ב ע' תכא."],["4110","419","<b>דזרענא פולין לנ\"ב גוונין</b>: ראה זהר (סבא) משפטים צז, סע\"ב. מאמרי אדה\"ז הקצרים ע' שפד."]]],[2300550697,"דעיבא בחור\"ף שהגשמים בעבים ונק' גשם ע\"ש הגשמה שהוא הסתר דעבי\"ם לשמש והוא מ\"ש ז\"ל בבניהו שהכה הארי בתוך הבור<sup data-n=\"4111\">420</sup> ביום השלג שלמד תו\"כ ביומא דסיתוא כו' שהוא חסדי' דשם הוי' דדכורא (דבניה\"ו על הל' גיבורי' דדוד<sup data-n=\"4112\">421</sup> שיעזרו בלא ל\"ב ול\"ב כנ\"ל) בן יה\"ו<sup data-n=\"4113\">422</sup> דז\"א<sup data-n=\"4114\">423</sup> שממתיק לגבורות דשם ב\"ן כמו בקרבנות ביום השלג דוקא כו').\n<b>וזהו</b> שמרמז לע\"ל דוקא בימות המשיח ועוה\"ב שהסתיו עבר שהוא צמצום דשם ב\"ן בחי' אלקי' שיהי' התגלות החסדי' דשם הוי' בלי העלם ולבוש דשם אלקים וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"4115\">424</sup> כו', ואז הגשם חלף והלך לו שהוא בחי' ההגשמה שמגשם בלבוש שק דנוגה להסתיר לכח האלקי בנבראי' וחלף והלך לו (כמו הגשמי' שבעבים שאז לא נראה הארת אור השמש וכגשם שמרוה לארץ ומצמיח בשינוי מהות כו'), ולכך אז יראו כ\"ב גם בשכל האנושי הטבעי כי פי הוי' עצמו דיבר בי\"מ דשם אלקים. והיינו מה שיהי' אור דשם הוי' דבחי' סובב דעכשיו בבחי' כח הפועל האלקי בנפעל ממש ולא כאותיות וצירופי' דשם אלקי' עכשיו שמסתירי' ומעלימי' לאור דשם הוי' שהוא עיקר ומקור דכח הפועל בנפעל ורק הוד וזיו דשם הוי' מרחוק מאיר עליהם בתמידות כמ\"ש הודו על ארץ כו', אבל לע\"ל שיוציא חמה מנרתקה הרי גופו של מאור שהוא שם הוי' יתגלה בדיבור ונק' פי הוי' ממש (כמו אותיות ודיבור דדבר הוי' שבתו\"מ (כמשי\"ת) כדיבור די\"מ עכשיו להוות כל בריאה מאין ליש כנ\"ל. ולכך אמר וראו כ\"ב דאפי' בהמות וחיות יכירו את בוראם ויבין כל יצור<sup data-n=\"4116\">425</sup> כו' כבהמות בהררי אלף<sup data-n=\"4117\">426</sup> שהי' קודם חטא עה\"ד כנ\"ל, וגם האדם יוסר ממנו ההגשמה דעיני בשר בראי' דשכל האנושי שעכשיו אינו רואה ומשיג רק בחי' ההגשמה המסתיר על כח ואור האלקי המחי' ומהווה לכל בריאה רק מרחוק בלבד נודע ומושג בהעלם דמקיף מהודו דשם הוי' כו'. אבל לע\"ל יהי' בחי' ראי' השכלי' באדם כמו ראי' חושיית ממש להכיר ולראות בחוש בכח ואור האלקי המהווה לכל בריאה מרוחניו' לגשמיות מאין ממש ליש שהוא משם הוי' דוקא כמ\"ש כי פי הוי' דיבר, להיות שיהי' שם הוי' עצמו בבחי' כח הפועל בנפעל בלי העלם ולבוש מסתיר כלל (כמו שהי' בגילוי דשם הוי' עצמו באבות ונביאים כמ\"ש והי' הוי' עצמו לי לאלקים ממש וכמו גם עכשיו שאו' הוי' אלקינו ממש ע\"י תו\"מ (כמשי\"ת). ע\"כ ממילא חלף הגשם והלך לו שהוא הסתר החשך הגשמי",[["4111","420","<b>שהכה הארי בתוך הבור</b>: ראה שמו\"ב כג, כ. ברכות יח, סע\"ב ואילך."],["4112","421","<b>דבניה\"ו על הל' גיבורי' דדוד</b>: ראה דהי\"א כז, ה. ו וברד\"ק ובמצודות דוד שם. מאמרי אדה\"ז על מארז\"ל ע' ריג. סה\"מ תרכ\"ח ע' סה."],["4113","422","<b>דבניה\"ו. . בן יה\"ו</b>: ראה לקו\"ת להאריז\"ל שמו\"ב פכ\"ג. ח\"ש עה\"פ ו(הנה) רבקה יוצאת (כד, טו). שער רוח הקדש סוף תיקון כ."],["4114","423","<b>יה\"ו דז\"א</b>: ראה לקו\"ת להאריז\"ל שמו\"א פי\"ח."],["4115","424","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["4116","425","<b>ויבין כל יצור</b>: תפלת העמידה לר\"ה."],["4117","426","<b>כבהמות בהררי אלף</b>: תהלים נ, י. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'נט. וש\"נ. בראשית ע' צו. וש\"נ. שע\"ת ח, א."]]],[2300550701,"שמחשיך ומעלים על האדם וכל בריאה מצד חטא עה\"ד דנמשך זוהמא של נחה\"ק<sup data-n=\"4118\">427</sup> ואחשיך אנפי בריין<sup data-n=\"4119\">428</sup> כו', ויראו כ\"ב לכח האלקי שבכל הברואי' בהכרה עצמי' וחושיי' דוקא כמ\"ש <span data-k=\"pg\">966</span> ּ וידע כל פעול כי אתה פעלתו כו' ולא כידיעה דעכשיו אף בנשמות צדיקי' שאינו אלא בהשגה מרחוק (שנק' השגת המציאות ולא השגת המהות וגם בנביאים (לבד משה ואבות<sup data-n=\"4120\">429</sup> ) א' הן במראה אליו<sup data-n=\"4121\">430</sup> כו' וד\"ל).\n<b>וזהו</b> ובאו במערות צורים מפני פחד ה' דבחי' פחד זה אינו אלא מצד עוצם הקירוב<sup data-n=\"4122\">431</sup> והוא ההתגלות דכבוד הוי' עצמו בנבראי' וכמ\"ש ומלאה הארץ דעה את הוי'<sup data-n=\"4123\">432</sup> ממש בידיעה והכרה ממש ולא בהשגת השכל, כי גם בהמות וחיות יהי' בהן ביטול המציאות מאלקות כחמורו של רפב\"י שא' אנו כחמורים כו' וכמ\"ש וגר זאב עם כבש<sup data-n=\"4124\">433</sup> כו' וארי' כבקר<sup data-n=\"4125\">434</sup> כו', לפי שיזדכך הרע דק\"נ וכל בחי' החומריות דעוה\"ז דעכשיו בלי העלם דלבוש שק דנוגה ולכך גם הטבע הגשמי' יזדכך בכל חלקי דצח\"מ (כדצח\"מ שבג\"ע דעשי' וכה\"ג כמ\"ש כגן ה'<sup data-n=\"4126\">435</sup> כו'). ולכך יבאו במערות צורים להחבא מפני פחד הוי' (כמו קודם החטא שדבר ה' גם עם הנחש<sup data-n=\"4127\">436</sup> וקול הוי' מתהלך בגן<sup data-n=\"4128\">437</sup> כו'), וכמו בר\"ה שאו' ושמך נור\"א<sup data-n=\"4129\">438</sup> על כל מה שבראת שייראוך כל המעשים כו' ולא כעכשיו דגם שנק' אדון על כל המעשים מרחוק מאיר עליהם כנ\"ל. וזהו כמו ההפרש כשהשמש מאיר בארץ בקיץ שהנצני' נראו כו', משא\"כ בחורף שנק' סתי\"ו שחושך יכסה ארץ וז\"ש כי הסתיו עב\"ר כו' וד\"ל.",[["4118","427","<b>חטא עה\"ד. . זוהמא של נחה\"ק</b>: ראה שבת קמו, רע\"א."],["4119","428","<b>ואחשיך אנפי בריין</b>: ראה זהר ח\"ש קלא, סע\"א."],["4120","429","<b>לבד. . ואבות</b>: ראה זהר וארא כג, ב ובמק\"מ שם. לקלו\"י לתניא ע' מח (קכז, ב). הערות לזהר וארא ע' נו."],["4121","430","<b>הן במראה אליו</b>: בהעלותך יב, ו [בהוספת תיבת: הן — ראה גם לעיל פ' בשלח קמד, א]."],["4122","431","<b>פחד. . מצד עוצם הקירוב</b>: ראה שה\"א מה, ב ובהערה 24. מאמרי אדה\"א נ\"ך ע' צ. וש\"נ."],["4123","432","<b>ומלאה הארץ דעה את הוי'</b>: ישעי' יא, ט [ושם: כי מלאה — נסמן לעיל פ' בשלח קס, ד]."],["4124","433","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."],["4125","434","<b>וארי' כבקר</b>: ישעי' יא, ז. סה, כה."],["4126","435","<b>כגן ה'</b>: לך יג, י."],["4127","436","<b>שדבר ה' גם עם הנחש</b>: בראשית ג, יד. טו."],["4128","437","<b>וקול הוי' מתהלך בגן</b>: בראשית שם, ח."],["4129","438","<b>ושמך נור\"א</b>: תפלת העמידה לימים נוראים."]]],[2300550057,"<b>ולהבין</b> זה בתוס' ביאור, הנה מבואר למעלה שלע\"ל נאמר ולילה כיום יאיר שלא יהי' הפרש כלל בין צמצום דחשך דלילה ובין אור דיום, כי גם בחי' הצמצום דשם אלקים שמסתיר עכשיו לשם הוי' לע\"ל יאיר גם הוא כאור הוי' ממש וכמו והי' הלבנה כאור החמה<sup data-n=\"4130\">439</sup> כו' וזהו ושמתי כדכ\"ד שמשותיך כו' (ולא שיצטרך להסיר חמה מנרתקה שזהו שם אלקים אלא גם שם אלקי' יאיר כשמש דהוי' עצמו). והיינו כי הוי' הוא האלקים כולא חד<sup data-n=\"4131\">440</sup> ממש, וזהו בחי' ד\"ת דאלקי' מאין ליש יהי' שוה לד\"ע דהוי' מי\"ש לאין כנ\"ל, דזהו ענין מה שבמקום גדולתו שם אתה כו' דגדולה וענוה כא' ממש שאין צמצום דבחי' ענוה כמו שהוא בבי\"ע נפרד כלל מבחי' הגדולה דשם הוי' דאצי' כו' כנ\"ל. והיינו ג\"כ ענין דהתגלות דשם הוי' לע\"ל בבחי' אותיות הדבור כמ\"ש ונגלה כו' כי פי הוי' דבר ולא יסתירו",[["4130","439","<b>והי' הלבנה כאור החמה</b>: ישעי' ל, כו [בדילוג]."],["4131","440","<b>כי הוי' הוא האלקים כולא חד</b>: נסמן לעיל פ' יתרו רנח, ג."]]],[2300550089,"האותיות כלל וכלל כנ\"ל. ולכך יבואו כל הברואי' והאדם במערות צורים מפני פחד הוי' כו' וכנ\"ל במ\"ש כי הסתיו עבר כו' שאין חושך והסתר כלל בארץ, לפי שאור הוי' עצמו יאיר בגילוי דרך אותיות בלי העלם ולבוש כלל כמו שהי' כבר לעולמים קודם חטא עה\"ד וכנ\"ל. וכך יהי' ג\"כ אחר הבירור דעה\"ד טו\"ר שיעובר רוח הטומאה לגמרי מכל חלקי דצח\"מ ויזדככו הגופים בתכלית עד שיראו כ\"ב ממש בראי' חושי' בלי העלם כלל כנ\"ל, והוא מה שיכירו בהכרה עצמי' בשם הוי' כמו שהוא בבחי' ד\"ע מיש האמיתי לאי\"ן ולא כמו שעכשיו מתצמצם בשם אלקים בבחי' ד\"ת מאין ליש שבחי' האי\"ן האלקי מוסתר ונעלם כמו אתה אל מסתת\"ר<sup data-n=\"4132\">441</sup> כו' (וכמו אברהם שקרא בשם הוי' מן <span data-k=\"pg\">תפג</span> ּ ההעלם לגילוי גמור כמו שיהי' לע\"ל ממש כמ\"ש ויקרא אברם בשם הוי' אל עולם<sup data-n=\"4133\">442</sup> כו', ולכך הי' נק' נשיא אלקים כו' ונק' אב המון גוים<sup data-n=\"4134\">443</sup> כו' ורדף לד' מלכים כמ\"ש בזוהר עמ\"ש ויחלק עליהם ליל\"ה<sup data-n=\"4135\">444</sup> ליל ה\"א שזהו מה שלילה כיום יאיר בבירור החשמ\"ל דנוגה שמחושך יהי' אור, והוא מה שהפריד בעצמו הרע מן הטוב בתכלית הקצה האחרון כמו שיהי' לע\"ל בהזדככות העולם כו') (וכליל שמורים דמצרים שנגלה עליהם כו' שהאיר גם לחושך דנש\"ט דמצרים). ולכך יהי' פחד הוי' על כל הברואי' לע\"ל בביטול תמידי ועצמיות כמו מלאכים דמרכבה ויותר מהם, וראי' מפרות שנשאו הארון כנ\"ל. וגם ע\"ש דנוגה נאמר אז אהפוך<sup data-n=\"4136\">445</sup> כו' שיהי' גילוי דשם הוי' על הכל ויבין כל יצור כו' מטעם הנ\"ל שיזדככו כל הגופים מצד תגבורת גילוי אור אלקי בארץ (כמו שהי' בג\"ע דעשי' קודם שחטא בעה\"ד כנ\"ל).\n<b>אך</b> הנה עדיין יש להבין מהיכן יוכל להיות בחי' הזדככות החומר כ\"כ באדם וגם בבהמה עד שיוכלו להכיר לבורא העליון כמו בראי' מקרוב ממש כנ\"ל. והנה אנו מוצאים גם עכשיו שיש מעין זה בנשמות ישראל שבגופי' גשמי' (שגם שמעורבים טו\"ר אינם מסתירים כ\"ש וק\"ו לע\"ל שיהי' הזדככות החומר בתכלית כנ\"ל) בבחי' ראי' מקרוב לאלקו' כראי' חושי' ממש, והיינו כמו בבחי' ראית עין השכל דחכ' שבמוח כמו שהוא בלב דוקא כמו ולבי ראה הרבה חכמה ודעת<sup data-n=\"4137\">446</sup> כו' שנק' עומק חכ' שבלב שהוא יותר אמת מראי' השכל וחכ' שבמוח החכ' עצמה כמ\"ש במ\"א בענין מ\"ש בר\"מ דבעין השכל שבלבא דוקא חזי כולא<sup data-n=\"4138\">447</sup> כו'. והנה בחי' ראי' דחכ' שבמוח אינו רק מה שרואה בעין השכל להתהוות הבריאה מכח האלקי מאי\"ן ליש שע\"ז א' איזהו חכם הרואה את הנולד<sup data-n=\"4139\">448</sup> הנולד מאין ליש, כמו",[["4132","441","<b>אתה אל מסתת\"ר</b>: ישעי' מה, טו."],["4133","442","<b>ויקרא אברם. . עולם</b>: נסמן לעיל פ' יתרו רנט, ב."],["4134","443","<b>אב המון גוים</b>: לך יז, ה."],["4135","444","<b>ויחלק עליהם ליל\"ה</b>: לך יד, טו. ראה לעיל פ' בא קכה, ב. וש\"נ. פח, ג. וש\"נ."],["4136","445","<b>אז אהפוך</b>: צפני' ג, ט."],["4137","446","<b>ולבי ראה הרבה חכמה ודעת</b>: קהלת א, טז. ראה גם עט\"ר שער ר\"ה ע' 40. מאמרי אדה\"א שמות ח\"ב ע' תנז."],["4138","447","<b>דבעין השכל שבלבא. . חזי כולא</b>: ראה זהר (רע\"מ) משפטים קטז, ב."],["4139","448","<b>איזהו חכם הרואה את הנולד</b>: תמיד לב, א. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310048\" data-slug=\"tanya\" data-id=\"3401310048\">תניא</a> פמ\"ג. מאמרי אדה\"א דברים ח\"א ע' רכא. וש\"נ שע\"ת עא, ג ובהערה 23."]]],[2300550121,"החכם שרואה בכח שכלו גם במה שעתיד להיות נולד אע\"פ שנעלם מן ההשגה האנושי' בבינה ודעת מ\"מ יראה בעין כח השכל דחכ' שלמעלה מן ההשגה דבינה, שהחכ' נק' אין ג\"כ ובינה נק' יש<sup data-n=\"4140\">449</sup> כידוע. וכמו שרואי' לאור השמש או לאור הנר גם מרחוק, או כמו שהעין יכול לראות גם מרחוק שרואה עצם ומהות הדבר הנעלם מן השגה שאינה רק כמו השמיעה שהיא מרחוק<sup data-n=\"4141\">450</sup> בלבד כידוע שמטעם זה אינו דומה שמיעה לראי'<sup data-n=\"4142\">451</sup>. והנה כמו\"כ אור החכ' שמבריק בעין השכל האלקי דכח מ\"ה דחכ' דנה\"א ליראה את הנולד מאין ליש יראה ג\"כ באי\"ן של היש דנבראים כמו שהוא אף שהוא נעלם<sup data-n=\"4143\">452</sup> מן ההשגה והבנה בבינה, וכמו ראי' מקרוב בעין הגשמי או בחכם שרואה את העתיד כו' שאין זה רק מחמת שטבע האור לגלות העלם שלא יוסתר ממנו, כך אור הראי' דחכ' בעין השכל ולכך נק' חכמים עיני העדה<sup data-n=\"4144\">453</sup> דוקא כידוע.\n<b>אך</b> זהו דוקא בעין השכל שבלב דוקא כמו ולבי ראה הרבה חכמה כו', לפי שבראי' עין השכל שבמוח החכ' מתעלם אורו בהשגה דמוח דבינה שאינו אמת כ\"כ (שהחכ' נק' אמ\"ת<sup data-n=\"4145\">454</sup> לפי שרואה בחכ' אמיתי' הדבר כמו שהוא בלי העלם ולבוש, משא\"כ בהשגה דבינה שהוא משיג הדבר בשכל שהוא עצמו מסתיר לבחי' עצם הדבר כו' בשמיעה מרחוק כנ\"ל), משא\"כ <span data-k=\"pg\">968</span> ּ ביציאת אור החכמה משכל והשגה דבינה בבואו בהבל הלב דוקא (ששם מסתיים יסוד אבא שארוך מיסוד אימא<sup data-n=\"4146\">455</sup> כמו יוסף שנק' יתום מאמו ולא מאביו<sup data-n=\"4147\">456</sup> שהוא יסוד אבא בבחי' יסוד ז\"א כמ\"ש במ\"א), והוא נקודת הלב שיראה גם הוא ראי' עין החכ' בראי' המהות בראי' מקרוב הרבה יותר מראי' עין החכ' שבמוח החכ' שהרי נק' ראי' הלב, שהלב רואה ראי' השכל בשם עומק החכ'. והוא מה שירגיש בלב כמו בשיר וניגון בבחי' ראי' השכל דאי\"ן דחכמה כמו שהוא מאי\"ן ממש כו' בלי העלם ולבוש דהשגה מבינה עד שא\"א לו להביא בהסבר וטעם לזולתו כלל שז\"ש ולבי ראה הרבה חכ' שהוא אמיתית יותר ממה שלמד החכ' בכח החכ' שמאי\"ן ליש תמצא בהברקה במוח החכ' לבינה כו' וד\"ל (וכמו שא' אסתכלנא ברזא דחכ'<sup data-n=\"4148\">458</sup> הסתכלות זו בלב כמו שא' לר\"ח נושא עון חמית<sup data-n=\"4149\">457</sup> כו' (וכמ\"ש במ\"א בדמיון",[["4140","449","<b>שהחכ'. . אין. . ובינה נק' יש</b>: ראה מאמרי אדה\"א בראשית ע' א ואילך. וש\"נ."],["4141","450","<b>השמיעה שהיא מרחוק</b>: ראה גם מאמרי אדה\"א בראשית ע' תקג וע' תקיד. הנחות תקע\"ז ע' כז וע' רלח."],["4142","451","<b>אינו דומה שמיעה לראי'</b>: נסמן לעיל פ' משפטים רפט, ג."],["4143","452","<b>נעלם</b>: אולי כתוב בגוכי\"ק: נעלה."],["4144","453","<b>נק' חכמים עיני העדה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן במ\"מ לשם. לעיל פ' בא קב, א. וש\"נ."],["4145","454","<b>שהחכ' נק' אמ\"ת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל\"ה</a> בהג\"ה. מאמרי אדה\"א שמות ח\"ב ע' תלז. וש\"נ."],["4146","455","<b>יסוד אבא שארוך מיסוד אימא</b>: ראה ע\"ח שער הכללים פ\"י. סידור שחרית לשבת קפז, ד. פיה\"מ מג, ב. ג. מאמרי אדה\"א נ\"ך ע' קיח ואילך. וש\"נ."],["4147","456","<b>יוסף שנק' יתום מאמו ולא מאביו</b>: ראה ע\"ח (שער הצלם) שכ\"ו, פ\"ג. מאמרי אדה\"א בראשית ע' רצד ואילך. ש\"א ו, א ובהערה 6."],["4148","458","<b>אסתכלנא ברזא דחכ'</b>: כ\"ה בכ\"מ. ראה הנסמן לעיל פ' בא קב, ד."],["4149","457","<b>אסתכלנא. . חמית</b>: ראה זהר (אד\"ר) נשא קלב, ב."]]],[2300550153,"לזה<sup data-n=\"4150\">459</sup> ממה שמבואר בשבחי האריז\"ל<sup data-n=\"4151\">460</sup> שהי' משיג סודות התורה בשעה א' שמנמנם כו' וד\"ל). וכמו\"כ יש בחי' עומק בינה בלב כמו ותן בלבינו בינה<sup data-n=\"4152\">461</sup> בלבינו דוקא, אך זהו בחי' השגת השכל בטוב טעם שנקלט תמציתו ורוחניות שלו בעומקו של מושג בלב דוקא שהלב שומע והלב רואה<sup data-n=\"4153\">462</sup> כו' וכמו שמע ישראל<sup data-n=\"4154\">463</sup> בשמיעה דבינה בלב לעומק המושג. אך זהו רק תמצית השגה ואינו דומה גם הוא לראי' דחכ' שהלב רואה ראיי' השכל שלמעלה מן ההשגה לגמרי כמו מ\"ה פשפש\"ת<sup data-n=\"4155\">464</sup> כו' וכמ\"ש במ\"א וד\"ל). וזהו כמ\"ש עיניך יונים<sup data-n=\"4156\">465</sup> עיניו כיונים<sup data-n=\"4157\">466</sup> שמסתכלי'<sup data-n=\"4158\">467</sup> בעונג נפלא זע\"ז כו' והוא ענין לאסתכלא ביקרא דמלכא<sup data-n=\"4159\">468</sup> כמ\"ש לחזות בנועם ה'<sup data-n=\"4160\">469</sup> כו' דראי' והסתכלות זו הוא בבחי' עונג נפלא שבפנימי' החכ' שהיא בבחי' ראי' מקרוב וזהו כמו יראה כל זכורך<sup data-n=\"4161\">470</sup> כו' כשם שבא לראות<sup data-n=\"4162\">471</sup> כו' כידוע.\n<b>ודוגמא</b> זאת יש בכל שבת בצלותא דמ\"ש שאז תתענג על הוי'<sup data-n=\"4163\">472</sup> בעונג אלקי עצמי שבפנימי' הלב שלמעלה מן ההשגה והתבוננו' רק בעונג פשוט והוא שנק' שיר אל כנ\"ל שהוא כולל רו\"ש בעלי' וירידה כא' ממש כנ\"ל, שזהו הטעם דגם שבת כלול מלילה ויום כא' כמו לע\"ל שלילה כיום יאיר כו' בלי הפרש כלל, וכן רו\"ש דשעשועי' דתוה\"ק כו'. והוא לפי שבכל שבת יש מעין עוה\"ב שכולו שבת יום שכולו טוב<sup data-n=\"4164\">473</sup> ונק' יום הגדול<sup data-n=\"4165\">474</sup> שכלול מערב ובוקר כו', וזהו לפי שיסבול ב' דעות ד\"ע וד\"ת כא' ממש בלי הפרש כלל כנ\"ל. וכמו עכשיו שיש הפרש בין תפלת החול לתפלת השבת, שגם שיש בחי' ראי' עין השכל בלב גם בתפלה דחול וכמו בק\"ש שאו' שמ\"ע ישראל זהו מלמטה למעלה בתחלה בשמיעה דהשגה דבינה ליבא ואח\"כ בביטול דהשגה יש לאין או' הוי' אלקינו ממש בבחי' ד\"ע דיחו\"ע שלמעלה מן ההשגה. אבל בתפלה דשבת שנמשך עונג העצמו' בנשמות מלמעלה למטה באו\"י כמו שהוא למעלה ממש כך הוא למטה כמו שיהי' לע\"ל, ע\"כ בחי' ראי' השכל שבלב הוא בעונג נפלא בבחי' שיר וניגון כמו דר\"מ הי' מנגן בכל מיני ניגון ברו\"ש כא' כו' שאין בזה יגיע' ועבודה כלל כמ\"ש במ\"א שז\"ש ולא ראה עמל בישראל<sup data-n=\"4166\">475</sup> שיר אל<sup data-n=\"4167\">476</sup> דשבת כו' וד\"ל. וכמו רשב\"י שא' בחד קטירא<sup data-n=\"4168\">477</sup> כו' שא\"צ לבא לבחי' ביטול <span data-k=\"pg\">תפד</span> ּ היש",[["4150","459","<b>וכמ\"ש במ\"א בדמיון לזה</b>: ראה שער האמונה צג, א."],["4151","460","<b>בשבחי האריז\"ל</b>: כ\"ה גם לעיל פ' בא קג, א. וש\"נ."],["4152","461","<b>ותן בלבינו בינה</b>: ברכת ק\"ש שחרית. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תנז."],["4153","462","<b>שהלב שומע והלב רואה</b>: קה\"ר פ\"א, טז."],["4154","463","<b>שמע ישראל</b>: ואתחנן ו, ד."],["4155","464","<b>מ\"ה פשפש\"ת</b>: זהר בהקדמה א, ב."],["4156","465","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["4157","466","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["4158","467","<b>כיונים שמסתכלי'</b>: ראה מאמרי אדה\"ז תקס\"ט ע' ה. תו\"ח ח\"ש קלב, סע\"א ואילך. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תקפז."],["4159","468","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."],["4160","469","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["4161","470","<b>יראה כל זכורך</b>: תשא לד, כג."],["4162","471","<b>כשם שבא לראות</b>: חגיגה ב, א."],["4163","472","<b>בצלותא דמ\"ש שאז תתענג על הוי'</b>: נסמן לעיל פ' תרומה שו, א."],["4164","473","<b>עוה\"ב. . יום שכולו טוב</b>: נוסח הרחמן שבברכת המזון ליו\"ט."],["4165","474","<b>יום הגדול</b>: לשון הכתוב מלאכי ג, כג [בדילוג השם]."],["4166","475","<b>ולא ראה עמל בישראל</b>: ראה מאמרי אדה\"ז תקס\"ד ס\"ע קעח ואילך. הנסמן במאמרי אדה\"א שמות ח\"א ע' קצב."],["4167","476","<b>בישראל שיר אל</b>: ת\"ז בהקדמה (ג, סע\"א). ראה לעיל פ' בשלח רמד, א ואילך. וש\"נ."],["4168","477","<b>רשב\"י שאמר בחד קטירא</b>: נסמן לעיל פ' משפטים רפט, ב הערה 131."]]],[2300550185,"לאין בהשגה אלא בי' אחידא כו' בבחי' עצמי' דרו\"ש כא' ממש. וכמו\"כ כל הנשמה תהלל י\"ה<sup data-n=\"4169\">478</sup> כמו בה' תתהלל נפשי<sup data-n=\"4170\">479</sup> כו' בשבת עכשיו, כך יהי' יותר מזה לע\"ל בראי' והסתכלות דעונג העצמות שבפנימי' החכמה כמו לחזות בנועם ה' דקאי לע\"ל כמ\"ש ויהי נועם ה' אלקינו עלינו<sup data-n=\"4171\">480</sup> כו' שזהו בחי' פנימי' ע\"י שנחשב מעצמו' דא\"ס כמו שהוא בלי העלם כלל כנ\"ל וד\"ל.\n<b>ואע\"פ</b> שגם עתה יש בחי' ראי' במהו\"ע אלקו' כמ\"ש מבשרי אחזה אלוה אחזה ממש זהו בחי' חיצוני' הראי' שנק' חזיון, כמו בראיה שבלב שרואה אדם בחיי נפשו אע\"פ שאינו רואה המהות דנפש ממש מ\"מ נתאמת אצלו מציאות חיות הרוחני' דנפשו שהוא חי בעצם בהרגשה והכרה עצמי' ממש כו'. כך יהי' לע\"ל שיהי' בחי' ראי' והכרה עצמי' בכל אדם, וגם בבהמות וחיות במהו\"ע אלקות שהוא המחי' את הכל מאין ליש ממש כאלו רואי' בעיני בשר ממש כמו שמכירים ורואים בחיי נפשם ממש כן יהי' ראי' אלקות בכח הפועל שלהם תמיד. אך זהו בבחי' חיצוני' כטבעי' חיות הנפש בכל בע\"ח, והרי גם לע\"ל ודאי יהי' הפרש בין אדם לבהמה כעכשיו ואע\"פ שיתגלה כבוד הוי' וראו כ\"ב כו' מ\"מ יהי' הפרש בזה הגילוי עצמו בין אדם לבהמה, ובאדם עצמו בין פנימי' האדם לחיצוני' שבהם כמו שאו' ויאמר כל אשר נשמה באפו<sup data-n=\"4172\">481</sup> ה' אלקי ישראל מלך כו' והוא כמארז\"ל שיאמרו קדוש לפני הצדיקי'<sup data-n=\"4173\">482</sup> כמ\"ש כל הנותר בציון כו' קדוש<sup data-n=\"4174\">483</sup> יאמר לו כו'. והיינו לפי שיהי' בנשמות ישראל בחי' ראי' פנימי' ועצמי' ממש שלמעלה מהכרה זו הטבעי' שיכיר כל בשר כמו שאו' וידע כ\"פ ויבין כל יצור כו' כמו שמכיר חיי נפשו שאין זה רק חיצוני' האור האלקי המחי' הכל מאין ליש. אבל הנחמות שמדברים לע\"ל זהו בראי' פנימי' ועצמי' דנועם ה' דוקא והוא בבחי' פנימי' ועצמו' דא\"ס ממש כמו שהוא בבחי' שעשועי המלך בעצמו'<sup data-n=\"4175\">484</sup> קודם הצמצום הראשון במל' דא\"ס בקו\"ח להיות מל' כ\"ע כו', והיינו פנימי' התענוג הפשוט ועצמי' שבח\"ע ורצה\"ע שבתו\"מ שלמטה שהאיר במ\"ת בלבושי' גשמיי' דמעשה המצות בסו\"מ וע\"ט בפו\"מ כמו לא תרצח<sup data-n=\"4176\">485</sup> כו', ולע\"ל יתגלה מן ההעלם דלבושי' הללו כי יעובר רוח הטומאה כו' ולא יהי' אור דתו\"מ בבירורי' דעה\"ד טו\"ר כלל רק כמו שהן למעלה בפנימי' ועצמי' דא\"ס ב\"ה שא' רחבה מצות\"ך מאד<sup data-n=\"4177\">486</sup> כו' שזהו שכר המצות בעוה\"ב שנק' עדן כו'. ואז נאמר ולא יכנף עוד מוריך והיו עיניך רואות דמה שעכשיו מתלבש מעצמו' ופנימי' דתענוג הפשוט בתו\"מ שלמטה יתגלה ולא יכנף עוד והיו עיניך רואות באור העצמו' הזה כמ\"ש באורך נראה אור<sup data-n=\"4178\">487</sup> שזהו באורך העצמי דתו\"מ נראה אור העצמו' ממש בעוה\"ב כו'",[["4169","478","<b>כל הנשמה תהלל י\"ה</b>: תהלים קנ, ו."],["4170","479","<b>בה' תתהלל נפשי</b>: תהלים לד, ג."],["4171","480","<b>ויהי נועם ה' אלקינו עלינו</b>: תהלים צ, יז."],["4172","481","<b>ויאמר כל אשר נשמה באפו</b>: תפלת העמידה לר\"ה."],["4173","482","<b>שיאמרו קדוש לפני הצדיקי'</b>: ראה ב\"ב עה, ב."],["4174","483","<b>כל הנותר בציון כו' קדוש</b>: ישעי' ד, ג [ושם: והי' הנשאר בציון והנותר בירושלים קדוש. נסמן לעיל פ' בשלח רלד, ד]."],["4175","484","<b>שעשועי המלך בעצמו'</b>: נסמן לעיל פ' תרומה שיח, ב."],["4176","485","<b>לא תרצח</b>: יתרו כ, יג."],["4177","486","<b>רחבה מצות\"ך מאד</b>: תהלים קיט, צו."],["4178","487","<b>באורך נראה אור</b>: תהלים לו, י."]]],[2300550217,"לפי שעמך בטל וטפל גם מקור כל החיים שהוא מקור כל התענוגי' העליונים שבע\"ס דאצי' ולמעלה עד מל' דא\"ס שבקו\"ח כו' וד\"ל.\n<b>והנה</b> הגם שאפי' בבע\"ח יהי' הכרה טבעי' באלקות בתמידו' בכל הברואים לע\"ל כמו ושמך נורא על כל כו' בהכרה בחיו' הנפש ויותר מזה, מ\"מ בחי' ראי' עין השכל בנקודת הלב בכאו\"א עכשיו בעונג עצמי בתפלה דשבת וגם כמו דחול בעומק חכ' שבלב כנ\"ל יותר עליון הרבה מצד שמלובש בזה בהעלם מעין בחי' ראי' פנימי' ועצמי' <span data-k=\"pg\">970</span> ּ דנש\"י בעצמות א\"ס ממש כמו בשבת גם עכשיו מאיר קצת מעין זה דלע\"ל וכנ\"ל בכ\"ו כל\"ח כו' וכמו בג' סעודות דשבת שאו' דא היא כו' ואין הגשמי' דמאכל שבת מגשם כ\"כ וכמ\"ש ולא פרש שבתכם<sup data-n=\"4179\">488</sup> וכמו המאכל דמן שהי' ממוצא פי הוי' ממש כמו שיהי' לע\"ל לאחר הבירורים דרפ\"ח כו' שא' והגש\"ם<sup data-n=\"4180\">489</sup> חלף והלך לו כנ\"ל וד\"ל. וכמו\"כ יש מעין ראי' ותענוג העצמי דלע\"ל בנש\"י גם עתה בכל יום במעשה המצות שיש יחוד עליון דקוב\"ה ושכינתי' שהוא הוי' ואלקי' ד\"ע וד\"ת כידוע רק שהוא בלבושים והעלמו' דמעשה המצות, ואמנם יש בזה בהעלם מעין דלע\"ל ממש שלא יכנף עוד כו' שהוא יח\"ע דהוי' ואלקי' לע\"ל שיוציא חמה כו' למהוי אחד באחד למטה כמו למעלה ממש כנ\"ל. ולכך צריך ג\"כ עכשיו לשמוח ולהתענג על ה' באה\"ר בתענוגי' באו\"י ואו\"ח ברו\"ש כנ\"ל בשמחה של מצוה דוקא, וכמ\"ש למעלה בענין עבדו את הוי' בשמח\"ה דקאי בעבודה דמצו' שביום דשמחה בצפרא כו' ויש בזה רו\"ש ג\"כ אך שמתכללי' כא' ממש, והוא במ\"ש עבדו את ה' ביראה וגילו ברעדה במקום גילה עצמה בשמחה של מצוה תהא רעדה ופחד אלקי' בפנים או שמחה בפנים ורעדה בחוץ כנ\"ל. וכמו שיהי' לע\"ל דכתי' ויספו ענוים שהן צ\"ג בתו\"מ דעכשיו בהוי' שמחה העצמי' בתענוג הפשוט דעוה\"ב כנ\"ל, ואביונ\"י אדם שהן בע\"ת בקדוש כו' שהוא מהיפוך חושך לאור שצ\"ג נעשה בע\"ת שמזה יפול היראה ופחד מקרוב ממל' דא\"ס עצמו כמו תפול עליהם<sup data-n=\"4181\">490</sup> כו' דקאי לע\"ל שנמצא ה\"ז כלול מב' הפכי' ממש דרו\"ש כא', שזה יהי' לע\"ל שא' שם נשמחה בו בשמחה ותענוג עצמי בראי' הפנימי' הנ\"ל לחזות בנועם ה' ובתוכו יש רעדה ופחד הוי' שבראי' מקרוב ממש כמ\"ש כולם ידעו אותי ממש מקטנם<sup data-n=\"4182\">491</sup> כו'. ולא כמ\"ת שגם שכל העם רואים כו' רואים את הנשמע<sup data-n=\"4183\">492</sup> כו', אבל אין זה רק באוא\"ס שבח\"ע בקול ודבור דד\"ת בהעלם ולבוש וכמ\"ש קול דברים אתם כו' ותמונה כו' זולתי קול<sup data-n=\"4184\">493</sup>, וכך גם עכשיו קול התורה שנתפס בהן כמו בהיכל ק\"ק ממש ועכ\"ז זהו בלבוש",[["4179","488","<b>ולא פרש שבתכם</b>: מלאכי ב, ג. ראה זהר יתרו פח, ב. לעיל פ' בא קכ, ג. וש\"נ."],["4180","489","<b>והגש\"ם</b>: אולי כתוב בגוכתי\"ק: הגש\"ם."],["4181","490","<b>תפול עליהם</b>: בשלח טו, טז. ראה גם לעיל פ' בשלח קנה, ב. קנח, ג."],["4182","491","<b>כולם ידעו אותי. . מקטנם</b>: ירמי' לא, לג [ושם: למקטנם — ראה הנסמן לעיל פ' שמות לח, ג]."],["4183","492","<b>שכל העם רואים. . את הנשמע</b>: יתרו כ, טו. ראה מכילתא ורש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670566\" data-slug=\"torat-chaim\" data-id=\"2300670566\">תו\"ח נח נז, ד</a> הערה 64."],["4184","493","<b>קול דברים. . זולתי קול</b>: ואתחנן ד, יב."]]],[2300550249,"דאור דתור' שא' עוטה אור כשלמה<sup data-n=\"4185\">494</sup> וכן במעשה המצות כנ\"ל. משא\"כ לע\"ל שא' ולא יכנף עוד כו' אפי' בלבושי' דאור דתורה כ\"א בראי' המהות פב\"פ כמ\"ש אל יתהלל חכם כו' כ\"א השכל וידוע אות\"י<sup data-n=\"4186\">495</sup> ממש וע\"כ כולם ידעו אותי בשוה ממש ולא ילמדו איש את רעהו<sup data-n=\"4187\">496</sup> כו' למעלה מבחי' חכ' דאדם. ומעין זה יש גם עתה בהעלם עכ\"פ במצות מעשיות שמהן דוקא יהי' שכר דעוה\"ב שעין בעין יראו<sup data-n=\"4188\">497</sup> כו' למעלה מעין בעין שהי' במ\"ת מטעם הנ\"ל (וזהו בברכו' המצות דוקא (כמשי\"ת) וד\"ל.\n<b>וזהו</b> ענין ברכת המצות, דהנה ארז\"ל ע\"פ כי טובים דודיך מיין<sup data-n=\"4189\">498</sup> עריבים עלי ד\"ס יותר מיינה של תורה<sup data-n=\"4190\">499</sup> והן ברכת המצות שהן מד\"ס<sup data-n=\"4191\">500</sup> יותר מיינה של תורה בפנימי' הסוד שבתורה דיין גימט' סוד<sup data-n=\"4192\">501</sup> שיתגלו טעמי תורה בימות המשיח<sup data-n=\"4193\">502</sup> כו'. וזהו פלא גדול דברכו' המצות דרבנן שתקנו קודם גוף מעשה המצות עובר לעשייתן<sup data-n=\"4194\">503</sup> דוקא שזהו קודם גופו של יח\"ע דקוב\"ה ושכינתי' שנעשה במצוה<sup data-n=\"4195\">504</sup> עצמה כידוע, וא\"כ למה א' דעריבים עלי ד\"ס שהן ברכות המצות יותר מפנימי' טעמי <span data-k=\"pg\">תפה</span> ּ המצות שיתגלו לע\"ל (ומ\"ש ישקני מנשיקות פיהו<sup data-n=\"4196\">505</sup> זהו ברכות המצות שמד\"ס שמחמתם יתגלו טעמי המצות כמ\"ש במ\"א). אך הענין הוא כידוע בשרש ברכת המצות שהוא בבחי' מקיף דכת\"ר שלמעלה מן החכ' דתו' (אפי' מבחי' טעם כמוס לרצה\"ע הנק' טעמי תו\"מ כו'), והוא הממשיך כח ועוז גדול בבחי' ההעלם דמקיף זה להיות גוף היחוד דהוי' ואלקי' שנק' קודב\"ה ושכינתי' במעשה המצות ולכך מברך עובר לעשייתן דוקא ואם לא ברכות המצות לא נעשה גוף היח\"ע הזה במעשה המצות כו' וד\"ל. והטעם הוא לפי שצריך להמשיך מעצמות א\"ס ב\"ה ממש שהוא מקור כל המקיפים דכתר שהוא הרצון הפשוט שבמצות שימשיך כח ועוז להיות יח\"ע דהוי' ואלקי' שיתאחדו בחי' ד\"ע וד\"ת כא' ממש כנ\"ל, והוא באמרו בברכו' המצות ברוך אתה הוי' אלקינו דוקא שענין אלקינו זהו המיוחד אלינו כמו יאר ה' פניו אליך<sup data-n=\"4197\">506</sup>, ומטעם הזה הוי' זה הוא אלקינו בלי שום הפרש כלל בין הוי' לאלקי'. ולא כמו בכל בחי' ההשתלשלו' דהוי' ואלקי' שהוא כשמש ומגן כו' דחיצוני' דשם אלקים מלביש לשם הוי' כמו הכלי המגביל את האור כו', אבל הוי' הפנימי' שיאר הוי' פניו אלינו גם שם אלקי' שבו הוא שוה לבחי' הפנימי' של הוי' בלי מסתיר ומעלים כלל לשם הוי'. ואין הפרש כלל בין הוי' לאלקי' שהחיצוני' דכלי הוא כמו הפנימי' דהוי' ממש בלי הבדל כלל בין",[["4185","494","<b>עוטה אור כשלמה</b>: תהלים קד, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תצב. וש\"נ. ש\"א לט, א ובהערה 1. לקמן פ' פקודי תנג, ג."],["4186","495","<b>אל. . השכל וידוע אות\"י</b>: ירמי' ט, כב. כג."],["4187","496","<b>ולא ילמדו איש את רעהו</b>: ירמי' לא, לג [בדילוג]."],["4188","497","<b>שעין בעין יראו</b>: ישעי' נב, ח."],["4189","498","<b>כי טובים דודיך מיין</b>: שה\"ש א, ב."],["4190","499","<b>עריבים עלי ד\"ס. . תורה</b>: ראה ע\"ז לה, א וברש\"י שם."],["4191","500","<b>ברכת המצות שהן מד\"ס</b>: ראה ברכות טו, א. לעיל פ' שמות מח, ד. וש\"נ."],["4192","501","<b>דיין גימט' סוד</b>: ראה ערובין סה, סע\"א."],["4193","502","<b>שיתגלו טעמי תורה בימות המשיח</b>: ראה רש\"י שה\"ש א, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. שער האמונה ג, ב הערה 10."],["4194","503","<b>דברכו' המצות. . עובר לעשייתן</b>: פסחים ז, ב. ראה גם מאמרי אדה\"א נ\"ך ע' שדמ. וש\"נ. וכן צ\"ל בש\"א לב, א הערה 20."],["4195","504","<b>יח\"ע דקוב\"ה ושכינתי' שנעשה במצוה</b>: ראה גם לעיל פ' וארא נא, ג. נד, ג. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תתיא ואילך."],["4196","505","<b>ישקני מנשיקות פיהו</b>: שה\"ש א, ב."],["4197","506","<b>יאר ה' פניו אליך</b>: נשא ו, כה."]]],[2300550280,"פנימי' לחיצוני', וכמו הוי' אלקיו עמו<sup data-n=\"4198\">507</sup> כו' דהוי' הוא אלקי\"ו עמו בבחי' התכללות כא' ממש, וכמו שא' יעקב והי' הוי' לי לאלקי' בלי צמצום כלל, והוא ע\"י תו\"מ דוקא ששם הוי' המלובש בשם אלקים בתורת הוי' ומצות הוי' אין חילוק והפרש כלל בין אור לכלי בין פנימי' לחיצוני' דכולו פנימי' ועצמיו' ממש ובבחי' פנימי' ועצמיו' ממש אין חילוק והפרש בין פנימי' לחיצוני' באו\"כ (וראי' לזה ממכתב אלקי' בלוחות הראשונות שמב' עבריהם כתובים<sup data-n=\"4199\">508</sup> בשוה ולא פנים ואחור מטעם זה שלוחות הראשונות הי' בבחי' פנימי' דח\"ע העצמי' שאין שם בחי' חיצוני' כלל אלא כולו פנימי' ועצמי' (וכן אותיות דתושב\"כ דתוה\"ק דס\"ר נש\"י הן מתקשראן שם<sup data-n=\"4200\">509</sup> (כמשי\"ת). וע\"כ א' מי כמוכה באלים הוי'<sup data-n=\"4201\">510</sup> שהוא בחי' ת\"ת שהוא בחי' פנימי' דשם הוי' שבתורה שנבדל מחו\"ג דאל ואלקים<sup data-n=\"4202\">511</sup> במה שהכלי שלו בשם אלקים אינו מסתיר לאור כלל מטעם הנ\"ל (כמ\"ש במ\"א).\n<b>וזהו</b> שאו' ברוך אתה ה' אלקינו דכמו שבשם הוי' למעלה בפנימי' דחכ' דתורה וגם במצות אין הכלי מסתיר לאור מטעם הנ\"ל, כך הוא בנש\"י שהן ג\"כ בפנימי' ועצמו' דשם הוי' כמ\"ש יאר ה' פניו דוקא אליך והוא בהתקשרות נשמתם באותיות התורה, דג' קשרי' הללו דישראל ואוריי' וקודב\"ה הכל אחד<sup data-n=\"4203\">512</sup> הוא שהוא הכל בפנימי' ועצמו' דוקא שהאו\"כ פנימי' וחיצוני' שוין ממש כנ\"ל. וזהו הוי' אלקיו עמו דוקא כי חלק הוי' עמו<sup data-n=\"4204\">513</sup> כו' ולכך יכולים לומר הוי' אלקינו ממש בלי הפרש כלל בין הוי' לאלקינו (וכן יעקב שא' והי' הוי' לי לאלקים זהו כשיתן לו לחם לאכול ובגד ללבוש שהוא לחם דתורה ולבוש דמצות<sup data-n=\"4205\">514</sup> כידוע), וכמו מי כהוי' אלקינו<sup data-n=\"4206\">515</sup> כו' שמיוחד פנימי' שלו אלינו. וזהו שאו' בא\"י אלקינו בברכות המצות דוקא שזהו להמשיך יח\"ע גם בהוי' ואלקי' דסובב וממלא שיהי' ג\"כ בפב\"פ בלי העלם ולבוש כלל כמו שיהי' לע\"ל כנ\"ל. וזהו אלקינו מלך העולם דהיינו שגם בחי' <span data-k=\"pg\">972</span> ּ שם אד' אדון כל הארץ שבא כמו כח הפועל בנפעל שעכשיו הוא בצמצום והסתר שהוא בחי' אלקים המצמצם לשם הוי' יהי' כמו בחי' אלקינו שמיוחד בשם הוי' בפנימי', והיינו שיהי' אלקינו דוקא מלך העולם כמו שיהי' לע\"ל דלילה כיום יאיר והלבנה תהי' כאור החמה כו' שהוא ד\"ע וד\"ת שוין ממש, וזהו לפי שהוי' אלקי' יהי' מלך העולם מפנימי' דמל' דא\"ס במל' דעשי' כו' (וכל זה לפי שקדשנו במצותיו דוקא שהן במצות העליונים שבפנימי' ועצמות התענוג הפשוט דא\"ס וציונו",[["4198","507","<b>הוי' אלקיו עמו</b>: בלק כג, כא. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670590\" data-slug=\"torat-chaim\" data-id=\"2300670590\">תו\"ח נח עו, ד</a>."],["4199","508","<b>ממכתב אלקי' בלוחות הראשונות שמב' עבריהם כתובים</b>: תשא לב, טו. טז. ראה גם לעיל פ' בשלח ריב, א. וש\"נ."],["4200","509","<b>דס\"ר נש\"י הן מתקשראן שם</b>: ראה גם לעיל פ' שמות ב, ד. וש\"נ."],["4201","510","<b>מי כמוכה באלים הוי'</b>: בשלח טו, יא. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' סג ואילך. מאמרי אדה\"א דברים ח\"ג ע' תשפד. וש\"נ."],["4202","511","<b>מחו\"ג דאל ואלקים</b>: ראה לעיל רמד, א ואילך. וש\"נ."],["4203","512","<b>דישראל ואוריי' וקודב\"ה הכל אחד</b>: ראה זהר אחרי עג, א."],["4204","513","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["4205","514","<b>לחם דתורה ולבוש דמצות</b>: ראה גם לעיל ריז, א. וש\"נ."],["4206","515","<b>מי כהוי' אלקינו</b>: ואתחנן ד, ז [בדילוג]."]]],[2300550308,"לעשות למטה יח\"ע זה בהוי' ואלקי' כו', שזהו שנעשה ע\"י ברכות המצות דוקא שהן בבחי' מקיף העליון דכת\"ר כנ\"ל וד\"ל. ושרש הענין הוא לפי שבשם הוי' דתו\"מ הוא בחי' עצמיו' רצונו ועצמיו' שכלו ומדותיו כידוע ע\"כ גם בלבושי' דשם אלקי' כמו בהתלבשות דתו\"מ למטה בדברים גשמיים אין הכלי ולבוש מסתיר כלל כמו לע\"ל כנ\"ל וד\"ל.\n<b>וזהו</b> מ\"ש אני ראשו\"ן ואני אחרו\"ן ומבלעדי אין אלקים כו' וא' בזוהר ובר\"מ בפי' ומבלעדי באמצעית'<sup data-n=\"4207\">516</sup> כו', דהנה מ\"ש אני ראשון זהו בבחי' פנימי' ועצמו' דמל' דא\"ס שנק' שעשועי המלך בעצמו ממש שנק' אני ראשון ממש ששם הוא בחי' פנימי' הח\"ע דתו\"מ שלמעלה שיתגלה מהם בעוה\"ב, וזהו ואנ\"י אחרו\"ן בעוה\"ב שנק' יום אחרון וכמו ותשחק ליום אחרון<sup data-n=\"4208\">517</sup> כו' שיתגלה מהעלם דעצמו' התענוג הפשוט כנ\"ל, ומבלעדי באמצעית' דהיינו עכשיו ובכל ו\"א שנין דהוי עלמא<sup data-n=\"4209\">518</sup> עד עוה\"ב באלף הז' אין אלקי' פי' אין בחי' אלקי' שיהי' מסתיר על שם הוי' כי הוי' הוא האלקי' ממש בלי הפרש כלל בין או\"כ כנ\"ל. ומ\"ש באמצעית' זהו דוקא מצד התלבשות דשם הוי' באלקי' עכשיו בין בההשתל' העולמות דבחי' סובב וממלא כידוע במ\"ש כי שמש ומגן כו' ובין בפנימי' דשם הוי' ואלקי' בהתלבשות בלבושים דמצות שזהו בחי' קו האמצעי דת\"ת דתורה בשם הוי' שע\"ז אמרו מי כמוך באלים הוי' כו' וכן אין קדוש כהוי'<sup data-n=\"4210\">519</sup>, שאין אלקי' מצמצם אורו כלל לפי שהכלי כמו האור מטעם הנ\"ל גם עכשיו כמו שיהי' לע\"ל ממש וד\"ל (וזהו כי ישר הוי'<sup data-n=\"4211\">520</sup> ישר יחזו<sup data-n=\"4212\">521</sup> כו' וכן ויהי בישורון<sup data-n=\"4213\">522</sup> כו' שזהו כמו קו המשקולת שהולך ביושר מראש לסוף בלי נטי' לימין ולשמאל, וזהו מצד קו האמצעי דת\"י<sup data-n=\"4214\">523</sup> שנק' אמצעיתא כידוע בענין ראש תו\"ך סו\"ף שנק' אמ\"ת<sup data-n=\"4215\">524</sup> כו' ונק' ישורון<sup data-n=\"4216\">525</sup> כו'. ועיקר האמת בסוף שהוא כמו בראש שזהו ע\"י האמצעי דקו\"ח שהולך ביושר מלמעלה למטה בלי נטיי' לצדדי' כו'. וכך הוא אמת ויושר דתורה שנק' קו הישר ונק' ספר הישר<sup data-n=\"4217\">526</sup> כו' כמו כי ישרים דרכי הוי'<sup data-n=\"4218\">527</sup> בפנימי' דשם הוי' שבחכמ' בלי נטי' לחו\"ג רק כפי קו המדה דקו\"ח שהולך ביושר מלמעלה למטה. וזהו מ\"ש אני ראשון קודם הצמצום",[["4207","516","<b>אני ראשון. . בפי' ומבלעדי באמצעית'</b>: ישעי' מד, ו. ראה ת\"ז ת\"ע (קכ, סע\"א)."],["4208","517","<b>ותשחק ליום אחרון</b>: משלי לא, כה."],["4209","518","<b>ו\"א שנין דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["4210","519","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב."],["4211","520","<b>כי ישר הוי'</b>: תהלים צב, טז."],["4212","521","<b>ישר יחזו</b>: תהלים יא, ז."],["4213","522","<b>ויהי בישורון</b>: ברכה לג, ה."],["4214","523","<b>קו האמצעי דת\"י</b>: ראה גם לעיל פ' תרומה שטז, ב. לקמן פ' ויקהל תד, ג."],["4215","524","<b>ראש תו\"ך סו\"ף שנק' אמ\"ת</b>: ראה ב\"ר פפ\"א, ב. שעה\"י קלד, א ובהערה 16."],["4216","525","<b>ונק' ישורון</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ס\"ע תשמז. וש\"נ."],["4217","526","<b>דתורה. . ונק' ספר הישר</b>: ראה לעיל פ' שמות י, ג. וש\"נ."],["4218","527","<b>כי ישרים דרכי הוי'</b>: הושע יד, י."]]],[2300550333,"דקו\"ח בתוה\"ק שקדמה לעולם הנאצל ונברא<sup data-n=\"4219\">528</sup> כו' ואנ\"י אחרו\"ן בסוף בעוה\"ב כנ\"ל, ואנ\"י אנ\"י הוא בראש כמו בסוף ואין נטי' לצד אחר כמו אני הוי' כו' בלי שינוי כלל, וזהו רק מצד הקו האמצעי שממשיך ביושר בדרכי הוי' שהוא שם הוי' דת\"ת דתור', וזהו ומבלעדי ובאמצעיתא <span data-k=\"pg\">תפו</span> ּ דוקא שכולל ראש וסוף כו' וד\"ל. וכמו\"כ גם בהשתלשלו' אני ראשון קודם הצמצום הראשון שהי' הוא ושמו בלבד שזהו בחי' מל' דא\"ס עצמו ואני זה אחרון במל' דא\"ס שיתגלה במשיח ועוה\"ב, ומבלעדי גם עכשיו מל' דא\"ס מאיר עד מל' דעשי' ואין צמצום דבחי' אלקי' שהוא בחי' כח הפועל בנפעל מסתיר לפניו כלל וכמו שאו' אתה הוא כו', וכן אני הוי' לא שניתי כו'. וראי' ממ\"ש אתה הוי' לבדיך<sup data-n=\"4220\">529</sup> כו' ממש ואת\"ה זה עשית השמים כו' טה\"ע וטה\"ת<sup data-n=\"4221\">530</sup> וארץ עלמא דאתגלייא וימים כו' ואתה זה מחי' כו' בלי שינוי כלל דאתה הוא כו' כמ\"ש ראו כי אנ\"י אני הוא<sup data-n=\"4222\">531</sup> וכמו שא' אתה הוי' אלקי' שבא בגילוי כמו בעוה\"ב אשר בחרת באבר\"ם<sup data-n=\"4223\">532</sup> כו' ונק' אברהם בה\"א אב המון גוים כו' להפוך חוש\"ך לאור כי מצאת לבבו נאמן<sup data-n=\"4224\">533</sup> בכלי כמו באור דהיינו בגופו כמו בנשמתו ממש כמו בעוה\"ב ע\"כ וכרות עמו כו' שיברר ז\"מ דתוהו ותקם את דבריך<sup data-n=\"4225\">534</sup> כו' כמ\"ש במ\"א) (וזהו ענין עו\"ז והד\"ר לבושה<sup data-n=\"4226\">535</sup> (עוז תושב\"כ והדר תושבע\"פ) ותשחק ליום אחרון עוז זה אור דתורה שא' ה' עוז לעמו יתן<sup data-n=\"4227\">536</sup> כו' והדר זה מעשה המצות שנק' לבוש הדר בבחי' לבוש מל' אשר לבש בו המלך במ\"ת<sup data-n=\"4228\">537</sup>. ואעפ\"י שהתו\"מ הן עכשיו בהעלם בלבושי' כמו לבש ה' עוז דתורה<sup data-n=\"4229\">538</sup> כו', מ\"מ לאחר הבירור השלם דתו\"מ בעוה\"ב תשחק בשחוק העליון יותר משהיתה התוה\"ק שעשועי' עצמי' ומשחקת לפניו בכל עת<sup data-n=\"4230\">539</sup> כו', שזהו משחקת בתב\"ל ארצו שהן ב' ארצות<sup data-n=\"4231\">540</sup> ארץ עילאה דעוה\"ב שנק' ארץ החיים<sup data-n=\"4232\">*541</sup> ארץ חפץ שלעולם ירשו ארץ<sup data-n=\"4233\">541</sup> וארץ תתאה כמו בג\"ע דבריאה שב\"פ גבו' גימ' רי\"ו<sup data-n=\"4234\">543</sup> עולה גימט' תבל<sup data-n=\"4235\">542</sup> שזהו אוצרות חיים דח\"ע וח\"ת דתורה כו' וד\"ל). וזהו ענין מ‘לך מ לך ימלוך<sup data-n=\"4236\">544</sup> עבר הוה ועתיד ראש תוך סוף כו' כמו שאו' אדון עולם אשר מלך<sup data-n=\"4237\">545</sup> בטרם כל יצור נברא שנק' מלך הקדוש מלך מרומם לבדו מאז שהוא מל'<sup data-n=\"4238\">546</sup> דא\"ס<sup data-n=\"4239\">547</sup> קודם הצמצום כנ\"ל, ומלך באמצעיתא זהו מל' דא\"ס בקו\"ח עד מל'",[["4219","528","<b>בתוה\"ק שקדמה לעולם הנאצל ונברא</b>: ראה מאמרי אדה\"ז תקס\"ז ע' ריג. הנסמן לעיל פ' וארא עט, ד."],["4220","529","<b>אתה הוי' לבדיך</b>: נחמי' ט, ו [בדילוג]."],["4221","530","<b>השמים כו' טה\"ע וטה\"ת</b>: ראה גם לעיל פ' בשלח קעח, ג. וש\"נ."],["4222","531","<b>ראו כי אנ\"י אני הוא</b>: האזינו לב, לט [בדילוג]."],["4223","532","<b>אתה הוי' אלקי'. . אשר בחרת באבר\"ם</b>: נחמי' ט, ז [בדילוג. ושם: האלקים]."],["4224","533","<b>מצאת לבבו נאמן</b>: ראה נחמי' שם, ח."],["4225","534","<b>וכרות עמו. . ותקם את דבריך</b>: נחמי' שם. ראה מאמרי אדה\"א שמות ח\"ב ע' תקנה ואילך."],["4226","535","<b>עו\"ז והד\"ר לבושה</b>: משלי לא, כה."],["4227","536","<b>ה' עוז לעמו יתן</b>: תהלים כט, יא."],["4228","537","<b>לבוש מל' אשר לבש בו המלך במ\"ת</b>: אסתר ו, ח. ראה גם לקמן פ' ויקהל תלא, סע\"ד. מאמרי אדה\"א שמות ח\"א ע' נא. במדבר ח\"ב ע' תקפ."],["4229","538","<b>לבש ה' עוז דתורה</b>: תהלים צג, א. ראה גם לעיל פ' בשלח קפג, ג. וש\"נ."],["4230","539","<b>ומשחקת לפניו בכל עת</b>: משלי ח, ל."],["4231","540","<b>משחקת בתב\"ל ארצו. . ב' ארצות</b>: משלי שם, לא. ראה גם תו\"ח ח\"ש קלז, ב."],["4232","*541","<b>דעוה\"ב שנק' ארץ החיים</b>: ראה גם לעיל פ' שמות ז, א. וש\"נ."],["4233","541","<b>שלעולם ירשו ארץ</b>: ישעי' ס, כא."],["4234","543","<b>גבו' גימ' רי\"ו</b>: ראה ת\"ז תכ\"ב (סז, ב). לקו\"ת להאריז\"ל ויחי עה\"פ גור ארי' יהודה (מט, ח). מאמר ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת תשנ\"ב) ע' 18. וש\"נ."],["4235","542","<b>שב\"פ. . רי\"ו. . תבל</b>: ראה ע\"ח (שער תיקון הנוקבא) של\"ד, פ\"ב כלל כב. תו\"ח ח\"ש קלז, ב ובהערה 24."],["4236","544","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א."],["4237","545","<b>אדון עולם אשר מלך</b>: תפלת השחר."],["4238","546","<b>מלך הקדוש. . מל' דא\"ס</b>: ע\"פ תפלת העמידה. ראה גם לעיל פ' בא ק, ג. וש\"נ."],["4239","547","<b>מלך מרומם. . מל' דא\"ס</b>: ע\"פ ברכת יוצר. ראה גם לעיל פ' בא צ, א. וש\"נ."]]],[2300550358,"דמל' דעשי' עכשיו שזהו לעת נעשה בחפצו כל מרצון הקדום דעצמו' א\"ס עד רצון שבמל' דעשי' אזי מלך שמו נקרא על עם נפרד כו', וימלוך לע\"ל זהו בחי' סוף דיום אחרון במל' דא\"ס הפנימי' שיהי' נצחיי' בחיי עולם כמ\"ש וע\"י יתיב<sup data-n=\"4240\">548</sup> כו', וזהו ואחרי ככלות הכל בתשלום הבירורים דרפ\"ח כו' לבדו ימלוך כו'. וזהו הי' הוה ויהי' דשם הוי'<sup data-n=\"4241\">549</sup> בכלל כידוע, ורת\"ס זה הכל בבחי' היושר בלי נטיי' כלל לימין ושמאל כמו בקו ההולך ביושר מראש לסוף באמת הבנין שמודד ביושר וזהו מצד קו המדה דתור'. וזהו ויהי בישורון מל\"ך שהוא מלך המשיח<sup data-n=\"4242\">550</sup> בבחי' סוף שנא' וגבה מאד יותר מאדה\"ר קודם החטא<sup data-n=\"4243\">551</sup> כידוע בענין אד\"ם א\"דם ד\"וד מ\"שיח<sup data-n=\"4244\">552</sup> שזהו ג\"כ ראש תוך סוף ומאד מ\"ם דמשיח קודם לא' דאדה\"ר וזהו וגבה מאד והוא א' רבתי דאד\"ם דדה\"י<sup data-n=\"4245\">553</sup> כו' וזהו כמו אני אחרון ומבלעדי כו' הנ\"ל וד\"ל).\n<b>ועוד</b> יתפרש במה שא' ומבלעדי באמצעיתא בחי' ממוצע, שגם בחי' הממוצע המקשר ומחבר שיאיר מעצמו' אוא\"ס בעולמות היינו מבלעדי אין אלקי בחי'<sup data-n=\"4246\">554</sup> ממוצע, שגם הוא נמשך מכח ועצמו' דא\"ס כמו כח המגביל <span data-k=\"pg\">974</span> ּ כל גבול ומדה שהוא כח הצמצום דשם אלקי' גם הוא מכח הא\"ס ב\"ה שהוא כל יכול כו', ויש בו גם כח זה דשם אלקים המגביל כל מדה והוא שנק' בחי' ממוצע ואמצעי שיש בו מבחי' אור העצמות ומבחי' הנאצלים כו'. והענין הוא בב' אופנים א' בדרך כלל במה שידוע דאוא\"ס למעלה עד אין קץ בעילוי אחר עילוי שנק' סדכ\"ס, והב' מה שאוא\"ס נמשך למטה עד אין תכלית והן ב' הפכי' ממש, ובכל ב' הפכי' בהכרח שיש בחי' ממוצע המחבר, שזהו פי' באמצעית' מאנ\"י ראשון בסדכ\"ס להיו' אנ\"י אחרון יש באמצעית' בחי' אמצעי וממוצע כו'. והוא במקום גדולתו שם ימצא ענוה שלו לצמצם עצמו להיות אני אחרון מקור לכל ההשתלשלו' דאבי\"ע, וזהו ענין שם אלקים שהוא כח המצמצם ומגביל כל גבול כו' והוא עצמו למעלה מן הגבול והיינו ומבלעדי אין אלקי\"ם כו' שגם אלקי' זה בא מכח העצמו' כו' כנ\"ל וד\"ל.\n<b>ובדרך</b> פרט יובן מזה במ\"ש והחכ' מאין תמצא<sup data-n=\"4247\">555</sup> ואיזה מקום בינה אלקי' הבין דרכה<sup data-n=\"4248\">556</sup> כו', פי' החכ' יש בה ב' מדרגות א' כמו שהיא כאי\"ן ממש והוא בחי' החכ' העצמי' דא\"ס שלתבונתו אין מספר<sup data-n=\"4249\">557</sup> ונק' חכים ולא בחכ' ידיעא<sup data-n=\"4250\">558</sup> כלל וזהו",[["4240","548","<b>וע\"י יתיב</b>: דניאל ז, ט."],["4241","549","<b>הי' הוה ויהי' דשם הוי'</b>: נסמן לעיל פ' יתרו רעא, ב."],["4242","550","<b>ויהי בישורון מל\"ך. . המשיח</b>: ראה גם לעיל פ' בשלח קנח, ג."],["4243","551","<b>וגבה מאד יותר מאדה\"ר קודם החטא</b>: ראה גם לעיל פ' שמות מז, ב ובהערה 156."],["4244","552","<b>אד\"ם א\"דם ד\"וד מ\"שיח</b>: ראה רקאנטי בראשית א, כו. לעיל מז, ב ובהערה 157."],["4245","553","<b>א' רבתי דאד\"ם דדה\"י</b>: בתחלתו."],["4246","554","<b>בחי'</b>: תיבה זו אינה ברורה בגוכתי\"ק."],["4247","555","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["4248","556","<b>אלקי' הבין דרכה</b>: איוב שם, כג."],["4249","557","<b>שלתבונתו אין מספר</b>: תהלים קמז, ה."],["4250","558","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה (יז, ב). ראה גם לעיל פ' יתרו רסו, סע\"ד ואילך."]]],[2300550378,"חכמה דתוה\"ק, ובדרך פרט זהו חכ' שבכת\"ר שנק' אנ\"י ראשון אנ\"י אותיות אין<sup data-n=\"4251\">559</sup> זהו בחי' ד\"ע מיש לאין דכלא חשיב, והוא מה שהחכ' נק' אין ממש דאפי' אור צח כו' אוכ\"ם הוא לגבי עה\"ע עצמו ונק' ירא בוש\"ת כידוע, וכמו תלמיד לפני רבו שבטל במציאות כך כח החכ' כמו שהיא מאי\"ן האמיתי בבושה<sup data-n=\"4252\">*560</sup> כו'. והב' מה שהחכ' מאין תמצא במציאות יש, והוא כמו גילוי אור הברקת השכל וכמעיין שנובע טיפין כו', וזהו אי\"ן ליש דבינה שנק' נהר<sup data-n=\"4253\">560</sup> כידוע. וזהו אני ראשון באין דחכ' הקדומה שנבדל בערך הרבה ממה שאני אחרון אין הב' דחכ' שנעשה אין ליש כמו בחכ' דמע\"ב שכולם בחכ' עשית, ויש בהכרח בחי' ממוצע ביניהן שיצמצם א\"ע מא\"ס דח\"ע לאין דחכמה (כמו יהושע נער<sup data-n=\"4254\">561</sup> איידי דטריד למבלע<sup data-n=\"4255\">562</sup> לא פליט וכשנעשה ראש ומשפיע למקבלים זהו ירידה וצמצום גדול בענין הוי זנב לאריות וכו'), והממוצע זהו בחי' אלקי' דהיינו כח המצמצם לח\"ע להיות נמשך למטה במקבלים וזהו אלקי' הבין דרכה כו'. וזהו בראשית דחכ' ברא אלקי'<sup data-n=\"4256\">563</sup> דוקא, וע\"ז א' ומבלעדי באמצעיתא זה אין אלקי' שגם הוא בא מכח העצמו' והוא בחי' קו המדה דחכ' דתורה שבאה למדוד כל מדה בהשתלשלו' וכמ\"ש מי מדד<sup data-n=\"4257\">564</sup> כו'. וזהו דאסתכל באורייתא וברא עלמא<sup data-n=\"4258\">565</sup> במדה ושיעור וכן אז ראה ויספרה<sup data-n=\"4259\">566</sup> כו' שז\"ש בשביל התורה שנק' ראשית<sup data-n=\"4260\">567</sup> כמ\"ש ה' קנני ראשית דרכו<sup data-n=\"4261\">568</sup> ובשביל ישראל שנק' ראשית<sup data-n=\"4262\">569</sup> כו' שמייחדי' יחוד פנימי במצות (כמשי\"ת).\n<b>וזהו</b> פי' הברכות דמצות ג\"כ בא\"י אלקינו מלך העולם פי' כמ\"ש למעלה בענין מלך מלך ימלוך כו' וכמ\"ש ה' מלך גיאות לבש כו' לבש ה' עו\"ז דתור\"ה שזהו בחי' הממוצע (כמשי\"ת). דהנה מל' דא\"ס כמו שהוא ברוממות העצמות ופנימי' דא\"ס אין לו שיעור למעלה ונק' מלך מרומם לבדו וכמו נכון כסאך מאז<sup data-n=\"4263\">570</sup> כו' וכדי שישפיל א\"ע להיות מלך גאות מל' כ\"ע בקו\"ח עד מל' דעשי' זהו צמצום גדול. וזהו אני ראשון ואני אחרון אני אין בחי' כתר מל' דא\"ס אני ראשון שזהו מיש לאין כו' ואני אחרון מל' דא\"ס אחר <span data-k=\"pg\">תפז</span> ּ הצמצום בקו\"ח וממוצע המחבר ב' הפכי' אלה הוא התורה ומצו' שז\"ש הוי' אלקינו מזה דוקא נמשך ומתצמצם להיות נק' שמו שם מלכותו עליהם מלך העולם בכלל, וז\"ש בי מלכי\"ם ימלוכו<sup data-n=\"4264\">571</sup>, וראי' מי\"פ דמלכיו' בר\"ה<sup data-n=\"4265\">572</sup> כמ\"ש במ\"א. והיינו לפי ששם הוי' דתו\"מ הוא בחי' עצמיות השכל ומדות דמלך הקדוש ומרומם הנ\"ל והארה וזיו הפנימי'",[["4251","559","<b>אנ\"י אותיות אין</b>: ראה פרדס (שער אם הא\"ס הוא הכתר) ש\"ג, פ\"א. הנסמן לעיל פ' וארא נ, ד הערה 68."],["4252","*560","<b>בבושה</b>: ח: בחי' מה."],["4253","560","<b>דבינה שנק' נהר</b>: זהר (אדרא דמשכנא) משפטים קכג, ב."],["4254","561","<b>יהושע נער</b>: תשא לג, יא [בדילוג]. ראה לעיל שכ, א ובהערה 64."],["4255","562","<b>איידי דטריד למבלע</b>: נסמן לעיל פ' יתרו רסז, ד."],["4256","563","<b>בראשית. . ברא אלקי'</b>: בראשית א, א."],["4257","564","<b>מי מדד</b>: ישעי' מ, יב."],["4258","565","<b>דאסתכל באורייתא וברא עלמא</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט."],["4259","566","<b>אז ראה ויספרה</b>: איוב כח, כז."],["4260","567","<b>בשביל התורה שנק' ראשית</b>: בראשית א, א וברש\"י שם. הנסמן בלקו\"ש נח (כרך ג) ע' 755."],["4261","568","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["4262","569","<b>ובשביל ישראל שנק' ראשית</b>: רש\"י בראשית א, א."],["4263","570","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["4264","571","<b>בי מלכי\"ם ימלוכו</b>: משלי ח, טו."],["4265","572","<b>מי\"פ דמלכיו' בר\"ה</b>: ר\"ה לב, א (במשנה). ראה גם לעיל פ' בא צז, א. וש\"נ."]]],[2300550397,"הזאת הוא שיורד למטה בתו\"מ שזהו שנק' אלקינו ממש בלי שינוי כלל כנ\"ל, ע\"כ זהו בחי' הממוצע בין עצמיות המלך הקדוש בתוה\"ק שזהו אני ראשון להתפשטו' מלכותו שנק' אחרון שיהי' נק' מלך העולם כמו כח הפועל כו', והוא בחי' אלקי' דתו\"מ דוקא וכמ\"ש אלקים הבין דרכה כמ\"ש ה' קנני ראשית כו'. וזהו ומבלעדי אין אלקי' אף בפנימי' התו\"מ שהן תומ\"צ וישראל שנק' ממוצע כמ\"ש בשביל ישראל שנק' ראשית שהן מייחדי' שמו העצמי' במצות ולכך הוי' אלקינו כו' וד\"ל.\n<b>והנה</b> מעתה אחר כל הנ\"ל יובן בדרך פרט וכלל בפ' זאת במ\"ש ואתה תצוה את בנ\"י ויקחו אליך כו' עד להעלות נר תמיד, דכלל ענין זה מדבר במעשה המצות כולן שיצוה לבני ישראל לעשותם שכללותם הוא מה שיקחו אליך שמן זית כתית למאור, פי' למאור שימשיכו מבחי' מאור דעצמות אוא\"ס כל פנימית האור דתו\"מ שזהו כדי להעלות נר תמיד דוקא, כי המצות נק' נר ותורה אור כמ\"ש כי נר מצוה<sup data-n=\"4266\">573</sup> כו'. והיינו כדי להעלות נר דמצוה תמיד למעלה בבחי' פנימי' ועצמו' דא\"ס וכמו אל מול פני המנורה<sup data-n=\"4267\">574</sup> יאירו ז' הנרות שהן כללות דנשמות ישראל שהן ז' נרות המנורה<sup data-n=\"4268\">575</sup> כי נר הוי' נשמת אדם<sup data-n=\"4269\">576</sup> בפרט ובכלל, ובנר מצוה דוקא יאירו נרות דנש' ישראל אל מול פני המנורה שהוא עצמו' דאוא\"ס כמו שהוא בפנימי' הכת\"ר כו' כמו יאר הוי' פניו אליך כו'. וזהו להעלות נר הוי' דנשמות ישראל לפני הוי' בבחי' פב\"פ תמיד שהוא ע\"י המצות דוקא כנ\"ל בברכות המצות, שמטעם זה או' הוי' אלקינו דוקא וכמ\"ש כי אתה תאיר נרי<sup data-n=\"4270\">577</sup> כו', ע\"י המצות שנק' נר נמשך ממאור להמשיך להאיר אור הפנימי' ועצמו' דרצה\"ע וח\"ע להאיר לנש\"י שהן נרות המנורה בכלל, וזהו להעלות נר תמיד בכללות דז' נרות המנורה והוא ע\"י מה שתצוה לבנ\"י ויקחו אליך שמן כו' (כמשי\"ת). והנה תחלה יש להבין בתוספת ביאור למה ע\"י המצות דוקא או' הוי' אלקינו כמו הוי' אלקיו עמו כו' שזהו יחוד פנימי' דהוי' ואלקי' בלי העלם ולבוש חיצוניו' כלל, אלא כולו בחי' פנימי' ועצמיו' שזהו כל ענין יח\"ע ויח\"ת שמייחדי' שמו העצמי בק\"ש ב\"פ כו' (והיינו בשביל ישראל שנק' ראשית כנ\"ל, לפי שהן העושי' הכלים הפנימי' ועצמיי' לאורות העצמיי' כמצות שנק' נר ותורה אור כו', לכך הן בחי' ממוצע להיות מזה מלך העולם בחיצוני' ההשתל' כנ\"ל).\n<b>והנה</b> יש להקדים תחלה בשרש ענין המצות שנק' כלים פנימיי' ועצמיי' דוקא כמו שידוע בשרש רמ\"ח מ\"ע למעלה שנק' רמ\"ח אברים דמלכא<sup data-n=\"4271\">578</sup> כו', ולכאורה הרי המשל ודמיון מאברי האדם הרי האברים הן רק כלים חיצוני' שמגבילים האור",[["4266","573","<b>כי נר מצוה</b>: משלי ו, כג."],["4267","574","<b>אל מול פני המנורה</b>: בהעלותך ח, ב."],["4268","575","<b>דנשמות ישראל. . המנורה</b>: ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא ואילך. וש\"נ."],["4269","576","<b>נר הוי' נשמת אדם</b>: משלי כ, כז."],["4270","577","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["4271","578","<b>רמ\"ח מ\"ע. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג. הערה 17."]]],[2300550414,"וחיות בתוכם בערך הגשם אל הרוחני כחומר לצורה שמצומצם בו האור הרוחני ונק' אדם חיצוני, ומה שקורא למצות רמ\"ח <span data-k=\"pg\">976</span> ּ אברים דמלכא זהו לשבח ומעלה יתירה שזהו שאנו או' שקדשנו במצותיו דוקא שנק' מצות הוי'<sup data-n=\"4272\">579</sup> שהוא בבחי' פנימי' ועצמו' דא\"ס כמ\"ש רחבה מצותך מאד והוא מצד בחי' או\"מ דרצון העליון העצמי שבמצות כידוע. אך הנה ידוע שבמצות יש ב' ענינים א' כמו שהן למעלה ממש שנק' מצות הוי'<sup data-n=\"4273\">580</sup> מצותי ממש (כמו שה' מניח תפילין<sup data-n=\"4274\">581</sup> ומתעטף בציצית<sup data-n=\"4275\">582</sup> ועושה צדקה<sup data-n=\"4276\">583</sup> בחסד עליון דאצי' שנק' דרועא ימינא דקוב\"ה וכן עוסק בתורה<sup data-n=\"4277\">584</sup> בחכמה מוחא כו' וכה\"ג שזהו בבחי' אדם העליון דאצי' כידוע). והב' כמו שהמצות נעשי' למטה בדברים גשמיי' דנוגה בתפילין בקלף גשמי וציצית בצמר כו' וכה\"ג, דאע\"פ שנקראי' בחי' כלים מכלים שונים להאיר בהן בחי' גילוי אור דרצה\"ע ממש כמו שהוא למעלה במצות העליונים הרוחני' דאצי' באו\"כ, ויש בהן בחי' קדושה העליונה ממש כמו שאו' שקדשנו במצותיו דקדושת העצמי' דמצותיו ממש שנק' רמ\"ח אברים דמלכא כו'. מ\"מ הרי המצות מלמטה שנעשי' בדברים גשמיי' נק' בחי' בירורי' שמתברר ועולה מדברים גשמיי' דנוגה דעשי' כו' ועולים למעלה באצי' להיות בבחי' כלים לאורות דאצי' וכמא' ועשיתם אתם כאלו עשאוני<sup data-n=\"4278\">585</sup> ברמ\"ח אברי' כו', ולכאורה אין זה מובן דהלא כבר יש מציאות או\"כ באדם דאצי' כמו חסד דרועא כו' כנ\"ל.\n<b>אך</b> הנה הענין יובן במשל האברים למטה באדם שיש בהן ב' ענינים, א' חיצוני' האברים כמו שהן בחי' כלים מגבילים אור וחיות שממוזג בכאו\"א כפי טבע בריאותו מתולדתו בבטן להיות חומר לצורה הרוחני' שבו, ואע\"פ שהיו האברי' תחלה בקטנות ואח\"כ הם מתגדלים גם זה הגידול בא בטבע הבריאה כמו שגדל החיות הפנימי' שלו שהוא האור וחיות שבנפשו שנמשך ממנה אור וחיות לכל אבר כו'. ונמצא שהאברים אע\"פ שהן כלים חיצוני' בגשם לרוחני' ומוגבלים מ\"מ הן נחשבים במהות ועצם א' ממש עם האור וחיות הרוחני ממש והיו לאחדים בלי הפרש כלל ביניהן. וראי' ממה שהאדם מרגיש בחיי נפשו הרוחני' כשכל הרוחני שבמוח וראי' הרוחני' בעין והילוך ברגל וכה\"ג בשאר הכחות דנפש ואורות חיות האברים ה\"ז ממש הרגשה בעצם האברים שהן חיים וקיימי' באור וחיות זה בכלל ובפרט בכל אבר, וכן התנועה באבר הגשמי הוא עצמו התנועה ברוחני' שבו ואין לחלק ביניהם כלל. וכמו בהקיץ שמרגיש החיות באברים ומניע האור והכלי שהוא הצורה וחומר כא' כך הוא בשינה שחיות הכללי במוח ולב בהסתלקות מ\"מ החיות נשאר באברים וישנם במציאותם ממש בצו\"ח שלהם כמו בהקיץ",[["4272","579","<b>מצות הוי'</b>: נסמן בהערה הבאה."],["4273","580","<b>מצות הוי'</b>: ויקרא ד, ב. יג. כב. ראה גם לעיל פ' יתרו רנט, ג ואילך."],["4274","581","<b>שה' מניח תפילין</b>: ברכות ו, א. ראה מאמרי אדה\"א שבהערה הבאה."],["4275","582","<b>ומתעטף בציצית</b>: ראה ר\"ה יז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["4276","583","<b>ועושה צדקה</b>: ראה גם לעיל פ' יתרו רס, ד הערה 209. וש\"נ."],["4277","584","<b>עוסק בתורה</b>: ע\"ז ג, ב."],["4278","585","<b>ועשיתם אתם כאלו עשאוני</b>: נסמן לעיל פ' יתרו רנט, ד."]]],[2300550431,"ממש כו', שההרגש בצו\"ח בהעלם והתנועה בגילוי בחיות דקטנות וצמצום הנשאר באברי' כמו שהן מתחלת עצם הווייתן בתולדה שמאותו מקור שנולד מאין ליש הנפש עצמה הרוחני' וכחות שלה הרוחני' משם נמצא ונתהוה החומר של האברים (כמ\"ש בע\"ח דבנין הכלים קודם לאורות<sup data-n=\"4279\">586</sup> כמו בולד שהתהוות של החומר קודם ליצי' הנפש הרוחני' כו', לפי ששרש הכלים מבחי' או\"מ<sup data-n=\"4280\">587</sup>, ואם התהוות הצורה קודמת מ\"מ מתהוי' הצו\"ח כא' במהות ועצם א' ממש בחכמה <span data-k=\"pg\">תפח</span> ּ מוחא המוח הוא בחי' כלי עצמי' לאור השכל והעין כלי עצמי' לראי' וכה\"ג, וע\"כ אין לאבר חילוף ושינוי בבריאה כלל ואדרבה עיקר המוח באדם הוא באברי' החיצוני', לפי ששרש חיצוני' האברים למעלה מפנימי' דאור וחיות מטעם הנ\"ל וראי' מתחה\"מ<sup data-n=\"4281\">588</sup> כידוע וד\"ל). ונמצא מובן שהאברים מתחדשי' מאין ליש במציאותם בחידוש מעיקרו כמו האור וחיות דנפש עצמה כמו גם בעת השינה שנמשך חיות לאברים ממקור החיות דנפש ממילא שצריכה לקבל אור ושפע חדשה ממקורה למעלה כו'. וזהו מה שנדמה לאדם שהוא חי ואבריו חיים וקיימים ממילא כמו טבע הכרחי' החיות בכל בע\"ח מתולדתו (שנק' בל\"א נ„טור) שמתקשר הרוחני' בגשמיות דאברי' ממילא ומאליו מצד הדם הוא הנפש כו' אע\"פ שאין ערך לגשם לגבי הרוחני כידוע מ\"מ כאשר נעשה החומר מוכן לקבל הצורה הרוחניות ממילא מיד נמשך הצורה בחומר כראי' בעין ושכל במוח וכה\"ג וד\"ל.\n<b>וענין</b> הב' באברי האדם היינו מה שע\"י בחי' ממוצע כמו המזון דמאכל מחבר ומקשר בחי' הרוחני' דאור וחיות בחומר האברי' שאין זה דבר חדש מעיקרו כלל, כי הרי התלבשות והרכבת חיות הרוחניות באברי' ממילא בא בקיום חזק מצד טבע הבריאה מתולדתו כנ\"ל עד שהן עצם אחד ממש, וחידוש חיותם ומציאותם נק' חידוש מעיקרו ממקור התהוות הצו\"ח דנפש האדם וכל בע\"ח. רק שבלא מזון ומחי' כלל הי' האור וחיות הרוחני' מסתלק מן החומר שמלובש בדם והרכבת ד\"י גשמי' כמו בתענית שמתחלש הכח הרוחני, אע\"פ שחלישות כח זה אינו ברוחני מצד עצמו כ\"א מצד הכלי והחומר כחלישות כח הרגל להילוך והיד לעשות והמוח להשכיל והעין לראו', מ\"מ זהו חלישות הכלי בא מצד הסתלקות הצורה מפני שאין דבר שיחזק הצורה בחומר והוא גרעון החומר מקלקול וחלישות הדמים כו' וכמו בזקן וחולה וכה\"ג. אך ע\"י המאכל או הרפואה שמחזק כח הדם שבאברים הוא הסיבה מה שיחבר ויקשר הצורה בחומר שיאיר בתקפו כמו שהוא בעצם בריאותו (שנק' נ„טור כו'), והיינו ענין גידול החיות באברים בכל משך זמן קיומו שמתקיים ע\"י המזון כמו על הלחם שיחי' האדם כי לחם לבב אנוש יסעד<sup data-n=\"4282\">589</sup>, דהיינו מה שמחזק הכח וחיות הרוחני' שיתחבר באברים שהן החומר עד שכלי המוח יקבל יותר צורת השכל והעין יקבל יותר הראי' והיד למלאכה ורגל להילוך וכה\"ג. אבל לא שע\"י המזון",[["4279","586","<b>דבנין הכלים קודם לאורות</b>: ראה לקמן פ' ויקהל תג, א. מאמרי אדה\"א קונטרסים ע' רז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670259\" data-slug=\"torat-chaim\" data-id=\"2300670259\">תו\"ח בראשית י, ד</a> ובהערה 14."],["4280","587","<b>ששורש הכלים מבחי' או\"מ</b>: ראה גם לעיל פ' שמות מו, א. וש\"נ."],["4281","588","<b>וראי' מתחה\"מ</b>: ראה עט\"ר דרוש לש\"ש ע' 80. מאמרי אדה\"א דברים ח\"א ע' שכז."],["4282","589","<b>לחם לבב אנוש יסעד</b>: תהלים קד, טו."]]],[2300550447,"ומאכל נמשך אור וחיות חדש מעיקרו ממש כי זהו נמשך מכבר כנ\"ל רק שמחזק חיות הנפש בגופו לבלתי תצא, כמו בהתעלפות מהעדר המזון והחולה מקלקול הדמים וקלקול החומר. ואע\"פ שמתחזק האדם בתוס' כח וחיות באברי' ע\"י המזון אין זה תוס' מחודש מעיקרו כלל רק האור וחיות שכבר במציאות בנפש מתפשט בכלים יותר, ונמצא אינו גורם רק התקשרות וחיבור הרוחני' בגשמי' שיהי' זה בתמידות ולא יופסק, וזהו שנדמה לאדם שמתחדש חיותו בכל יום ויום. ובאמת אין זה <span data-k=\"pg\">978</span> ּ חדוש מעיקרו כי גם בחי' התקשרו' הצורה בחומר כבר הוטבע בתולדה מבטן רק שאין לו קיום בתמידות אם לא ע\"י המזון שעושה התחדשות תמידי בחיבור הצו\"ח בכל יום להחזיק האור בכלי שלא יסתלק, אבל באמת א\"ז חידוש גמור מה שמתחדש חיות שלו בכל יום ע\"י מזון כי גם בשינה מתחדש הצו\"ח כא' כו' רק זה ענין גידול וחיזוק האור בכלי כ\"ז משך קיומו בעולם כנ\"ל וד\"ל.\n<b>והנה</b> באמת אע\"פ שמבואר למעלה דבאברים וכלים מצד עצם הבריא' מתאחדי' עם האור ולכך אין בהם שינוי וחילוף אע\"פ שמגבילי' ומגשמי' הרוחני' כראי' גשמי' בעין מראי' הרוחני' וכה\"ג, ויש בזה חידוש גמור מאין ליש במקור התהוות הנפש בצו\"ח כנ\"ל. משא\"כ במזון ומחי' שיחי' האדם על ידו שאינו רק חיזוק הצורה בחומר להעמידו על מקומו הראשון לבד ואין בזה חידוש מעיקרו כלל רק כממוצע כו'. אמנם עכ\"ז באמת יש יתרון מעלה הרבה לבחי' הממוצע הזה דמזון אע\"פ שהוא גשמי יותר מאברי' שהן כלים עצמיי' עכ\"פ, במה שמחבר ומקשר הצורה הרוחני' בחומר בתוס' אור וחיות רב הרבה יותר מעצם הבריאה בהתקשרות דצו\"ח יחד כמו ולד בבטן האם, כי הלא מה שמתחבר הצורה בחומר בטבע הבריאה ה\"ז בא בצמצום גדול מאד בבחי' שינוי המהות מרוחניות לגשמיות כידוע בענין אדם א' דם, שמבחי' הגשמי' שברוחניות נמשך רוחניות בגשמי' כצומח דחטה ועשב שמכח הצומח הרוחני מתגשם לגדל ולהצמיח החטה ועשב בצמיחה גשמי' בחומר העשב כו'. כך רוחניות הזאת דצורה בחומר האברים אף בגידולו בבטן האם אינו בא רק מצמצום וקטנות דנפש הרוחני' בעצם ולכך אינו מאיר באברי' רק בבחי' קטנות בהעלם גדול כעיבור הולד בבטן, וכמו\"כ בשינה שהפנימי' דאור וחיות דשכל ומדות וגם רוח דנפש דדם ובשר נשאר רק בקטנות מאד כמו בתנועה גשמי', והיינו לפי המדה שצריך להיות בחיבור הרוחני' בגשמי' לבד בלי תוס' אור מחודש לעולם כו'. משא\"כ בלידת הולד שיצא במהות ברי' בפ\"ע רק שיונק משדי אמו יש לו אור וחיות בגילוי רב יותר בכל האברים גם בהרגש ותנועה וראיה ושמיעה והילוך כו', אף שהוא ג\"כ בדרך בריאה טבעי' כנ\"ל. וכמו\"כ בהקיץ אדם מן השינה יאיר אור השכל במוח והראי' בעין בהתפשטו' וההילוך ברגל בחיות מחודש והיד בפעולה וכה\"ג,"],[2300550462,"שזהו רק התפשטו' האור וחיות בכלים ואברים ביותר שאין זה כלל בשינה או בעיבור הולד בבטן אע\"פ שכבר נמשך בגופו אור וחיות הצורה כו'.\n<b>וכמו</b> הפרש גדול הזה בין שינה לבהקיץ ובין עיבור ללידה כך יובן עוד הפרש גדול הרבה יותר מזה גם בין לידה או בהקיץ לגידול האדם וקיומו בחיות נפשו בגופו כל ימיו ע\"י המזון ומאכל כנ\"ל בכל ימי משך קיומו ע' שנה, דגם שהמאכל ומזון גשמי אבל עי\"ז יש חיבור וקשר הרוחני' דנפש כמו שהוא בעצם ממש שיתפשט כל כוחו' שלה בתוס' אור מחודש בגילוי רב גם בכלים שהם האברים הגשמי', כמו שע\"י החיזוק כח המאכל בדם הוא הנפש יתוסף כח הרוחני כמו שהוא בנפש עצמה לפעול כל מלאכה וכן <span data-k=\"pg\">תפט</span> ּ יתוסף כח העין לראות ואוזן לשמוע והשכל במוח להשכיל כל חכ', שבכל זה נראה רק כח התפשטות אורות בכלים בתוס' מרובה על עיקר עצם הבריאה דצו\"ח בתולדה, כמו אומן יד בכל מלאכה ע\"י הפעולה שבא בחידוש הכח הרוחני שמתגדל בה משך זמן רב מידי יום ויום דוקא נעשה אומן גדול. וכן איש החכם בעסקו בלימודי' שכליי' כל ימיו בכלי המוח הגשמי דוקא ימים ידברו ורוב שנים יודיעו חכמה<sup data-n=\"4283\">590</sup> עד שנק' זקן שקנה חכמה<sup data-n=\"4284\">591</sup> ממקורה שנתגלה בו כל העלם דחכמה מאין ליש. וכך במדות שבלב בחסד שנמשך בלבו ע\"י חיבור האור בכלי בתוס' מרובה במה שפועל ועושה חסד רב ה\"ז תוס' אור בכלי למעלה מכפי המדה שהי' בתחלה. וכן בכל ציור אדם באו\"פ שבכלי' שנק' גידול וצמיחה מקטנות לגדלות בכל משך זמן קיומו, שכל זה אינו אלא ע\"י חיזוק זה דאור בכלי ע\"י המזון ומחי' שמחזק כח שכלו ומדותיו ופנימית חיות האברים הרבה יותר מעצם הבריאה שלהם בצו\"ח כו'. וזה הפרש גדול יותר מבחי' לידה דולד על עיבורו ובהקיץ על שינה הנ\"ל שגם בהקיץ או בלידה אין תוס' מחודש בפנימי' הצורה כלל כו'. ונמצא מובן בדרך כלל שגם שיש מעלה באו\"כ בתולדה שהן עצם אחד ומחודש מאין ממש כנ\"ל, מ\"מ אין זה רק בחי' חיצוניות לבד בכלל שהוא חיצוני' וקטנות האורות בחיצוניות וקטנות הכלים שהן האברים, אבל בחיזוק האורות בכלים ע\"י מזון שמגדל כל ימיו כנ\"ל, אע\"פ שאינו אלא חיזוק לבד כנ\"ל יש בזה תוס' מרובה וחידוש רב בפנימי' ועצמי' הרוחני' שיאיר כמו שהוא ממש בפנימית האברים בלא בחי' חיצוניות כלל וכלל וד\"ל.",[["4283","590","<b>ימים ידברו. . חכמה</b>: איוב לב, ז."],["4284","591","<b>זקן שקנה חכמה</b>: נסמן לעיל פ' משפטים ש, ב."]]],[2300550477,"<b>והנמשל</b> מכל הנ\"ל יובן תחלה בנשמה האלקי' הרוחניות שהוא בבחי' צו\"ח או\"כ ברוחניות ומזה יובן בדוגמא למעלה בבחי' אדם דאצי' (ואדם דבריאה) שהוא בחי' זו\"נ דאצי' כו'. דהנה גם הנה\"א יש ב' מדרגות ברוחני' האלקי', א' בחי' הצורה שהוא עצם הנפש הזאת האלקי שכלולה מרצון ושכל אלקי ומדות אוי\"ר אלקי', ולמעלה היינו חב\"ד חג\"ת נה\"י בכלל וג' כלים מוחא ולבא כו' כמו באדם הגשמי וכן יש פרטי אברי' פנימי' וחיצוני' כיד ורגל כו'. שהרי ידוע בשרש הנשמות שהיו תחלה בבחי' עיבור בבטן המל' שנק' אם הבנים ונק' אימא תתאה<sup data-n=\"4285\">592</sup> וכמ\"ש בזוהר דכל נשמה הוה קיימא<sup data-n=\"4286\">593</sup> כו' שזהו אוצר הנשמות<sup data-n=\"4287\">594</sup> ששמו גוף<sup data-n=\"4288\">595</sup> כמבואר בדרז\"ל, וכמ\"ש כמו הרה תקריב ללדת<sup data-n=\"4289\">596</sup> כו' שנק' אשה הרה וכמ\"ש במשנה כאשה עוברה<sup data-n=\"4290\">597</sup> כו' וכמו בגלות שנק' עיבור כו' (או שינה<sup data-n=\"4291\">598</sup> בקטנות המוחי' ומדות). וכמו שבעיבור יש בנין החומר כמו בנין הצורה כנ\"ל, כך הוא בנשמות האלקי' שהוא בא בדרך טבע הבריאה מאין ליש כמו אתה בראת יצרת<sup data-n=\"4292\">599</sup> כו'. וכמו שרואי' בגילוי בנה\"א במהות ועצמו' שלה ברצון ושכל והשגה אלקי' שאין כל א' דומה לחבירו<sup data-n=\"4293\">600</sup>, יש שכל משיג כך וכך, ויש שכל משיג באופן אלקו' באופן אחר כל א' לפום שיעורא דילי'<sup data-n=\"4294\">601</sup> עד שהי' ס\"ר דיעות, כמו בנים רבים שמתולדה שלהם בבטן אמם מובדל זה מחבירו כמ\"ש בזוהר בלק על מראש <span data-k=\"pg\">980</span> ּ צורים<sup data-n=\"4295\">602</sup> כו' דמסט' דאימא אתמתח כו' שהוא התפשטו' הנה\"א באוצר העליון בבחי' עיבור המוחין ומדות (ומסט' דאבא נמצא עצם הנשמה טרם שמתפשט בשכל ומדות באו\"כ כו' וכמ\"ש במ\"א שזהו תושב\"כ שנק' מוסר אביך שהן ס\"ר אותיות<sup data-n=\"4296\">604</sup> שלה ותושבע\"פ נק' אמ\"ך<sup data-n=\"4297\">603</sup> כו'). וא\"כ בהכרח לומר שיש בחי' חומר לצורה זו ג\"כ, והיינו בחי' כלי המגביל לאור במוח הגשמי בגוף. כך יש במוח חכ' בנשמה ומוח בינה וכן ראי' עין ושמיעת אוזן והילוך ברגל והכל בבחי' הרוחני', רק שנק' כלים ואברים כמו ילכו מחיל<sup data-n=\"4298\">605</sup> בהילוך רוחני בהילוך גשמי דרגל וזהו עלי' הנשמות מג\"ע לג\"ע ברגל דוקא. וכן הראי' בעין לאסתכלא ביקרא כו', וכן אוי\"ר בלב ופעולה ביד ודיבור בפה כמו ששמע ב' רוחות מספרות<sup data-n=\"4299\">606</sup> זו עם זו כו'. וכמלאכי' שקוראין זא\"ז<sup data-n=\"4300\">607</sup> כו' (שכך הן המלאכי' שנק' אברים דשכינה כמו רגלי השכינה ועיני ה' ואזני ה' כו' מארי דאשגחותא<sup data-n=\"4301\">608</sup> ומארי דידין ורגלי'<sup data-n=\"4302\">609</sup> כו' כמ\"ש בזוהר), שכל זה אינו רק בבחי' כלים המתארי' לאור באותיות השכל ואותיות המדות כו' שבאופן כך וכך מתגלה אופן השגתו האלקי' ואופן התפעלות אוי\"ר אלקי'. וכמו בכלים ואברים",[["4285","592","<b>המל'. . אימא תתאה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא</a> רפנ\"ב. אגה\"ק סכ\"ה (קלט, א). הנסמן במ\"מ ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381202\" data-slug=\"likkutei-torah\" data-id=\"4001381202\">לקו\"ת שה\"ש יח, ב</a>."],["4286","593","<b>דכל נשמה הוה קיימא</b>: ראה סה\"מ תש\"ח ע' 182 הערה ה. לעיל פ' בשלח קסד, ב. הערה 14."],["4287","594","<b>המל'. . אוצר הנשמות</b>: ראה גם לעיל פ' וארא סז, א. וש\"נ."],["4288","595","<b>אוצר הנשמות ששמו גוף</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. הנסמן לעיל פ' וארא סז, א."],["4289","596","<b>הרה תקריב ללדת</b>: ישעי' כו, יז."],["4290","597","<b>במשנה כאשה עוברה</b>: ראה ברכות כט, ב. לעיל פ' שמות לא, ג. הערה 215."],["4291","598","<b>בגלות שנק' עיבור. . שינה</b>: ראה גם לעיל פ' שמות כה, א. וש\"נ."],["4292","599","<b>אתה בראת יצרת</b>: ברכת אלקי נשמה [בדילוג]."],["4293","600","<b>שאין כל א' דומה לחבירו</b>: ראה סנהדרין לז, א ב(משנה). לח, א. ברכות נח, א. שערי אורה צג, א ובהערה 17."],["4294","601","<b>לפום שיעורא דילי'</b>: ראה זהר וירא קג, רע\"ב."],["4295","602","<b>בזוהר בלק על מראש צורים</b>: ראה שם רג, ב. ביאוה\"ז שם קג, א ואילך."],["4296","604","<b>תושב\"כ. . ס\"ר אותיות</b>: ראה מג\"ע אופן קפו. לעיל פ' שמות לב, ב. וש\"נ."],["4297","603","<b>תושב\"כ שנק' מוסר אביך. . אמ\"ך</b>: ראה אגה\"ק סכ\"ט (קנא, א) בשם הזהר. לעיל פ' שמות ט, ב ובהערה 411."],["4298","605","<b>ילכו מחיל</b>: תהלים פד, ח."],["4299","606","<b>ששמע ב' רוחות מספרות</b>: ברכות יח, ב."],["4300","607","<b>וכמלאכי' שקוראין זא\"ז</b>: ישעי' ו, ג."],["4301","608","<b>מארי דאשגחותא</b>: ראה זהר (אד\"ר) נשא קלו, ב."],["4302","609","<b>ומארי דידין ורגלי'</b>: ת\"ז תי\"ח (לב, ב). ת\"ל (עה, א)."]]],[2300550492,"שבגוף ונפש הטבעי' ממש שנולדו צו\"ח יחד בבטן ונתקשר רוחניות בגשמי' והי' למהות אחד, כך הוא בנשמת האדם בצו\"ח שלה שהוא כמו קשר רוחניות בגשמי' ממש ויש בזה בחי' קטנות וגדלות כו' בעיבור שהוא תלת גו תלת<sup data-n=\"4303\">610</sup> כו', שהמוחין ומדות בהעלם ולא נשאר רק צמצום דקטנות בחיצוניות האברים דנה\"י כו', ובנש\"י בגלות שמוחין ומדות שלהם בתכלית קטנות והעלם ולא נשאר רק בחי' נה\"י שבנה\"י שהוא אוי\"ר דקטנות למעשה בלבד כו'. והגאולה נק' לידה<sup data-n=\"4304\">611</sup> כלידת הולד שנפקחו עיניו ויראה וישמע כו' כי יאיר אורות בכלים כו', כך לע\"ל יהי' ראי' עין השכל האלקי בנשמות ויפקח עיני כל נשמות ויאמר כל אשר נשמה באפו ה' כו', כמו בראי' חושי' וכמו וראו כל בשר<sup data-n=\"4305\">612</sup> כו' וכן לחזות בנועם ה' כו' וכן האוזן תשמע וכה\"ג בכל ציור אברים דנשמות שיהי' אז בבחי' לידה, וכמו ההפרש ממש בין בעת השינה להקיץ שבהקיצו יאיר שכלו במוחו ויבחין וידע הכל וכן המדות בלב והראי' בעין והילוך ושמיעה כו' והילוך ברגל (ומטעם זה אין זה פלא כ\"כ מה שלע\"ל יכירו וידעו כולם במהו\"ע אלקו' כמו בראי' מקרוב ממש כמ\"ש כולם ידעו אותי ולא ילמדו איש את רעהו בהשגות שכלי' כעכשיו ויהיו בביטול תמידי בלי הפסק יותר ממלאכים דעכשיו אע\"פ שהן כמו אברים כו' שאין זה רק בכח אלקי המצומצם בהם כו').\n<b>ומעתה</b> יובן ב' הענינים הנ\"ל באברי' דאדם הגשמי שכך הוא ברוחניות דאדם דנה\"א שנק' אדם דבריאה כאדה\"ר בג\"ע קודם החטא כו' שהי' עקבו<sup data-n=\"4306\">613</sup> כו' כמ\"ש במ\"א שהי' ראשו בבריאה<sup data-n=\"4307\">614</sup> וגופו ביצי' ורגליו בעשי') וכך בא\"ק אדם דבריאה<sup data-n=\"4308\">615</sup> בכללות הכל, עקב דא\"ק מסתיים בסוף העשי'<sup data-n=\"4309\">616</sup>, וזהו שנק' עקבו' משיחא<sup data-n=\"4310\">617</sup> וכמו רגלי השכינה למעלה כו' וכהארץ הדום <span data-k=\"pg\">תצ</span> ּ רגלי<sup data-n=\"4311\">618</sup> כו'). שענין הא' הוא שהצו\"ח מתחדשי' בחידוש גמור מאין ליש והן עצם א' בלי שינוי וחילוף שהרי נק' בעל מום בחסרון אבר גשמי כו'. וכך הוא בחומר לצור' דנשמה כמו שנפגם צלם אלקי' דנשמה בחטא כמו ונפש כי תחטא<sup data-n=\"4312\">619</sup> שזהו עושה חסרון אבר בפגם העין והאזן ויד ורגל וכה\"ג כמו בעין ואוזן ויד ורגל גשמי בגוף ממש כו', ועכ\"ז אע\"פ שמתארי' הכלים ומגשמי' לפנימי' ועצמי' דאור הנשמה נחשב עצם ומהות א' כנ\"ל. ולכך הנשמות צריכים לבא בנהר דינור וגיהנם<sup data-n=\"4313\">620</sup> עד שתתמרק וימולא בה כל חסרון ופגם באברים כו' וכאשר יתוקן הכלי ממילא נמשך האור כנ\"ל, רק שיש בזה בחי' קטנות וגדלות כמו עיבור ולידה וכמו שינה והקיץ שיש הפרש גדול ביניהם אך שניהם הן בדרך בריאה בעצם (כמו נאטור). וענין הב' באברים הוא מה שמתחזק האור בכלי ע\"י מזון ומחי' שאין זה חידוש מעיקרו בבריא' האו\"כ שכבר ישנם במציאות כו' רק בלא מזון",[["4303","610","<b>תלת גו תלת</b>: ראה זהר (תוספתא) בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. שעה\"י קל, ב הערה 18."],["4304","611","<b>והגאולה נק' לידה</b>: ראה תו\"א ר\"פ וארא. לעיל פ' שמות יז, ג הערה 725."],["4305","612","<b>וראו כל בשר</b>: ישעי' מ, ה."],["4306","613","<b>כאדה\"ר. . שהי' עקבו</b>: ראה ויק\"ר פ\"כ, ב. זהר (רע\"מ) קדושים פג, רע\"ב. הנסמן לעיל פ' שמות מ, ב."],["4307","614","<b>שהי' ראשו בבריאה</b>: נסמן לעיל פ' שמות מ, ב."],["4308","615","<b>בא\"ק אדם דבריאה</b>: ראה גם לעיל פ' בשלח קמה, ג. וש\"נ."],["4309","616","<b>עקב דא\"ק. . העשי'</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["4310","617","<b>עקבו' משיחא</b>: ראה גם לעיל פ' שמות ל, א. וש\"נ."],["4311","618","<b>וכהארץ הדום רגלי</b>: ישעי' סו, א."],["4312","619","<b>ונפש כי תחטא</b>: ויקרא ה, א."],["4313","620","<b>הנשמות. . וגיהנם</b>: ראה זהר (רע\"מ) בהעלותך קנג, א."]]],[2300550506,"ומחי' הי' האור מסתלק מן הכלי כו', וכך הוא במזון הרוחני דנה\"א והוא כמזון לחם דתורה שנק' מזון לנשמה כידוע וכמ\"ש ותורתך בתוך מעי<sup data-n=\"4314\">621</sup> ממש כו', וכלחם גשמי יסעד הלב גשמי לחבר ולחזק האור וחיות גשמי בחומר כל האברים ממוח שבראש עד הילוך הרגל כנ\"ל, כך בחי' מזון דתורה מחזק לאור וחיות האלקי' שבמוחין ומדות דנשמה שיאיר בתקפו וכח יותר כמו בחיזוק כח השכל והשגה האלקי' ובאוי\"ר כו' בכלי' דמוחא ולבא דנשמה (יותר ממה שהי' לה בעיבורו וגם בלידה (כמשי\"ת) וכן מעשה המצות שאו' אשר יעשה אותם האדם שהיא הנשמה וחי בהם מחיות האלקי' בחיזוק וכח גדול ביותר שזהו לקשר הרוחני' דאור האלקי בכלים ואברים שהעין יראה באלקות יותר ולא יסתלק אור הראי' דנשמה הרוחנית מבחי' הכלי דעין עד בחי' ההילוך ברגל (כמו שמן המאכל גשמי יתחזק גם כח ההילוך כמו דוק בככי ותשכח בניגרי<sup data-n=\"4315\">622</sup> כך מה שילכו הנשמות ברגל בעילוי אחר עילוי זהו ממזון דלחם דתו\"מ כו'. וראי' לזה ממה שא' אשרי מי שבא לכאן<sup data-n=\"4316\">623</sup> לג\"ע ותלמודו בידו שלמד בעוה\"ז בידו דוקא שנותן כח גדול בכח ההשגה שבמוח להשיג בזיו השכינה שנמשך מבינה שבמל' וכן לחזות בנועם ה' וכן בהילוך ועלי' כנ\"ל וכה\"ג). וכמו ע\"י מעשה המצוה בצדקה וחסד שביד הגשמי נמשך כח ועוז גדול לקשר ולחזק כח היד בנה\"א למעלה כמו בכח הילוך שברגל. ובכלל במה שעוסק בתורה הנגלית לשמה מתחזק כח המוחין בגדלות דנה\"א כו' ומבואר למעלה דאין חיזוק זה רק לקשר הרוחני' דצורה בחומר שיאיר כמו שהוא בעצם הבריאה שאין כל חדש בזה כלל כו', אבל זהו ענין גידול הנפש בגוף כל משך זמן קיומו שמתקיים ע\"י המזון ולא תצא הנפש מן הגוף כמו בתענית כו'. וכך הוא במזון האלקי דתורה ומצות שיחזק לנשמה בחיבור האור בכלי שהוא כל זמן משך גידול הנשמה שתהי' בצלם אלקי' ממש שיתקיים בכלי' ולא יחלש כחה ולא יכבה אורה במניעות המזון דתו' כו', והוא מה שיתחדש בחי' אור הנשמה בחומר שלה וגם בנה\"ט מדי יום ויום כמ\"ש חדשים לבקרים כו' <span data-k=\"pg\">982</span> ּ שמחמת זה מתחזק כח עבודתה במוחי' ומדות ומעשה בכל יום אע\"פ שאינו חידוש מעיקרו. אבל מזון דתו\"מ עושה התחדשות לחדש חיבור וקשר זה דאור בכלי שיהי' לו קיום בתמידי' כי צל ימינו עלי ארץ<sup data-n=\"4317\">624</sup> תאיר אור הנשמה מאור האלקי ותתקיים קיום נצחי אף בג\"ע ועוה\"ב כמשי\"ת ולא תסתלק למקורה כו' וד\"ל.\n<b>והנה</b> ענין הב' הזה מבואר למעלה שאע\"פ שאינו רק חיזוק האור בכלים מ\"מ יש בו יתרון מעלה רבה יותר מעצם הבריאה דצורה וחומר כו' כנ\"ל באריכות, ויותר מן הפרש שמקטנות דעיבור ללידה ומשינה להקיץ כו' דעיבור ולידה או",[["4314","621","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["4315","622","<b>דוק בככי ותשכח בניגרי</b>: שבת קנב, א. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תעב."],["4316","623","<b>אשרי מי שבא לכאן</b>: פסחים נ, א. ראה גם לעיל פ' שמות ה, א. וש\"נ."],["4317","624","<b>כי צל ימינו עלי ארץ</b>: איוב ח, ט."]]],[2300550520,"בשינה והקיץ אין האור בכלי רק כפי המדה בצמצום כפי הבריאה, אבל ע\"י המזון שמחזק כח עצם הנפש שיאיר כמו שהיא בכלים כמו בלימוד ומלאכה יעלה למעלה עליונה יותר מכמו שהיא בטבע הבריאה כמו בחסד שבלב שיעשה בידו יאיר תוספת אור בנפשו בכלי כמו בפעולה דאומן מדי יום כו' וכן בעוסק בחכ' בכלי מוחו בימים ושנים כו' שיקנה טבע שני בגילוי רב יותר מתחלה כנ\"ל. וכך יובן גם בנפש האלקי' באו\"כ שבה כנ\"ל דע\"י המזון דתורה למטה דוקא וע\"י מעשה המצות בצדקה ביד וכה\"ג נמשך תוס' אור רב ממקיף דנר\"נ שבה יותר מעצם הבריאה שלה בצורה וחומר או\"כ אף בלידה כו', והוא בחי' מוחין דגדלות שאדם נתגדל בכל ימי חייו באמצעות העסק בתו\"מ עד שנשלם בחכ' ומדות בימי הזקנה שנק' זקן שקנה חכ' ממקורה ובשלימות דאוי\"ר האלקי' הרבה יותר מתולדתו באוצר הנשמות בבטן המל' מאור הזרוע לצ\"ע<sup data-n=\"4318\">625</sup> כו'. וזהו כל עיקר ירידת הנשמ' למטה בעוה\"ז בכל שבעי' שנה שתתלבש בנפש הטבעי' לברר לבחי' חשמל דנוג\"ה שהיא הנפש הטבעי' בשכל ומדות שבה ע\"י תו\"מ שעושה בדברים גשמיי' דוקא, שעי\"ז יהי' גידול הנשמה בעילוי היותר עליון במוחין ומדות שלא הי' ביכולתה להגיע מצד עצמה במקור חוצבה. וזהו למען חייך<sup data-n=\"4319\">626</sup> ממש, וכן במצות וחי בהם<sup data-n=\"4320\">627</sup> מחיי החיים<sup data-n=\"4321\">628</sup> דעצמות אור א\"ס שלמעלה מע\"ס דאצי' באו\"כ דאדם כו', והיינו מבחי' מקיפי' דע\"ס שבעצמות א\"ס שלמעלה ממקור דנשמות שנולדו מיחוד זו\"נ כו'. וכל זה אינו רק מעסק התו\"מ למטה כמו כשעוסק בחכ' דתורה בגילוי בדיבור בפה א' כי על כל מוצא פי הוי'<sup data-n=\"4322\">629</sup> דתורה יחיה האדם שהוא הנשמה במקיף דחכ', וכן ע\"י התפילין בראשו בד' פרשיות ד' מקיפים דחו\"ב כו', וכן בציצית ממקיף דמל' דא\"ס, וכה\"ג בצדקה וחסד בדין צדקה נמשך מקיף דרב חסד העליון מעצמות החסד דא\"ס ממש וכה\"ג, וכמ\"ש וחי בהם מחיי החיים דא\"ס עצמו כו' (וזהו חיבור וקשר הפנימי דאו\"כ בנשמה ע\"י מזון להאיר בפנימי' ועצמי' דנשמה בפנימי' החיות באברים בתוס' מרובה בכלי כמו שהוא במקיף שאין זה באו\"כ בעצם הבריאה דנשמה כלל רק בחיצוני' התקשרות דצו\"ח כפי המדה לבד כנ\"ל). וזהו ענין העלאות נשמות ישראל למעלה אל מול פני המנורה דוקא שהוא ע\"י מצות דוקא כנ\"ל כמ\"ש להעלות נר תמיד<sup data-n=\"4323\">630</sup> (וכמשי\"ת).\n<b>ואמנם</b> מכ\"ז יובן ג\"כ למעלה בענין <span data-k=\"pg\">תצא</span> ּ הפרש שבין מצות עליונו' למעלה באדם דאצי' שנק' מצות הוי' ובין מצות שנעשה למטה בדברים גשמיי' שע\"ז א' ועשיתם כו' כאלו",[["4318","625","<b>מאור הזרוע לצ\"ע</b>: ראה גם לעיל פ' בשלח רמ, ג."],["4319","626","<b>למען חייך</b>: נצבים ל, ו."],["4320","627","<b>וחי בהם</b>: נסמן לקמן הערה 644."],["4321","628","<b>מחיי החיים</b>: ראה יומא עא, א."],["4322","629","<b>כי על כל מוצא פי הוי'</b>: עקב ח, ג. ראה גם לקמן פ' פקודי תס, א. מאמרי אדה\"א בראשית ע' תפו. וש\"נ. שמות ח\"א ע' קמה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670262\" data-slug=\"torat-chaim\" data-id=\"2300670262\">תו\"ח בראשית לז, ג</a>."],["4323","630","<b>להעלות נר תמיד</b>: תצוה כז, כ. אמור כד, ב."]]],[2300550533,"עשאוני כו' כנ\"ל, דהנה כמו שמבואר למעלה בנה\"א שיש בה בחי' עיבור ולידה ומוחי' דגדלות כו' כך הוא למעלה באדם העליון בבחי' מוחין ומדות דז\"א דאצי' (כמו בבחי' מל' שנק' שכינה<sup data-n=\"4324\">631</sup> כנ\"ל שיש בה או\"כ כמלאכים דבריאה ויצי' כו' שנק' אברי' דשכינה כך למעלה באצי' עצמו הרי נאמר כל תוארי אדם כעיני הוי' משוטטי' ל' זכר<sup data-n=\"4325\">632</sup> כו' וירא ה'<sup data-n=\"4326\">633</sup> וישמע כו' וישב הוי' הנה עומד<sup data-n=\"4327\">634</sup> כו' וכה\"ג כידוע), ובחי' האו\"כ הוא כמו בעצם התולדה בצו\"ח בנשמות פרטי' שבצלם אלקי' כו'. וזהו כמו שמדמה בציור אדם כמו חכ' מוחא חסד דרועא כו' שאין זה רק בחי' כלים מגבילים לאו\"פ שהן בחי' שמות, כמו שם ע\"ב במילוי יודי\"ן כלי לאור החכ' דז\"א וס\"ג בכלי הבינה ומדות בשם מ\"ה כו' שנק' שם התואר שמתארי' לעצם האור, שז\"ש איהו וחיוהי וגרמוהי<sup data-n=\"4328\">635</sup> באצי' וכמו ממלא כל שמהן<sup data-n=\"4329\">636</sup> מלגיו ומלבר כו', וכמ\"ש למעלה באורך דמ\"ש דאשתארו כגופא בלא כו' זהו שם המושאל וכן עיני הוי' או כמלאכים דבריאה במל' כרגלי השכינה, שהוא שם המושאל דאין לו גוף ולא דמות הגוף כמ\"ש כי לא ראיתם כל תמונה כו', אלא זהו הכל בחי' שמות וצירופי' שמגבילים לאורות דע\"ס שנאצלו מן העצמו' בצמצום גדול בבחי' קטנות דעיבור ולד כו'. כך יצאו אורות וכלים דז\"א מאימא עילאה, וכמו תולדות המדות בשכל עצמו ועד\"מ מנשמה הנברא' מאין ליש מאצי' לבריאה כך הוא מן המאציל לאצי' כו', ובחי' גדלות המוחין ומדות למעלה זהו כדמיון שיעיר אדם מן השינה כמו ויקץ כישן ה'<sup data-n=\"4330\">637</sup> כו'. ואמנם במצות עליונות כמו שמניח תפילין בראשו ועושה צדקה בידו כבי' בחסד דבדרועא ימינא כו' כמו לגמול לדלים שהיא השכינה שזהו ח\"ס דלי\"ת<sup data-n=\"4331\">638</sup> כו' הוא שמקשר הארת האורות בכלים שהן רמ\"ח אברים דמלכא למעלה באצי' ונק' מצות הוי', כמו שלמטה בנשמ' האלקי' נק' חיזוק האור בכלים כמו ע\"י מזון לחם דתורה אור ניתוסף כח המוחין דחב\"ד דז\"א כשהקב\"ה עוסק בתורה דאצי' וכן ע\"י תפילין בראשו וצדקה בידו וכה\"ג וד\"ל.\n<b>אך</b> זהו למעלה בבחי' האצי' שהוא בבחי' הרוחניות (כמקלות דיעקב שהי' יחודי' עליונים דתפילין<sup data-n=\"4332\">639</sup> למעלה וכה\"ג), והן ה\"ח המגדילי' רמ\"ח אברים דג' פעמים ט' פעמים ט' עולה רמ\"ג וה\"ח כוללי' הוא רמ\"ח<sup data-n=\"4333\">640</sup> כמ\"ש בע\"ח. אך ע\"י המצות הגשמיי' למטה מבירורי' דרפ\"ח בדברים גשמיי' עולה למעלה באו\"כ דאצי' להיות תוס' אורות בכלים הרבה יותר, כמו שעולה ת\"ת דאדם במוחי' עליונים כמו בחצות דאצית לקלא דאורייתא<sup data-n=\"4334\">641</sup> וכמו יושב ושונה כנגד הקורא בתורה<sup data-n=\"4335\">642</sup> הנגלית דוקא ומזה",[["4324","631","<b>מל' שנק' שכינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310057\" data-slug=\"tanya\" data-id=\"3401310057\">תניא</a> רפנ\"ב. הנסמן לעיל פ' שמות א, ד."],["4325","632","<b>כעיני הוי' משוטטי' ל' זכר</b>: ראה זהר (סבא) משפטים קז, א. ויחי רמא, סע\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370068\" data-slug=\"torah-or\" data-id=\"3901370068\">תו\"א וירא טו, ב</a>. אוה\"ת וירא (כרך ד) ע' 1472."],["4326","633","<b>וירא ה'</b>: בראשית ו, ה."],["4327","634","<b>הנה עומד</b>: ראה לעיל פ' בשלח קסה, ג הערה 85. רלב, ג הערה 682. לקמן הערה 740."],["4328","635","<b>איהו וחיוהי וגרמוהי</b>: ראה ת\"ז בהקדמה (ג, ב)."],["4329","636","<b>ממלא כל שמהן</b>: ת\"ז בהקדמה (יז, ב)."],["4330","637","<b>ויקץ כישן ה'</b>: תהלים עח, סה."],["4331","638","<b>ח\"ס דלי\"ת</b>: ראה גם לעיל פ' יתרו רנט, ג ובהערה 148."],["4332","639","<b>כמקלות דיעקב. . דתפילין</b>: זהר (סתרי תורה) ויצא קסב, א. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670576\" data-slug=\"torat-chaim\" data-id=\"2300670576\">תו\"ח בראשית מה, ד</a> הערה 45."],["4333","640","<b>דג' פעמים ט'. . וה\"ח. . רמ\"ח</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד, פ\"ו. הנסמן בשע\"ת מב, ב הערה 13."],["4334","641","<b>בחצות דאצית לקלא דאורייתא</b>: ראה זהר ויקרא יג, א. נח עב, א. לך צב, א. פינחס ריג, א."],["4335","642","<b>יושב ושונה כנגד הקורא בתורה</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג הערה 18."]]]]});
